import{S as a}from"./index-CxaWkr2C.js";a.thianHockKeng.src,a.thianHockKeng.credit;const i={title:["Thian Hock Keng,","the sailors’","temple"],subtitle:"天福宫 · Telok Ayer Street · Hokkien",video:{title:"A temple once on the sea",duration:115,captions:["Thian Hock Keng is a Hokkien temple to Mazu.","Mazu is the goddess of the sea.","Sailors gave thanks here after the voyage from China.","Land reclamation later moved the sea away."]},thenNow:{then:a.thianHockKeng1890,now:a.thianHockKeng2006,sliderLabel:"Compare the temple in 1890 and 2006",captions:{then:{lead:"c.1890.",text:" A rickshaw waits outside the temple on an unpaved Telok Ayer Street."},mid:{lead:"Same corner, 116 years apart.",text:" The roofline, ridge dragons and side gate still line up."},now:{lead:"2006.",text:" The same front, with office blocks now rising behind the roofs."}}},lead:"Thian Hock Keng is a Hokkien temple to Mazu, the sea goddess, built from 1839 to 1842 on Telok Ayer Street.",more:["It once stood on the shoreline. Sailors arriving from China came here to give thanks for a safe voyage.","The halls were built with traditional joinery, without nails. It was gazetted as a national monument in 1973."],lookFor:[{icon:"roof",text:"Dragons on the curved roof ridges"},{icon:"joinery",text:"Timber joinery with no nails"}],next:{thumb:a.lanterns.src,credit:a.lanterns.credit}};a.plan1822.src,a.plan1822.credit;a.plan1822.src,a.plan1822.credit,a.pagodaStreet.src,a.pagodaStreet.credit;const g={"curated:sg-a-noodle-story":{title:["A Noodle Story,","Singapore-style ramen"],subtitle:"Amoy Street Food Centre · Singapore-style ramen",lead:"A Noodle Story serves Singapore-style ramen at Amoy Street Food Centre. Gwern Khoo and Ben Tham opened it on 17 February 2013; Khoo had cooked at the restaurants Waku Ghin and Iggy’s.",more:["Khoo saw a hawker stall as a low-cost way to test his ideas. The bowl brings together springy noodles, wanton, Japanese-style cha shu and an onsen egg.","By 2018 the stall sold about 200 bowls a day and had been on the MICHELIN Bib Gourmand list. In 2021 a second outlet opened in Guoco Tower."],lookFor:["Stall #01-39 on the first floor","Wanton, cha shu and an onsen egg in one bowl"],sources:[{title:"A Noodle Story: Singapore hawkerpreneur",url:"https://vulcanpost.com/617948/a-noodle-story-singapore-hawkerpreneur/",publisher:"Vulcan Post",checkedAt:"2026-10-29"},{title:"A Noodle Story",url:"https://en.wikipedia.org/wiki/A_Noodle_Story",publisher:"Wikipedia",checkedAt:"2026-10-29"}],clip:{title:"Fine dining to hawker stall",seconds:90,captions:["Two cooks opened this stall at Amoy Street in 2013.","Gwern Khoo had cooked at Waku Ghin and Iggy’s.","Their ramen has wanton, cha shu and an onsen egg.","By 2018 they sold about 200 bowls a day."],poster:{src:"nearby/cards/sg-a-noodle-story.webp",alt:"The A Noodle Story stall, #01-39, with its lit menu boards and customers ordering",credit:"Mx. Granger 2024 · CC0",url:"https://commons.wikimedia.org/wiki/File:A_Noodle_Story.jpg"}},tiles:[{value:2013,label:"stall opens",source:{title:"A Noodle Story: Singapore hawkerpreneur",url:"https://vulcanpost.com/617948/a-noodle-story-singapore-hawkerpreneur/",publisher:"Vulcan Post",checkedAt:"2026-10-29"}},{value:200,label:"bowls a day (about, 2018)",source:{title:"A Noodle Story: Singapore hawkerpreneur",url:"https://vulcanpost.com/617948/a-noodle-story-singapore-hawkerpreneur/",publisher:"Vulcan Post",checkedAt:"2026-10-29"}},{value:2021,label:"Guoco Tower outlet",source:{title:"A Noodle Story",url:"https://en.wikipedia.org/wiki/A_Noodle_Story",publisher:"Wikipedia",checkedAt:"2026-10-29"}}],reviewedAt:"2026-10-29"},"curated:sg-al-abrar-mosque":{title:["Al-Abrar Mosque,","the hut mosque","of Telok Ayer"],subtitle:"Telok Ayer Street · mosque",lead:"Al-Abrar Mosque on Telok Ayer Street is one of Singapore's oldest mosques. It was founded in 1827 by Chulias, Muslim migrants from the Coromandel Coast of South India.",more:['It began as a small thatched hut, so it was nicknamed Kuchu Palli, "hut mosque" in Tamil. Many Chulias were traders and moneychangers, and the mosque was also their meeting place. The present brick mosque was built between 1850 and 1855.',"It sits in a row of shophouses, three shophouses wide, and its front takes in the five-foot way. Two tall octagonal minarets, each topped with a crescent moon and a star, mark it out. Office workers from nearby come to pray, especially on Fridays."],lookFor:["Two octagonal minarets with crescent and star","The five-foot way running across the front","Notched cresting along the roofline"],sources:[{title:"Al-Abrar Mosque",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/al-abrar-mosque",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"},{title:"Masjid Al-Abrar",url:"https://en.wikipedia.org/wiki/Masjid_Al-Abrar",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"The hut mosque",seconds:90,captions:["This mosque began in 1827 as a small thatched hut.",'Its Tamil nickname, Kuchu Palli, means "hut mosque".',"The brick mosque was begun in 1850 and finished in 1855.","Two octagonal minarets rise above a row of shophouses."]},tiles:[{value:1827,label:"mosque founded",source:{title:"Al-Abrar Mosque",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/al-abrar-mosque",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:1855,label:"brick mosque finished",source:{title:"Al-Abrar Mosque",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/al-abrar-mosque",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:1974,label:"national monument",source:{title:"Masjid Al-Abrar",url:"https://en.wikipedia.org/wiki/Masjid_Al-Abrar",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-albert-centre-market-food-centre":{title:["Albert Centre,","market and food centre","on Queen Street"],subtitle:"Queen Street · wet market and hawker centre",lead:"Albert Centre on Queen Street is one of the earliest cooked food centres in Singapore. It has 86 food stalls and 148 market stalls.",more:["In the 1970s and early 1980s, Albert Street next door was a popular open-air dining area with lively shophouse bars. When the area was rebuilt in the mid-1980s, most of the food stalls moved to the hawker centre at the nearby Albert Complex.","The centre closed for renovation in February 2025 and reopened on 5 May 2025, airier and brighter. The food centre is on Level 1; dried goods and sundry stalls are on Level 3. Many people come here after praying at the temples on Waterloo Street."],lookFor:["Cooked food stalls on Level 1","Dried goods and sundry stalls on Level 3","Anthony Indonesian Cuisine’s nasi padang queue"],sources:[{title:"Albert Centre Market & Food Centre to undergo 3-month renovation",url:"https://mothership.sg/2025/01/albert-food-centre-bugis-renovation/",publisher:"Mothership",checkedAt:"2026-10-31"},{title:"Albert Centre Market & Food Centre reopens after 3 month renovation",url:"https://sethlui.com/albert-centre-market-food-centre-reopens-bugis-singapore-may-2025/",publisher:"Seth Lui",checkedAt:"2026-10-31"},{title:"Street hawker stalls along Albert Street",url:"https://www.roots.gov.sg/Collection-Landing/listing/1161770",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}],clip:{title:"From street stalls to a centre",seconds:90,captions:["Albert Centre is a market and hawker centre in one building.","Albert Street nearby was once a busy open-air place to eat.","In the mid-1980s most of its food stalls moved indoors here.","Today there are 86 food stalls and 148 market stalls."]},tiles:[{value:86,label:"cooked food stalls",grouped:!0,source:{title:"Albert Centre Market & Food Centre to undergo 3-month renovation",url:"https://mothership.sg/2025/01/albert-food-centre-bugis-renovation/",publisher:"Mothership",checkedAt:"2026-10-31"}},{value:148,label:"market stalls",grouped:!0,source:{title:"Albert Centre Market & Food Centre to undergo 3-month renovation",url:"https://mothership.sg/2025/01/albert-food-centre-bugis-renovation/",publisher:"Mothership",checkedAt:"2026-10-31"}},{value:2025,label:"reopens after renovation",source:{title:"Albert Centre Market & Food Centre reopens after 3 month renovation",url:"https://sethlui.com/albert-centre-market-food-centre-reopens-bugis-singapore-may-2025/",publisher:"Seth Lui",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-alkaff-bridge":{title:["Alkaff Bridge,","a footbridge","painted with circles"],subtitle:"Robertson Quay · painted footbridge",lead:"Alkaff Bridge is a steel footbridge over the Singapore River at Robertson Quay. It is 55 metres long and shaped like a tongkang, a light boat once used to carry goods on the river.",more:["It stands near the former Alkaff Quay, named after the Alkaffs, an Arab family who were among the wealthiest in Singapore in the early 20th century.","In January 2004 the Filipino artist Pacita Abad and a team of rope specialists painted the bridge, using 2,350 circle stencils. She called it her gift to the people of Singapore. The repainted bridge was launched again on 12 July 2019."],lookFor:["Bright circles painted all over the beams","The boat-like curve of the steel frame","Circles hand-painted on the railings"],sources:[{title:"Alkaff Bridge",url:"https://en.wikipedia.org/wiki/Alkaff_Bridge",publisher:"Wikipedia",checkedAt:"2026-10-31"},{title:"Launch of Pacita's Restored Painted Bridge",url:"https://pacitaabad.com/events/5/",publisher:"Pacita Abad Art Estate",checkedAt:"2026-10-31"}],clip:{title:"A bridge of circles",seconds:90,captions:["A 55-metre steel footbridge crosses the river at Robertson Quay.","It is shaped like a tongkang, a light boat that carried goods.","In 2004 artist Pacita Abad covered it in painted circles.","Repainted in 2019, it still links the two banks for walkers."],poster:{src:"nearby/cards/sg-alkaff-bridge.webp",alt:"Alkaff Bridge, a steel footbridge covered in painted circles, over the Singapore River",credit:"Walmaul 2025 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Alkaff_Bridge.jpg"}},tiles:[{value:55,label:"long",suffix:" m",source:{title:"Alkaff Bridge",url:"https://en.wikipedia.org/wiki/Alkaff_Bridge",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:2004,label:"painted by Pacita Abad",source:{title:"Alkaff Bridge",url:"https://en.wikipedia.org/wiki/Alkaff_Bridge",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:2350,label:"circle stencils",grouped:!0,source:{title:"Alkaff Bridge",url:"https://en.wikipedia.org/wiki/Alkaff_Bridge",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-allauddin-s-briyani":{title:["Allauddin's Briyani,","a family stall","at Tekka"],subtitle:"Tekka Centre · hawker stall, briyani",lead:"Allauddin's Briyani is a family stall in Tekka Centre, the hawker centre and wet market at the edge of Little India. It is now run by the second-generation owner, Haji Mohamed.",more:["Diners choose chicken, fried chicken, mutton, fried fish or egg briyani. The mutton set comes with an egg and papadum. The stall has a MICHELIN Plate.","Tekka Centre opened in 1982 and was called Zhujiao Centre until 2000. It closed for a big renovation in 2008 and reopened in 2009."],lookFor:["Stall #01-229 on the ground floor","Mutton briyani set with egg and papadum","The wet market next to the food stalls"],order:"kopi",sources:[{title:"The 10 best Nasi Biryani places in Singapore",url:"https://www.herworld.com/life/the-10-best-nasi-biryani-places-in-singapore",publisher:"Her World",checkedAt:"2026-10-31"},{title:"Tekka Centre Food Guide",url:"https://eatbook.sg/tekka-centre/",publisher:"Eatbook",checkedAt:"2026-10-31"},{title:"Tekka Centre",url:"https://en.wikipedia.org/wiki/Tekka_Centre",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"Briyani at Tekka",seconds:85,captions:["A family briyani stall in Tekka Centre.","The second generation, Haji Mohamed, now runs it.","A mutton set comes with egg and papadum.","Find it at stall #01-229, open from 8am."],poster:{src:"nearby/cards/sg-allauddin-s-briyani.webp",alt:"The purple main entrance of Tekka Centre with its name sign, where the stall is (not the stall itself)",credit:"Kbseah 2025 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Tekka_Centre_entrance,_evening.jpg"}},tiles:[{value:1982,label:"Tekka Centre opens",source:{title:"Tekka Centre",url:"https://en.wikipedia.org/wiki/Tekka_Centre",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:2e3,label:"renamed Tekka Centre",source:{title:"Tekka Centre",url:"https://en.wikipedia.org/wiki/Tekka_Centre",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:2009,label:"reopens after renovation",source:{title:"Tekka Centre",url:"https://en.wikipedia.org/wiki/Tekka_Centre",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-anderson-bridge":{title:["Anderson Bridge,","steel arches","at the river mouth"],subtitle:"Singapore River · steel truss bridge, now for walkers",lead:"Anderson Bridge was built to ease the heavy traffic on Cavenagh Bridge. It was officially opened in 1910 and named after Sir John Anderson, Governor of the Straits Settlements from 1904 to 1911.",more:["Municipal Engineer Robert Peirce and his assistant D. M. Martia designed it. It is a steel truss bridge: the steelwork was made in Britain and shipped to Singapore. Electric trams once ran across it.","In 2019 it became a National Monument together with Cavenagh and Elgin Bridges, as the Singapore River Bridges. At the end of 2021 it was closed to cars and became a bridge for walkers."],lookFor:["Granite archways and fluted piers at each end","The Aswan stone, facing Victoria Memorial Hall","Cast-iron latticework along the sides"],sources:[{title:"Singapore River Bridges: Cavenagh Bridge, Anderson Bridge and Elgin Bridge",url:"https://www.roots.gov.sg/places/places-landing/places/national-monuments/singapore-river-bridges",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"},{title:"Anderson Bridge (Singapore)",url:"https://en.wikipedia.org/wiki/Anderson_Bridge_(Singapore)",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"A second bridge for the river",seconds:90,captions:["Anderson Bridge crosses the Singapore River near its mouth.","It opened in 1910 to take traffic off the busy Cavenagh Bridge.","A granite stone from Aswan, Egypt, is fixed to its middle girder.","Since the end of 2021 it has been a bridge for people, not cars."],poster:{src:"nearby/cards/anderson-bridge.webp",alt:"Anderson Bridge's white steel arches over the Singapore River, seen from above",credit:"Zairon 2015 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Singapore_Anderson_Bridge_viewed_from_The_Stamford_2.jpg"}},tiles:[{value:1910,label:"officially opened",source:{title:"Singapore River Bridges: Cavenagh Bridge, Anderson Bridge and Elgin Bridge",url:"https://www.roots.gov.sg/places/places-landing/places/national-monuments/singapore-river-bridges",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:70,label:"total length",suffix:" m",source:{title:"Anderson Bridge (Singapore)",url:"https://en.wikipedia.org/wiki/Anderson_Bridge_(Singapore)",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:2019,label:"national monument",source:{title:"Singapore River Bridges: Cavenagh Bridge, Anderson Bridge and Elgin Bridge",url:"https://www.roots.gov.sg/places/places-landing/places/national-monuments/singapore-river-bridges",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}}],thenNow:{then:{src:"nearby/cards/anderson-bridge-then.webp",alt:"Anderson Bridge around 1930, its dark steel arches and granite gateway seen from the river",credit:"Unknown photographer, c.1930 (KITLV 104800) · CC BY 4.0",url:"https://commons.wikimedia.org/wiki/File:Anderson_Bridge_te_Singapore,_KITLV_104800.tiff"},now:{src:"nearby/cards/anderson-bridge-now.webp",alt:"Anderson Bridge in 2023, painted white, with office towers behind",credit:"Ralff Nestor Nacor 2023 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Anderson_Bridge,_Singapore,_August_2023.jpg"},thenLabel:"c.1930",nowLabel:"2023",captions:{then:{lead:"c.1930.",text:" Dark steel arches and a granite gateway over the river."},mid:{lead:"Same bridge, about 90 years apart.",text:" The arches still carry it."},now:{lead:"2023.",text:" Painted white, with office towers behind."}}},reviewedAt:"2026-10-29"},"curated:sg-anju":{title:["Anju,","Korean dishes","made for drinking"],subtitle:"Tras Street · modern Korean dining and bar",lead:"Anju is a modern Korean restaurant and bar on Tras Street. Anju is the Korean word for dishes served with alcohol.",more:["The restaurant imports bottles directly from Korean distilleries. Its aim is to show Korean drinks beyond soju, some of them new even to Koreans, with a modern menu by head chef Kim to match.","Tras Street was named in 1898 after Tras, a small town in Pahang. The Hong San See temple was first built here in 1836 and moved to Mohamed Sultan Road after a road project in 1907."],lookFor:["Two- and three-storey shophouses on Tras Street","The bars that make the street a night spot"],sources:[{title:"About",url:"https://anju.com.sg/sub/about.html",publisher:"ANJU",checkedAt:"2026-10-29"},{title:"Tras Street",url:"https://en.wikipedia.org/wiki/Tras_Street",publisher:"Wikipedia",checkedAt:"2026-10-29"}],clip:{title:"Beyond the green bottle",seconds:90,captions:["Anju is the Korean word for dishes served with alcohol.","Its drinks come straight from Korean distilleries.","The aim: Korean drinks beyond soju, new even to some Koreans.","Tras Street, named in 1898 after a Malayan town, is full of bars."],poster:{src:"nearby/cards/anju.webp",alt:"Restored shophouses on Tras Street, the street where Anju is (not the restaurant itself)",credit:"Bjoertvedt 2018 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Singapore_-_Outram_-_Tras_Street_IMG_9205.jpg"}},tiles:[{value:1836,label:"Hong San See built here",source:{title:"Tras Street",url:"https://en.wikipedia.org/wiki/Tras_Street",publisher:"Wikipedia",checkedAt:"2026-10-29"}},{value:1898,label:"Tras Street named",source:{title:"Tras Street",url:"https://en.wikipedia.org/wiki/Tras_Street",publisher:"Wikipedia",checkedAt:"2026-10-29"}},{value:1907,label:"temple moved away",source:{title:"Tras Street",url:"https://en.wikipedia.org/wiki/Tras_Street",publisher:"Wikipedia",checkedAt:"2026-10-29"}}],reviewedAt:"2026-10-29"},"curated:sg-ann-chin-handmade-popiah":{title:["Ann Chin,","popiah skins","made by hand"],subtitle:"Chinatown Complex · popiah",lead:"Ann Chin Handmade Popiah sells popiah: a soft, thin wheat-flour skin rolled around a filling. The brand began when Lim Kam Chwee spent his savings on a pushcart; in 1958 he set up shop in Orh Kio, now Upper Thomson Road.",more:["It is still a family business. Third-generation leader Pamela runs it with her mother, Wendy Lim. In 2024 Vulcan Post counted 13 stores, and close to a million rolls sold in 2023.","The MICHELIN Guide singled out this Chinatown Complex stall, where the skins are made by hand on the premises. The filling has turnip, lettuce, bean sprouts, egg and crushed peanuts."],lookFor:["Stall #02-112 on the food centre floor","Turnip, bean sprouts and crushed peanuts inside","Fried spring rolls sold alongside"],sources:[{title:"Ann Chin Popiah: brand history, founder and growth",url:"https://vulcanpost.com/851478/ann-chin-popiah-singapore-brand-history-founder-growth",publisher:"Vulcan Post",checkedAt:"2026-10-29"},{title:"Chinatown Complex popiah",url:"https://ordinarypatrons.com/2017/03/22/chinatown-complex-popiah",publisher:"Ordinary Patrons (food blog)",checkedAt:"2026-10-29"},{title:"Popiah",url:"https://en.wikipedia.org/wiki/Popiah",publisher:"Wikipedia",checkedAt:"2026-10-29"}],clip:{title:"A thin pancake roll",seconds:90,captions:["Popiah means “thin flatbread” in Hokkien.","Lim Kam Chwee spent his savings on a pushcart, Ann Chin.","In 1958 he set up shop in Orh Kio, now Upper Thomson Road.","At this stall the skins are still made by hand."],poster:{src:"nearby/cards/sg-ann-chin-handmade-popiah.webp",alt:"Two popiah rolls cut into pieces on a plate in Singapore (not from this stall)",credit:"Mimasiki 2020 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Singapore_stuffed_pancake.jpg"}},tiles:[{value:1958,label:"shop opens in Orh Kio",source:{title:"Ann Chin Popiah: brand history, founder and growth",url:"https://vulcanpost.com/851478/ann-chin-popiah-singapore-brand-history-founder-growth",publisher:"Vulcan Post",checkedAt:"2026-10-29"}},{value:13,label:"stores in 2024",source:{title:"Ann Chin Popiah: brand history, founder and growth",url:"https://vulcanpost.com/851478/ann-chin-popiah-singapore-brand-history-founder-growth",publisher:"Vulcan Post",checkedAt:"2026-10-29"}},{value:1,label:"rolls sold in 2023 (nearly)",source:{title:"Ann Chin Popiah: brand history, founder and growth",url:"https://vulcanpost.com/851478/ann-chin-popiah-singapore-brand-history-founder-growth",publisher:"Vulcan Post",checkedAt:"2026-10-29"},suffix:"M"}],reviewedAt:"2026-10-29"},"curated:sg-armenian-church-of-saint-gregory-the-illuminator":{title:["The Armenian Church,","Singapore’s oldest","Christian church"],subtitle:"Hill Street · Armenian Apostolic church",lead:"The Armenian Church on Hill Street is Singapore’s oldest Christian church. The small Armenian community laid its foundation stone on 1 January 1835, and the church was consecrated at Easter 1836.",more:["George D. Coleman designed it in the plan of a cross, with Doric columns and a triangular pediment on each of its four arms. The first bell turret was replaced in 1847, and again in 1853 by the belfry you see now. Inside, the church is round, a design not found in other churches in Singapore.","Armenians such as Agnes Joaquim, who bred the orchid Vanda Miss Joaquim, and the Sarkies brothers of Raffles Hotel belonged to this community. The last resident priest left in the 1930s. Agnes Joaquim’s tombstone now stands in the church’s Garden of Memories."],lookFor:["Doric columns and a pediment on all four arms","Old pews with woven rattan backs","Agnes Joaquim’s tombstone in the Garden of Memories"],sources:[{title:"Armenian Apostolic Church of Saint Gregory the Illuminator",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/armenian-apostolic-church-of-saint-gregory-the-illuminator",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"},{title:"Armenian Church, Singapore",url:"https://en.wikipedia.org/wiki/Armenian_Church,_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"Twelve families, one church",seconds:90,captions:["This white church is Singapore’s oldest Christian church.","Armenian traders laid its foundation stone on 1 January 1835.","Its belfry was rebuilt twice; today’s one dates from 1853.","Inside, the church is round, unlike any other here."]},tiles:[{value:1835,label:"foundation stone laid",source:{title:"Armenian Apostolic Church of Saint Gregory the Illuminator",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/armenian-apostolic-church-of-saint-gregory-the-illuminator",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:1836,label:"church consecrated",source:{title:"Armenian Apostolic Church of Saint Gregory the Illuminator",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/armenian-apostolic-church-of-saint-gregory-the-illuminator",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:1973,label:"national monument",source:{title:"Armenian Church, Singapore",url:"https://en.wikipedia.org/wiki/Armenian_Church,_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-artscience-museum":{title:["ArtScience Museum,","a lotus","by the bay"],subtitle:"Bayfront Avenue · museum of art, science and technology",lead:"The ArtScience Museum at Marina Bay Sands opened on 17 February 2011. Its exhibitions blend art, science, culture and technology.",more:["Moshe Safdie designed it. Its shape is often compared to a lotus flower: a round base with ten 'fingers' reaching up, with skylights at the fingertips. The outside is fibre-reinforced plastic on a steel frame.","Most shows are touring exhibitions from other museums. The only permanent exhibition is Future World, made with the art group teamLab, in the Basement 2 galleries."],lookFor:["Ten curved 'fingers' rising from a round base","Skylights at the tips of the fingers"],sources:[{title:"ArtScience Museum",url:"https://en.wikipedia.org/wiki/ArtScience_Museum",publisher:"Wikipedia",checkedAt:"2026-10-31"},{title:"Marina Bay Sands",url:"https://en.wikipedia.org/wiki/Marina_Bay_Sands",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"Ten fingers to the sky",seconds:90,captions:["This museum mixes art, science, culture and technology.","Prime Minister Lee Hsien Loong opened it on 17 February 2011.","Its ten 'fingers' rise from a round base; the tallest is 60 m.","Downstairs, teamLab's Future World is its one permanent show."]},tiles:[{value:2011,label:"museum opens",source:{title:"ArtScience Museum",url:"https://en.wikipedia.org/wiki/ArtScience_Museum",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:10,label:"'fingers' on the roof",source:{title:"ArtScience Museum",url:"https://en.wikipedia.org/wiki/ArtScience_Museum",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:60,label:"tallest finger",suffix:" m",source:{title:"Marina Bay Sands",url:"https://en.wikipedia.org/wiki/Marina_Bay_Sands",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-asia-square":{title:["Asia Square,","two glass towers","at Marina Bay"],subtitle:"Marina View · office towers with a hotel",lead:"Asia Square is an office and retail development on Marina View. Tower 1, with 43 floors, opened on 8 November 2011, and Tower 2, with 46 floors, opened on 19 November 2013.",more:["It was Singapore's first office development with a business hotel built in: The Westin Singapore, in Tower 2. A landscaped plaza of about 9,300 m², The Cube, links the two towers.","It has green features such as solar panels on the roof and a bio-diesel plant, and it holds LEED Platinum and Green Mark Platinum awards."],lookFor:["The Cube, the plaza between the two towers","The ground-level link to Shenton Way MRT"],sources:[{title:"Asia Square",url:"https://en.wikipedia.org/wiki/Asia_Square",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"Offices with a hotel inside",seconds:90,captions:["Asia Square is two glass office towers on Marina View.","Tower 1 opened in 2011, and Tower 2 followed in 2013.","Tower 2 holds a hotel, The Westin Singapore.","A landscaped plaza, The Cube, links the two towers."]},tiles:[{value:2011,label:"Tower 1 opens",source:{title:"Asia Square",url:"https://en.wikipedia.org/wiki/Asia_Square",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:2013,label:"Tower 2 opens",source:{title:"Asia Square",url:"https://en.wikipedia.org/wiki/Asia_Square",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:46,label:"floors in Tower 2",source:{title:"Asia Square",url:"https://en.wikipedia.org/wiki/Asia_Square",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-asian-civilisations-museum":{title:["Asian Civilisations Museum,","Asia's story","by the river"],subtitle:"Empress Place · museum of Asian art and history",lead:"The Asian Civilisations Museum shows the material cultures of China, Southeast Asia, South Asia and West Asia. Since 2003 it has filled the Former Empress Place Building at the mouth of the Singapore River.",more:["Colonial Engineer Major John F. A. McNair designed the building, and convicts built it. Work began in June 1864 and ended in December 1867. Almost the whole colonial government worked here, so it was simply called Government Offices. The name Empress Place came in 1907, in memory of Queen Victoria.","The Tang Shipwreck gallery shows the cargo of an Arab ship that sank nearly 1,100 years ago and was found by chance in 1998. More than 50,000 hand-painted bowls from Changsha, China, were found in the wreck."],lookFor:["Rows of Doric columns in the high-ceilinged rooms","Tall French windows, made to keep rooms cool","Changsha bowls in the Tang Shipwreck gallery"],sources:[{title:"Former Empress Place Building (now Asian Civilisations Museum)",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/former-empress-place-building-now-asian-civilisations-museum",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"},{title:"Tang Shipwreck",url:"https://www.nhb.gov.sg/acm/galleries/maritime-trade/tang-shipwreck",publisher:"Asian Civilisations Museum (National Heritage Board)",checkedAt:"2026-10-31"},{title:"Asian Civilisations Museum",url:"https://en.wikipedia.org/wiki/Asian_Civilisations_Museum",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"From offices to a museum",seconds:95,captions:["This museum shows art and history from across Asia.","Its building was finished in 1867 as government offices.","Convicts built it to a design by Major J. F. A. McNair.","Inside, see the cargo of a ship that sank 1,100 years ago."]},tiles:[{value:1867,label:"building completed",source:{title:"Former Empress Place Building (now Asian Civilisations Museum)",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/former-empress-place-building-now-asian-civilisations-museum",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:2003,label:"museum moves in",source:{title:"Former Empress Place Building (now Asian Civilisations Museum)",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/former-empress-place-building-now-asian-civilisations-museum",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:5e4,label:"bowls found in the wreck",suffix:"+",grouped:!0,source:{title:"Tang Shipwreck",url:"https://www.nhb.gov.sg/acm/galleries/maritime-trade/tang-shipwreck",publisher:"Asian Civilisations Museum (National Heritage Board)",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-biopolis":{title:["Biopolis,","seven science buildings","by Zaha Hadid"],subtitle:"one-north · biomedical research campus",lead:"Biopolis is a campus for biomedical research and development at one-north. Government agencies, research institutes and company labs work side by side here.",more:["Phase 1, designed by Zaha Hadid, is a group of seven buildings: Nanos, Genome, Helios, Chromos, Proteos, Matrix and Centros. They were built between June 2003 and March 2004 for S$500 million.","The campus kept growing: Neuros and Immunos in 2006, Synapse and Amnios in 2011, and a Procter & Gamble innovation centre in 2014. For the public there are shops, restaurants, cafés and a 300-seat food court."],lookFor:["Building names like Helios, Matrix and Centros","The food court and cafés, open to the public"],sources:[{title:"Biopolis",url:"https://en.wikipedia.org/wiki/Biopolis",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"A campus for life sciences",seconds:85,captions:["Biopolis is a campus for biomedical research at one-north.","Zaha Hadid designed its first seven buildings.","They went up between June 2003 and March 2004.","Cafés and a 300-seat food court are open to the public."],poster:{src:"nearby/cards/biopolis.webp",alt:"Glass sky bridges link the tall buildings of Biopolis, seen from the street below",credit:"Henry Leong Him Woh 2008 · CC BY-SA 2.0",url:"https://commons.wikimedia.org/wiki/File:Biopolis-Singapore-20080712.jpg"}},tiles:[{value:2004,label:"first phase completed",source:{title:"Biopolis",url:"https://en.wikipedia.org/wiki/Biopolis",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:7,label:"buildings in phase 1",source:{title:"Biopolis",url:"https://en.wikipedia.org/wiki/Biopolis",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:2014,label:"P&G innovation centre opens",source:{title:"Biopolis",url:"https://en.wikipedia.org/wiki/Biopolis",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-bismillah-biryani":{title:["Bismillah Biryani,","dum biryani","on Dunlop Street"],subtitle:"Dunlop Street · biryani restaurant",lead:"Bismillah Biryani serves dum biryani at 50 Dunlop Street in Little India. Its chef-owner is Arif Salahuddin.",more:["The MICHELIN Guide gave it a Bib Gourmand every year from 2016 to 2023, except 2020: seven in all. By 2023 it had three other outlets in Singapore.","Besides chicken dum biryani, served with a boiled egg, the menu has lamb shank biryani, samosas and kebabs."],lookFor:["50 Dunlop Street, near Jalan Besar MRT","Lamb shank or chicken dum biryani","Kebabs and samosas"],sources:[{title:"Bismillah Biryani: Michelin Bib Gourmand Briyani In Jalan Besar",url:"https://eatbook.sg/bismillah-biryani/",publisher:"Eatbook",checkedAt:"2026-10-31"},{title:"Bismillah Biryani",url:"https://danielfooddiary.com/2017/07/12/bismillahbiryani/",publisher:"Daniel Food Diary",checkedAt:"2026-10-31"}],clip:{title:"Biryani on Dunlop Street",seconds:90,captions:["A biryani restaurant at 50 Dunlop Street.","Chef-owner Arif Salahuddin cooks dum biryani.","Its menu runs from chicken dum to lamb shank biryani.","It held a MICHELIN Bib Gourmand from 2016."],poster:{src:"nearby/cards/sg-bismillah-biryani.webp",alt:"Dunlop Street in Little India, a row of old shophouses and parked cars (the street, not the restaurant itself)",credit:"Orderinchaos 2016 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Little_India_-_Dunlop_W_from_Madras.jpg"}},tiles:[{value:2016,label:"first Bib Gourmand",source:{title:"Bismillah Biryani: Michelin Bib Gourmand Briyani In Jalan Besar",url:"https://eatbook.sg/bismillah-biryani/",publisher:"Eatbook",checkedAt:"2026-10-31"}},{value:7,label:"Bib Gourmands to 2023",source:{title:"Bismillah Biryani: Michelin Bib Gourmand Briyani In Jalan Besar",url:"https://eatbook.sg/bismillah-biryani/",publisher:"Eatbook",checkedAt:"2026-10-31"}},{value:3,label:"other outlets (2023)",source:{title:"Bismillah Biryani: Michelin Bib Gourmand Briyani In Jalan Besar",url:"https://eatbook.sg/bismillah-biryani/",publisher:"Eatbook",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-boat-quay":{title:["Boat Quay,","the belly of the carp"],subtitle:"Singapore River · riverside shophouses",lead:"Boat Quay is the row of old shophouses and warehouses on the south bank of the Singapore River, near its mouth. It was once the busiest part of the old port.",more:[`In 1823 a small hill at Battery Road was levelled, and the earth was used to fill the swampy south bank. Merchants built warehouses, offices and their own jetties here. The Chinese called it the "belly of the carp", because good fortune is said to live in a fish's belly.`,"By 1983 the last boats had moved to Pasir Panjang so that the river could be cleaned. Boat Quay became a conservation area on 7 July 1989, and its shophouses now hold restaurants and bars."],lookFor:["Two- and three-storey shophouses facing the river","Granite edging along the five-foot way","Bumboats working as river taxis"],sources:[{title:"Boat Quay Conservation Area",url:"https://www.ura.gov.sg/conservation/find-a-building/conservation-portal/btqy/",publisher:"Urban Redevelopment Authority (URA)",checkedAt:"2026-10-31"},{title:"Boat Quay",url:"https://en.wikipedia.org/wiki/Boat_Quay",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"The belly of the carp",seconds:90,captions:["Boat Quay lines a wide bend on the south bank of the river.","In 1823 earth from a levelled hill filled in the swampy bank.","In the 1860s it handled three-quarters of all shipping business.","Restored shophouses now hold restaurants and bars by the water."]},tiles:[{value:1823,label:"swampy bank filled in",source:{title:"Boat Quay Conservation Area",url:"https://www.ura.gov.sg/conservation/find-a-building/conservation-portal/btqy/",publisher:"Urban Redevelopment Authority (URA)",checkedAt:"2026-10-31"}},{value:1e5,label:"people on the river, 1890",suffix:"+",grouped:!0,source:{title:"Boat Quay Conservation Area",url:"https://www.ura.gov.sg/conservation/find-a-building/conservation-portal/btqy/",publisher:"Urban Redevelopment Authority (URA)",checkedAt:"2026-10-31"}},{value:1989,label:"conservation area",source:{title:"Boat Quay Conservation Area",url:"https://www.ura.gov.sg/conservation/find-a-building/conservation-portal/btqy/",publisher:"Urban Redevelopment Authority (URA)",checkedAt:"2026-10-31"}}],thenNow:{then:{src:"nearby/cards/sg-boat-quay-then.webp",alt:"Old photo of boats packed along the river at Boat Quay, with shophouses on the far bank",credit:"G.R. Lambert & Co. c.1900 · public domain",url:"https://commons.wikimedia.org/wiki/File:Photographic_Views_of_Singapore_Plate_09_Boat_Quay.jpg"},now:{src:"nearby/cards/sg-boat-quay-now.webp",alt:"Boat Quay shophouses along the river, with office towers behind them",credit:"Frank Schulenburg 2023 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:View_of_Boat_Quay,_Singapore_(2023)-L1003669.jpg"},thenLabel:"c.1900",nowLabel:"2023",captions:{then:{lead:"c.1900.",text:" Boats crowd the river in front of the Boat Quay shophouses, when the quay was a trading centre."},mid:{lead:"1983.",text:" The last boats moved to Pasir Panjang so that the river could be cleaned."},now:{lead:"2023.",text:" The restored shophouses hold restaurants and bars, with office towers behind them."}}},reviewedAt:"2026-10-29"},"curated:sg-born":{title:["Born,","fine dining","in the old rickshaw station"],subtitle:"Neil Road · creative tasting menu in the Jinrikisha Station",lead:"Born is chef Zor Tan’s tasting-menu restaurant in the former Jinrikisha Station, the 1903 building that once ran the city’s rickshaws.",more:["The Municipal Council built the station in 1903 as the administration centre for rickshaws, which reached Singapore from Japan via Shanghai in the 1880s. Many early Chinese immigrants worked hard lives as rickshaw pullers.","Zor Tan trained at Jaan and Restaurant Andre and ran Sichuan Moon in Macau. Born won its first MICHELIN star in 2023. In 1987 the building was one of the first in Tanjong Pagar restored by the URA."],lookFor:["The Municipal Council crest on the front","Red brick and white plaster in the Edwardian style","The corner tower with its eight-sided dome"],sources:[{title:"1 Neil Road",url:"https://www.ura.gov.sg/conservation/find-a-building/conservation-portal/tjpa-00150/",publisher:"Urban Redevelopment Authority",checkedAt:"2026-10-29"},{title:"Former Jinricksha Station",url:"https://www.roots.gov.sg/places/places-landing/Places/landmarks/chinatown-clans-associations-trail/former-jinricksha-station",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-29"},{title:"Jinrikisha Station",url:"https://en.wikipedia.org/wiki/Jinrikisha_Station",publisher:"Wikipedia",checkedAt:"2026-10-29"},{title:"About",url:"https://restaurantborn.com/about/",publisher:"Born",checkedAt:"2026-10-29"},{title:"List of Michelin-starred restaurants in Singapore",url:"https://en.wikipedia.org/wiki/List_of_Michelin-starred_restaurants_in_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-29"}],clip:{title:"Where rickshaws were run",seconds:90,captions:["Born is in the old Jinrikisha Station, built in 1903.","It ran Singapore’s rickshaws, which came from Japan via Shanghai.","Chef Zor Tan trained at Jaan and Restaurant Andre.","A paper sculpture by Peter Gentenaar hangs over the dining room."],poster:{src:"nearby/cards/born.webp",alt:"The former Jinrikisha Station at Neil Road and Tanjong Pagar Road, the building that houses Born",credit:"Elisa.rolle 2012 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Jinrikisha_Station_2012_0141.jpg"}},tiles:[{value:1880,label:"rickshaws arrive",source:{title:"1 Neil Road",url:"https://www.ura.gov.sg/conservation/find-a-building/conservation-portal/tjpa-00150/",publisher:"Urban Redevelopment Authority",checkedAt:"2026-10-29"},suffix:"s"},{value:1903,label:"rickshaw station built",source:{title:"1 Neil Road",url:"https://www.ura.gov.sg/conservation/find-a-building/conservation-portal/tjpa-00150/",publisher:"Urban Redevelopment Authority",checkedAt:"2026-10-29"}},{value:2023,label:"first MICHELIN star",source:{title:"List of Michelin-starred restaurants in Singapore",url:"https://en.wikipedia.org/wiki/List_of_Michelin-starred_restaurants_in_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-29"}}],reviewedAt:"2026-10-29"},"curated:sg-buddha-tooth-relic-temple-and-museum":{title:["Buddha Tooth Relic Temple,","built in Tang style"],subtitle:"South Bridge Road · Buddhist temple and museum",lead:"The Buddha Tooth Relic Temple and Museum on South Bridge Road was built to house what Buddhists regard as a tooth of the Buddha. President S. R. Nathan opened it on Vesak Day in 2007.",more:["Its design combines the Tang dynasty style, seen as a golden age of Chinese architecture, with the Buddhist mandala, a symbol of the universe. The relic is kept in a stupa made from 320 kilograms of gold.","The building also holds two museums. On the roof, the Ten Thousand Buddha Pagoda holds about 11,111 small statues of Buddhas and Bodhisattvas."],lookFor:["Three large red doors at the main gate","The gold stupa on the fourth floor","The Ten Thousand Buddha Pagoda on the roof"],sources:[{title:"Our Story",url:"https://www.buddhatoothrelictemple.org.sg/our-story",publisher:"Buddha Tooth Relic Temple and Museum",checkedAt:"2026-10-31"},{title:"Buddha Tooth Relic Temple and Museum",url:"https://www.visitsingapore.com/see-do-singapore/culture-heritage/places-of-worship/buddha-tooth-relic-temple-museum/",publisher:"Singapore Tourism Board (VisitSingapore)",checkedAt:"2026-10-31"},{title:"Buddha Tooth Relic Temple and Museum",url:"https://en.wikipedia.org/wiki/Buddha_Tooth_Relic_Temple_and_Museum",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"A tooth in a golden stupa",seconds:90,captions:["This temple was built to house a tooth relic of the Buddha.","It was opened on Vesak Day in 2007.","The relic sits in a stupa made from 320 kg of gold.","Visitors can see the relic on the fourth floor."],poster:{src:"nearby/cards/sg-buddha-tooth-relic-temple-and-museum.webp",alt:"The red and gold Tang-style Buddha Tooth Relic Temple on South Bridge Road",credit:"Jakub Hałun 2024 · CC BY 4.0",url:"https://commons.wikimedia.org/wiki/File:Buddha_Tooth_Relic_Temple,_Singapore,_20240122_0810_2924_01.jpg"}},tiles:[{value:2007,label:"temple opens",source:{title:"Our Story",url:"https://www.buddhatoothrelictemple.org.sg/our-story",publisher:"Buddha Tooth Relic Temple and Museum",checkedAt:"2026-10-31"}},{value:320,label:"of gold in the stupa",suffix:" kg",source:{title:"Buddha Tooth Relic Temple and Museum",url:"https://www.visitsingapore.com/see-do-singapore/culture-heritage/places-of-worship/buddha-tooth-relic-temple-museum/",publisher:"Singapore Tourism Board (VisitSingapore)",checkedAt:"2026-10-31"}},{value:11111,label:"Buddhas in roof pagoda",grouped:!0,source:{title:"Buddha Tooth Relic Temple and Museum",url:"https://en.wikipedia.org/wiki/Buddha_Tooth_Relic_Temple_and_Museum",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-buona-vista-mrt-station":{title:["Buona Vista,","where two MRT lines meet"],subtitle:"North Buona Vista Road · MRT interchange (EW21/CC22)",lead:"Buona Vista is an MRT interchange between the East–West Line (EW21) and the Circle Line (CC22). It is the main rail gateway to one-north.",more:["The raised East–West Line station opened on 12 March 1988, on the stretch from Outram Park to Clementi. A light rail line to NUS was once planned from here, but it was never built.","The underground Circle Line platforms opened on 8 October 2011, and the station’s second level became a transfer level between the lines. The artwork “The Tree of Life” by Gilles Massot shows a eucalyptus tree from nearby Kent Ridge Park."],lookFor:["“The Tree of Life” on the Circle Line lift shaft","David Liew’s mural of Buona Vista’s history","Dotted seats that spell the station’s name"],sources:[{title:"Buona Vista MRT station",url:"https://en.wikipedia.org/wiki/Buona_Vista_MRT_station",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"The gateway to one-north",seconds:80,captions:["Buona Vista links the East–West and Circle lines.","The raised East–West station opened on 12 March 1988.","Circle Line platforms opened underground in 2011.","The platform seats are dots that spell the station’s name."],poster:{src:"nearby/cards/buona-vista-mrt-station.webp",alt:"The raised Buona Vista MRT station seen past large rain trees, with office towers behind",credit:"Wzhkevin 2022 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Buona_Vista_MRT_Station_from_Commonwealth_Avenue_West.jpg"}},tiles:[{value:1988,label:"East–West Line opens",source:{title:"Buona Vista MRT station",url:"https://en.wikipedia.org/wiki/Buona_Vista_MRT_station",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:2011,label:"Circle Line opens",source:{title:"Buona Vista MRT station",url:"https://en.wikipedia.org/wiki/Buona_Vista_MRT_station",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:4,label:"platforms",source:{title:"Buona Vista MRT station",url:"https://en.wikipedia.org/wiki/Buona_Vista_MRT_station",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-capitagreen":{title:["CapitaGreen,","a tower that","grows plants"],subtitle:"Market Street · office tower",lead:"CapitaGreen is a 245-metre office tower near Raffles Place. The Japanese architect Toyo Ito designed it, and it was completed in 2014.",more:["The tower was designed to be like a plant growing towards the sun, with living plants in its façade. Its rooftop garden, the Sky Forest, has 40 kinds of tree and shrub.","A 45-metre wind-catcher on the roof, shaped like flower petals, catches cool fresh air and sends it down into the office floors. In 2015 the tower won the CTBUH award for Best Tall Building in Asia and Australasia."],lookFor:["Green plants in the glass façade","The petal-shaped wind-catcher on the roof"],sources:[{title:"CapitaGreen",url:"https://en.wikipedia.org/wiki/CapitaGreen",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"A tower like a plant",seconds:90,captions:["CapitaGreen is an office tower near Raffles Place.","Toyo Ito designed it; it was completed in 2014.","Its façade holds living plants, like a plant growing to the sun.","A rooftop wind-catcher pulls cool air into the offices."]},tiles:[{value:2014,label:"completed",source:{title:"CapitaGreen",url:"https://en.wikipedia.org/wiki/CapitaGreen",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:245,label:"metres tall",source:{title:"CapitaGreen",url:"https://en.wikipedia.org/wiki/CapitaGreen",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:40,label:"kinds of plant, Sky Forest",source:{title:"CapitaGreen",url:"https://en.wikipedia.org/wiki/CapitaGreen",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-capitaspring":{title:["CapitaSpring,","a garden","in the sky"],subtitle:"Market Street · office tower with sky gardens",lead:"CapitaSpring is a 280-metre tower at 88 Market Street, completed in November 2021. It was designed by BIG and the architect Carlo Ratti, for CapitaLand and Mitsubishi Estate.",more:["Its front opens up in the middle for the Green Oasis, a vertical garden 35 metres high over four storeys. Higher up is the 1-Arden Sky Garden, and the building is home to Singapore's tallest urban farm.","It holds offices, shops and a hotel, and a food centre with a hawker centre on its second and third floors. Visitors must book a free time slot to see the gardens."],lookFor:["The green gap in the middle of the tower","The hawker centre on levels 2 and 3"],sources:[{title:"CapitaSpring",url:"https://www.capitaland.com/sg/en/lease/commercial-space-listing/capitaspring.html",publisher:"CapitaLand",checkedAt:"2026-10-31"},{title:"CapitaSpring",url:"https://en.wikipedia.org/wiki/CapitaSpring",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"Green in the middle",seconds:90,captions:["CapitaSpring is a 280-metre tower in Raffles Place.","BIG and Carlo Ratti designed it; it was completed in 2021.","Its Green Oasis is a garden 35 metres high, over four storeys.","Book a free time slot to visit its gardens."]},tiles:[{value:2021,label:"tower completed",source:{title:"CapitaSpring",url:"https://www.capitaland.com/sg/en/lease/commercial-space-listing/capitaspring.html",publisher:"CapitaLand",checkedAt:"2026-10-31"}},{value:280,label:"tall",suffix:" m",source:{title:"CapitaSpring",url:"https://www.capitaland.com/sg/en/lease/commercial-space-listing/capitaspring.html",publisher:"CapitaLand",checkedAt:"2026-10-31"}},{value:35,label:"high Green Oasis",suffix:" m",source:{title:"CapitaSpring",url:"https://www.capitaland.com/sg/en/lease/commercial-space-listing/capitaspring.html",publisher:"CapitaLand",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-capitol-singapore":{title:["Capitol Theatre,","a 1930 picture palace"],subtitle:"Stamford Road · historic theatre in a modern complex",lead:"Capitol Theatre opened on 22 May 1930 at the corner of Stamford Road and North Bridge Road. At the time it was hailed as the most modern hall with the largest capacity in the Far East.",more:["Persian businessman Mirza Mohamed Ali Namazie commissioned it. British architects Keys and Dowdeswell designed it, inspired by the Roxy Theatre in New York. Film stars such as Charlie Chaplin visited.","In 1946 Shaw bought it and made it their main cinema. It later stood empty for more than ten years. Restored as part of Capitol Singapore, with a hotel, a mall and homes, it reopened on 19 May 2015 with Singapura: The Musical."],lookFor:["The two Pegasus reliefs, uncovered in restoration","Inside: the recreated Persian Zodiac ceiling"],sources:[{title:"Capitol Theatre, Singapore",url:"https://en.wikipedia.org/wiki/Capitol_Theatre,_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"},{title:"About",url:"https://capitolsingapore.com/about/",publisher:"Capitol Singapore",checkedAt:"2026-10-31"}],clip:{title:"Opening night, 1930",seconds:95,captions:["Capitol Theatre was one of Singapore's finest theatres.","It opened on 22 May 1930 with the film Rio Rita.","Its first hall held at least 1,600 people.","After years empty, it reopened in 2015 with a new musical."]},tiles:[{value:1930,label:"theatre opens",source:{title:"Capitol Theatre, Singapore",url:"https://en.wikipedia.org/wiki/Capitol_Theatre,_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:1600,label:"seats at opening (at least)",grouped:!0,source:{title:"Capitol Theatre, Singapore",url:"https://en.wikipedia.org/wiki/Capitol_Theatre,_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:2015,label:"theatre reopens",source:{title:"Capitol Theatre, Singapore",url:"https://en.wikipedia.org/wiki/Capitol_Theatre,_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-cathedral-of-the-good-shepherd":{title:["Good Shepherd,","Singapore’s first","Catholic church"],subtitle:"Queen Street · Catholic cathedral",lead:"The Cathedral of the Good Shepherd was Singapore’s first permanent Catholic church. Its foundation stone was laid on 18 June 1843, and Father Jean-Marie Beurel blessed it on 6 June 1847.",more:["It was named after the Good Shepherd because of Bishop Laurent Imbert, believed to be the first priest to say Mass in Singapore. He was killed in Korea in 1839 after writing, ‘the good shepherd lays down his life for his sheep’. His relics are kept in the cathedral.","Designed by Denis McSwiney in the form of a Latin cross, it copies features of two London churches. The pipe organ, installed by Bevington & Sons in 1912, is Singapore’s oldest playable pipe organ. After a three-year restoration the cathedral reopened on 20 November 2016."],lookFor:["The three-part steeple with a budded cross","Stained glass of the Madonna and Child over a door","Twelve crosses on marble slabs inside"],sources:[{title:"Cathedral of the Good Shepherd",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/cathedral-of-the-good-shepherd",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"},{title:"Cathedral of the Good Shepherd, Singapore",url:"https://en.wikipedia.org/wiki/Cathedral_of_the_Good_Shepherd,_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"Named for a martyr",seconds:95,captions:["This was the first permanent Catholic church in Singapore.","Its foundation stone was laid in 1843; it opened in 1847.","It is named after a bishop martyred in Korea in 1839.","Its 1912 pipe organ is the oldest playable one here."],poster:{src:"nearby/cards/cathedral-of-the-good-shepherd.webp",alt:"The white cathedral with Tuscan columns, a red roof and a tall steeple behind its gates",credit:"Chainwit. 2023 · CC BY 4.0",url:"https://commons.wikimedia.org/wiki/File:Cathedral_of_the_Good_Shepherd,_Singapore_(2023)_-_img_01.jpg"}},tiles:[{value:1843,label:"foundation stone laid",source:{title:"Cathedral of the Good Shepherd",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/cathedral-of-the-good-shepherd",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:1847,label:"church blessed",source:{title:"Cathedral of the Good Shepherd",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/cathedral-of-the-good-shepherd",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:1912,label:"pipe organ installed",source:{title:"Cathedral of the Good Shepherd",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/cathedral-of-the-good-shepherd",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-cavenagh-bridge":{title:["Cavenagh Bridge,","Glasgow iron","since 1869"],subtitle:"Singapore River · iron footbridge and National Monument",lead:"Cavenagh Bridge, completed in 1869, is the oldest bridge in Singapore still in its original form. It linked the trading area on the south bank of the river with the government offices on the north bank.",more:["It is named after Sir Orfeur Cavenagh, Governor of the Straits Settlements from 1859 to 1867. The iron parts were made by P & W MacLellan in Glasgow, and the bridge was the last major work of Indian convicts in Singapore.","When Anderson Bridge opened in 1910, motor traffic moved there. A police sign at both ends still bans cattle, horses and any vehicle over 3 cwt, about 152 kg, so only people on foot can cross."],lookFor:["The old police sign at each end of the bridge","The Cavenagh family crest at the top","Plates with the name P & W MacLellan"],sources:[{title:"Singapore River Bridges: Cavenagh Bridge, Anderson Bridge and Elgin Bridge",url:"https://www.roots.gov.sg/places/places-landing/places/national-monuments/singapore-river-bridges",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"},{title:"Cavenagh Bridge",url:"https://en.wikipedia.org/wiki/Cavenagh_Bridge",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"No cattle, no horses",seconds:90,captions:["Before this bridge, people crossed the river here by ferry.","Its iron was made in Glasgow, Scotland, and shipped to Singapore.","It was tested with a load four times its own weight.","An old sign still bans cattle, horses and heavy carts."]},tiles:[{value:1869,label:"bridge completed",source:{title:"Singapore River Bridges: Cavenagh Bridge, Anderson Bridge and Elgin Bridge",url:"https://www.roots.gov.sg/places/places-landing/places/national-monuments/singapore-river-bridges",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:1910,label:"cars move to Anderson Bridge",source:{title:"Cavenagh Bridge",url:"https://en.wikipedia.org/wiki/Cavenagh_Bridge",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:2019,label:"national monument",source:{title:"Singapore River Bridges: Cavenagh Bridge, Anderson Bridge and Elgin Bridge",url:"https://www.roots.gov.sg/places/places-landing/places/national-monuments/singapore-river-bridges",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}}],thenNow:{then:{src:"nearby/cards/cavenagh-bridge-then.webp",alt:"Cavenagh Bridge around 1870, its cables and towers over a calm river, low colonial buildings behind",credit:"Unknown photographer, c.1870 (KITLV 155825) · Public domain",url:"https://commons.wikimedia.org/wiki/File:KITLV_-_155825_-_Cavanagh_Bridge_at_Singapore_-_circa_1870.tif"},now:{src:"nearby/cards/cavenagh-bridge-now.webp",alt:"Cavenagh Bridge in 2016 with walkers on it and office towers behind",credit:"Marcin Konsek 2016 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:2016_Singapur,_Downtown_Core,_Most_Cavenagha_(02)_(cropped).jpg"},thenLabel:"c.1870",nowLabel:"2016",captions:{then:{lead:"c.1870.",text:" The new bridge, its cables, and low buildings on the bank."},mid:{lead:"Same bridge, nearly 150 years apart.",text:" The cables and towers are still there."},now:{lead:"2016.",text:" A footbridge in front of the city's towers."}}},reviewedAt:"2026-10-29"},"curated:sg-central-fire-station":{title:["Central Fire Station,","red and white","since 1909"],subtitle:"Hill Street · working fire station and heritage gallery",lead:"Central Fire Station on Hill Street is the oldest surviving fire station in Singapore, and it is still in use. Building began in 1908 at the foot of Fort Canning Hill, and the station was completed in 1909.",more:["Its red-and-white front is called “blood-and-bandage” architecture: the bare red bricks are the “blood” and the white-painted plaster is the “bandage”. The style was popular in the Edwardian era. From the tall lookout tower, a fireman once watched for fires nearby.","The station was built for motorised fire engines from London, which replaced horse-drawn ones. The Civil Defence Heritage Gallery, opened in 2001, tells the story of Singapore’s firefighters from the early days to now."],lookFor:["Twin cupolas beside the triangular pediment","The fire brigade monogram in the pediment","Red shutter doors for the fire engines"],sources:[{title:"Central Fire Station",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/central-fire-station",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-29"}],clip:{title:"Blood and bandage",seconds:90,captions:["This is Singapore’s oldest surviving fire station, still at work.","The fire brigade began in 1888; this station opened in 1909.","Red brick is the “blood”, white plaster the “bandage”.","A heritage gallery inside tells the story of firefighting."],poster:{src:"nearby/cards/central-fire-station.webp",alt:"The red-and-white Central Fire Station on Hill Street with its lookout tower and red engine doors",credit:"Mike Peel 2023 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:At_Singapore_2023_045_-_Central_Fire_Station.jpg"}},tiles:[{value:1888,label:"fire brigade set up",source:{title:"Central Fire Station",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/central-fire-station",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-29"}},{value:1909,label:"station completed",source:{title:"Central Fire Station",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/central-fire-station",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-29"}},{value:2001,label:"heritage gallery opens",source:{title:"Central Fire Station",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/central-fire-station",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-29"}}],reviewedAt:"2026-10-29"},"curated:sg-cherry-garden-by-chef-fei":{title:["Cherry Garden,","Cantonese and Teochew","by Chef Fei"],subtitle:"Mandarin Oriental · Cantonese and Teochew restaurant",lead:"Cherry Garden by Chef Fei serves Cantonese and Teochew cooking at the Mandarin Oriental, Singapore. It was awarded One MICHELIN Star in the MICHELIN Guide Singapore 2026.",more:["Chef Fei was born and raised in Chaoshan, Guangdong. He began cooking at 16, became an executive chef by 20 and led his Guangzhou restaurant, Jiang by Chef Fei, to two MICHELIN stars for seven years in a row.","The room has old-world stone walls and wooden trellises, like a traditional courtyard house. Private rooms seat from four to 18 guests."],lookFor:["Stone walls and wooden trellises inside","Private dining rooms for up to 18 guests"],sources:[{title:"Cherry Garden by Chef Fei",url:"https://www.mandarinoriental.com/en/singapore/marina-bay/dine/cherry-garden",publisher:"Mandarin Oriental, Singapore",checkedAt:"2026-10-31"}],clip:{title:"A chef from Chaoshan",seconds:90,captions:["Cherry Garden is on Level 5 of the Mandarin Oriental.","Chef Fei was born and raised in Chaoshan, Guangdong.","He started cooking at 16 and was an executive chef by 20.","It holds One MICHELIN Star in the 2026 Singapore guide."],poster:{src:"nearby/cards/sg-cherry-garden-by-chef-fei.webp",alt:"The Mandarin Oriental Singapore hotel tower behind trees at Marina Square, where Cherry Garden is on Level 5",credit:"Bjoertvedt 2018 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Singapore_-_Marina_Bay_-_Mandarin_Oriental_IMG_9186.jpg"}},tiles:[{value:2026,label:"One MICHELIN Star",source:{title:"Cherry Garden by Chef Fei",url:"https://www.mandarinoriental.com/en/singapore/marina-bay/dine/cherry-garden",publisher:"Mandarin Oriental, Singapore",checkedAt:"2026-10-31"}},{value:16,label:"age Chef Fei began cooking",source:{title:"Cherry Garden by Chef Fei",url:"https://www.mandarinoriental.com/en/singapore/marina-bay/dine/cherry-garden",publisher:"Mandarin Oriental, Singapore",checkedAt:"2026-10-31"}},{value:18,label:"guests, private dining",source:{title:"Cherry Garden by Chef Fei",url:"https://www.mandarinoriental.com/en/singapore/marina-bay/dine/cherry-garden",publisher:"Mandarin Oriental, Singapore",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-chijmes":{title:["CHIJMES,","a convent school","turned courtyard"],subtitle:"Victoria Street · former convent, now dining",lead:"CHIJMES was the Convent of the Holy Infant Jesus, a girls' school started in 1854 by French Catholic nuns. The nuns moved into Caldwell House, built in 1840–41 and designed by G. D. Coleman.",more:["The Gothic chapel, designed by Father Charles Benedict Nain, was finished in 1903 and consecrated in 1904. Its stained glass was made in Bruges, Belgium, and each of its 648 columns has its own carvings of tropical birds and plants.","The schools moved to Toa Payoh in 1983. Caldwell House and the chapel became national monuments in 1990, and after restoration the complex reopened in 1996 as CHIJMES, pronounced 'chimes'."],lookFor:["The 'Gate of Hope', where babies were once left","Stained-glass windows in CHIJMES Hall","Caldwell House's curved, semi-circular front"],sources:[{title:"CHIJMES",url:"https://www.nlb.gov.sg/main/article-detail?cmsuuid=a1145bd1-7c99-4dce-ba0b-2626122ebdbd",publisher:"National Library Board (Singapore Infopedia)",checkedAt:"2026-10-31"}],clip:{title:"From convent to CHIJMES",seconds:100,captions:["French nuns opened a girls' school here in 1854.","The Gothic chapel was consecrated on 11 June 1904.","Each of its 648 columns has unique carvings.","Since 1996 it has held shops and restaurants."]},tiles:[{value:1854,label:"convent school founded",source:{title:"CHIJMES",url:"https://www.nlb.gov.sg/main/article-detail?cmsuuid=a1145bd1-7c99-4dce-ba0b-2626122ebdbd",publisher:"National Library Board (Singapore Infopedia)",checkedAt:"2026-10-31"}},{value:1904,label:"chapel consecrated",source:{title:"CHIJMES",url:"https://www.nlb.gov.sg/main/article-detail?cmsuuid=a1145bd1-7c99-4dce-ba0b-2626122ebdbd",publisher:"National Library Board (Singapore Infopedia)",checkedAt:"2026-10-31"}},{value:648,label:"carved columns",source:{title:"CHIJMES",url:"https://www.nlb.gov.sg/main/article-detail?cmsuuid=a1145bd1-7c99-4dce-ba0b-2626122ebdbd",publisher:"National Library Board (Singapore Infopedia)",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-childrens-museum-singapore":{title:["Children's Museum,","a 1906 school","for play"],subtitle:"Coleman Street · museum for children 12 and under",lead:"Children's Museum Singapore is Singapore's first museum for children aged 12 and below. It opened on 8 December 2022 in a two-storey colonial building on Coleman Street.",more:["Tomlinson and Lermit Architects designed the building for Anglo-Chinese School in 1906, as an extra block next to Oldham Hall. In the 1970s and 1980s it housed the Methodist Book Room.","From 1995 it was the Singapore Philatelic Museum, about stamps and postal history. It closed for renovation and reopened as the Children's Museum, opened by Deputy Prime Minister Heng Swee Keat."],lookFor:["The two-storey colonial building on Coleman Street","Hands-on galleries for young children"],sources:[{title:"About Us",url:"https://www.heritage.sg/childrensmuseum/whoweare/about-us",publisher:"Children's Museum Singapore",checkedAt:"2026-10-31"},{title:"Singapore Philatelic Museum",url:"https://en.wikipedia.org/wiki/Singapore_Philatelic_Museum",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"From school to stamps to play",seconds:90,captions:["This building was put up in 1906 for Anglo-Chinese School.","Later it was a bookshop, then a stamp museum from 1995.","In 2022 it reopened as a museum for children.","It is for children aged 12 and below."],poster:{src:"nearby/cards/sg-childrens-museum-singapore.webp",alt:"The white two-storey colonial building with colourful windows and the museum’s name",credit:"Diego Delso 2023 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Museo_de_los_Niños,_Singapur,_2023-08-18,_DD_09.jpg"}},tiles:[{value:1906,label:"school building",source:{title:"About Us",url:"https://www.heritage.sg/childrensmuseum/whoweare/about-us",publisher:"Children's Museum Singapore",checkedAt:"2026-10-31"}},{value:1995,label:"Philatelic Museum",source:{title:"About Us",url:"https://www.heritage.sg/childrensmuseum/whoweare/about-us",publisher:"Children's Museum Singapore",checkedAt:"2026-10-31"}},{value:2022,label:"Children's Museum opens",source:{title:"Singapore Philatelic Museum",url:"https://en.wikipedia.org/wiki/Singapore_Philatelic_Museum",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-china-cultural-centre":{title:["China Cultural Centre,","eleven storeys","of Chinese arts"],subtitle:"Queen Street · cultural centre of the People's Republic of China",lead:"The China Cultural Centre on Queen Street shows the culture of China through exhibitions, performances, films, talks and classes. It opened on 7 November 2015.",more:["It stands on the site of a former People's Association clubhouse. Xi Jinping, then China's Vice-President, and Goh Chok Tong broke ground on 15 November 2010. As President, Xi opened it with Goh five years later, in the 25th year of ties between the two countries.","Architect Liu Thai Ker designed the 11-storey building, with a library, classrooms and a multipurpose hall. It is not the same as the Singapore Chinese Cultural Centre, which is about local Chinese Singaporean culture."],lookFor:["The 11-storey building on Queen Street","A library and classrooms inside"],sources:[{title:"China Cultural Centre (Singapore)",url:"https://en.wikipedia.org/wiki/China_Cultural_Centre_(Singapore)",publisher:"Wikipedia",checkedAt:"2026-10-31"},{title:"Opening of China Cultural Centre",url:"https://www.mccy.gov.sg/about-us/news-and-resources/opening-of-china-cultural-centre/",publisher:"Ministry of Culture, Community and Youth",checkedAt:"2026-10-31"}],clip:{title:"Opened by Xi Jinping",seconds:85,captions:["A centre for the culture of China, on Queen Street.","Xi Jinping and Goh Chok Tong broke ground in 2010.","Architect Liu Thai Ker designed the 11-storey block.","It opened on 7 November 2015."],poster:{src:"nearby/cards/sg-china-cultural-centre.webp",alt:"The grey and white tower of the centre with its Chinese name in red down the front",credit:"Chongkian 2015 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:China_Cultural_Centre_(Singapore)_20151109.jpg"}},tiles:[{value:2010,label:"ground broken",source:{title:"China Cultural Centre (Singapore)",url:"https://en.wikipedia.org/wiki/China_Cultural_Centre_(Singapore)",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:2015,label:"centre opens",source:{title:"Opening of China Cultural Centre",url:"https://www.mccy.gov.sg/about-us/news-and-resources/opening-of-china-cultural-centre/",publisher:"Ministry of Culture, Community and Youth",checkedAt:"2026-10-31"}},{value:11,label:"storeys",source:{title:"China Cultural Centre (Singapore)",url:"https://en.wikipedia.org/wiki/China_Cultural_Centre_(Singapore)",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-chinatown-complex-food-centre":{title:["Chinatown Complex,","a home for","Chinatown’s street hawkers"],subtitle:"Smith Street · market and food centre",lead:"Chinatown Complex was built in 1981 as the Kreta Ayer Complex, to move street hawkers off Chinatown’s streets. About 300 hawkers moved in, and the last of them arrived in October 1983.",more:["People feared the move would erase old Chinatown, so the building borrows Chinese forms: pavilions, columns, arches, clay tiles, pitched roofs and a rooftop garden. It was renamed Chinatown Complex in 1984.","The wet market is in the basement, shops are on the ground floor and the food centre is on the second floor. After a $20.9 million upgrade it reopened in 2008 with more than 700 stalls. By 2016, about one in five of the original hawkers were still here."],lookFor:["The wet market in the basement","Clay-tiled pitched roofs and covered walkways","Hundreds of food stalls on the second floor"],order:"kopi",sources:[{title:"Chinatown Complex Market & Food Centre",url:"https://www.roots.gov.sg/stories-landing/stories/Hawker-Centres/Chinatown-Complex-Market-Food-Centre",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-29"}],clip:{title:"Off the street, up a floor",seconds:95,captions:["Hawkers once cooked on Smith, Trengganu and Pagoda Streets.","In 1983 about 300 of them moved into this new complex.","Its design borrows pavilions, arches and clay-tiled roofs.","Wet market below, food centre on the second floor."],poster:{src:"nearby/cards/sg-chinatown-complex-food-centre.webp",alt:"Chinatown Complex Market and Food Centre: red columns and steps at the entrance",credit:"Kbseah 2025 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Chinatown_Complex_Market_and_Food_Centre,_exterior.jpg"}},tiles:[{value:1983,label:"street hawkers move in",source:{title:"Chinatown Complex Market & Food Centre",url:"https://www.roots.gov.sg/stories-landing/stories/Hawker-Centres/Chinatown-Complex-Market-Food-Centre",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-29"}},{value:300,label:"hawkers resettled (about)",source:{title:"Chinatown Complex Market & Food Centre",url:"https://www.roots.gov.sg/stories-landing/stories/Hawker-Centres/Chinatown-Complex-Market-Food-Centre",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-29"}},{value:700,label:"stalls after 2008 reopening",source:{title:"Chinatown Complex Market & Food Centre",url:"https://www.roots.gov.sg/stories-landing/stories/Hawker-Centres/Chinatown-Complex-Market-Food-Centre",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-29"},suffix:"+"}],reviewedAt:"2026-10-29"},"curated:sg-church-of-saints-peter-and-paul":{title:["Saints Peter and Paul,","Mother Church","of the Chinese mission"],subtitle:"Queen Street · Catholic church, national monument",lead:"The Church of Saints Peter and Paul on Queen Street was built in 1869–1870. Priests from here started other Chinese Catholic parishes, so it is known as the 'Mother Church' of the Chinese mission.",more:["It was first built for Chinese and Tamil-speaking Catholics, and later served the Chinese alone. Three bronze bells were put in the belfry in 1883. In 1891–1892 transepts and a sacristy were added, with a pressed-steel ceiling from Ohio.","It became a national monument on 10 February 2003. A restoration finished in 2016 brought back the encaustic floor tiles and wooden louvred windows, and won a URA Architectural Heritage Award."],lookFor:["Saint Peter with keys and Saint Paul with a sword","Five saints in the sanctuary's stained glass","Eight Roman columns on the porch"],sources:[{title:"Church of Saints Peter and Paul",url:"https://www.roots.gov.sg/places/places-landing/places/national-monuments/church-of-saints-peter-and-paul",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"},{title:"Church of Saints Peter and Paul, Singapore",url:"https://en.wikipedia.org/wiki/Church_of_Saints_Peter_and_Paul,_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"The Mother Church",seconds:95,captions:["Building began in 1869 and ended the next year.","Priests from here started other Chinese parishes.","Its three bronze bells have rung since 1883.","Statues of Peter and Paul flank the rose window."],poster:{src:"nearby/cards/sg-church-of-saints-peter-and-paul.webp",alt:"The white Neo-Gothic front of the church with its spire and rose window",credit:"Chainwit. 2023 · CC BY 4.0",url:"https://commons.wikimedia.org/wiki/File:Church_of_Saints_Peter_and_Paul,_Singapore_(2023)_-_img_01.jpg"}},tiles:[{value:1870,label:"church completed",source:{title:"Church of Saints Peter and Paul",url:"https://www.roots.gov.sg/places/places-landing/places/national-monuments/church-of-saints-peter-and-paul",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:1883,label:"three bronze bells",source:{title:"Church of Saints Peter and Paul",url:"https://www.roots.gov.sg/places/places-landing/places/national-monuments/church-of-saints-peter-and-paul",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:2003,label:"national monument",source:{title:"Church of Saints Peter and Paul, Singapore",url:"https://en.wikipedia.org/wiki/Church_of_Saints_Peter_and_Paul,_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-church-of-the-sacred-heart":{title:["Church of the Sacred Heart,","French Baroque","on Tank Road"],subtitle:"Tank Road · Catholic church",lead:"The Church of the Sacred Heart was built for Cantonese- and Hakka-speaking Catholics, who until then worshipped at the Church of Saints Peter and Paul. It was blessed on 11 September 1910, with about 200 parishioners.",more:["Father Vincent Gazeau started a building fund in 1908. The French priest-architect Father Louis Lambert designed it in a French Baroque style. Chinese Catholic donors gave the altar, the stained glass and the teak pews. By 1935 the congregation had grown to 2,150.","On the afternoon of 15 February 1942, Japanese shells hit the church and destroyed the ceiling, pews and fittings. No one was hurt, because the Chinese New Year thanksgiving Mass that morning was over."],lookFor:["White marble altars carved in France","Life-sized statues of Our Lady and St Joseph","Stained glass and teak pews"],sources:[{title:"About",url:"https://www.churchofthesacredheart.sg/about",publisher:"Church of the Sacred Heart",checkedAt:"2026-10-31"}],clip:{title:"Shells on Chinese New Year",seconds:95,captions:["Built for Cantonese- and Hakka-speaking Catholics.","Bishop Barillon blessed it on 11 September 1910.","On 15 February 1942 Japanese shells hit the church.","No one was hurt: the morning Mass had already ended."],poster:{src:"nearby/cards/sg-church-of-the-sacred-heart.webp",alt:"The white front of the church with columns and a bell tower, against a blue sky",credit:"Bahnfrend 2023 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Church_of_the_Sacred_Heart,_Singapore,_2023_(01).jpg"}},tiles:[{value:1910,label:"church blessed",source:{title:"About",url:"https://www.churchofthesacredheart.sg/about",publisher:"Church of the Sacred Heart",checkedAt:"2026-10-31"}},{value:200,label:"first parishioners (about)",source:{title:"About",url:"https://www.churchofthesacredheart.sg/about",publisher:"Church of the Sacred Heart",checkedAt:"2026-10-31"}},{value:2150,label:"congregation in 1935",grouped:!0,source:{title:"About",url:"https://www.churchofthesacredheart.sg/about",publisher:"Church of the Sacred Heart",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-church-of-the-true-light":{title:["Church of the True Light,","scripture in","Chinese script"],subtitle:"Perak Road · Anglican church",lead:"The Church of the True Light began in 1911 as a mission to Heng Hua and Hock Chew Chinese from Fujian. Its first meetings were held in a friend's barber shop on Bencoolen Street.",more:["Guok Koh Muo, a part-time schoolmaster and newspaper journalist, started the mission at the call of a British missionary, Miss Apple. It moved often in the 1920s, once into an old Buddhist nunnery on Victoria Street. It took the name Church of the True Light at Jalan Besar.","The present site was bought in 1940, but the war delayed building. The church was finished in 1952, with a free clinic and a kindergarten. It became a parish in 1963 and was once called 'the trishaw rider church'."],lookFor:["Bible verses in Chinese script on walls and pillars","The conserved 1952 church on Perak Road"],sources:[{title:"Church of the True Light",url:"https://www.roots.gov.sg/places/places-landing/places/landmarks/little-india-heritage-trail-walk-of-faiths/church-of-the-true-light",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"},{title:"Church of the True Light",url:"https://anglican.org.sg/our-parishes/cotl/",publisher:"Anglican Diocese of Singapore",checkedAt:"2026-10-31"}],clip:{title:"Started in a barber shop",seconds:90,captions:["In 1911 a mission began for Chinese from Fujian.","Its first meetings were in a barber shop on Bencoolen Street.","The church on Perak Road was finished in 1952.","Bible verses in Chinese script cover its walls and pillars."],poster:{src:"nearby/cards/sg-church-of-the-true-light.webp",alt:"The cream church with a tall tower and Chinese characters on its front, at a street corner",credit:"Orderinchaos 2016 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Little_India_-_Church_of_the_True_Light_(Perak-Dickson).jpg"}},tiles:[{value:1911,label:"mission begins",source:{title:"Church of the True Light",url:"https://www.roots.gov.sg/places/places-landing/places/landmarks/little-india-heritage-trail-walk-of-faiths/church-of-the-true-light",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:1952,label:"church completed",source:{title:"Church of the True Light",url:"https://www.roots.gov.sg/places/places-landing/places/landmarks/little-india-heritage-trail-walk-of-faiths/church-of-the-true-light",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:1963,label:"becomes a parish",source:{title:"Church of the True Light",url:"https://anglican.org.sg/our-parishes/cotl/",publisher:"Anglican Diocese of Singapore",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-civilian-war-memorial":{title:["Civilian War Memorial,","the Four Chopsticks"],subtitle:"Beach Road · memorial to civilian war victims",lead:"The Civilian War Memorial was the first memorial in Singapore to the civilians who died in the Japanese Occupation of 1942 to 1945. Prime Minister Lee Kuan Yew unveiled it on 15 February 1967, 25 years after the British surrender.",more:["In 1962, mass graves were found in many places around Singapore, more than 40 of them in the 'Valley of Death' at Siglap. They held victims of Sook Ching, when the Japanese arrested and killed many men, mainly Chinese. The Singapore Chinese Chamber of Commerce collected the remains and raised money for a memorial.","Swan & Maclaren designed it. Its four 67-metre columns, called the 'Four Chopsticks', stand for the Chinese, Malays, Indians and Eurasians who died. The remains rest in 606 urns in a vault under the platform."],lookFor:["The words at the base in four official languages","The empty urn on a pedestal between the columns","The water pools around the memorial"],sources:[{title:"Civilian War Memorial",url:"https://www.roots.gov.sg/en/places/places-landing/Places/national-monuments/civilian-war-memorial",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}],clip:{title:"Remembering the civilians",seconds:95,captions:["This memorial remembers civilians killed from 1942 to 1945.","In 1962, mass graves of war victims were found around Singapore.","Four 67-metre columns stand for four communities.","A memorial service is held here every 15 February."]},tiles:[{value:1967,label:"memorial unveiled",source:{title:"Civilian War Memorial",url:"https://www.roots.gov.sg/en/places/places-landing/Places/national-monuments/civilian-war-memorial",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:67,label:"high columns",suffix:" m",source:{title:"Civilian War Memorial",url:"https://www.roots.gov.sg/en/places/places-landing/Places/national-monuments/civilian-war-memorial",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:606,label:"urns in the vault below",source:{title:"Civilian War Memorial",url:"https://www.roots.gov.sg/en/places/places-landing/Places/national-monuments/civilian-war-memorial",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-clarke-quay":{title:["Clarke Quay,","old warehouses","by the river"],subtitle:"Singapore River · restored warehouses",lead:"Clarke Quay is a riverside quay just upstream from Boat Quay. It is named after Lieutenant-General Sir Andrew Clarke, the second Governor of the Straits Settlements.",more:["In colonial times, lighters carried goods from Boat Quay upstream to the warehouses here. When cargo services moved to Pasir Panjang, the quay fell silent. The area received conservation status on 7 July 1989, and its shophouses were restored in 1993.","The oldest building is the River House, a two-storey Teochew-style mansion from the 1880s. It was a merchant's home and later a godown for gambier, biscuits and other goods."],lookFor:["The River House and its decorated roof ridges","Read Bridge, linking to the south bank","Rows of old brick warehouses by the river"],sources:[{title:"Clarke Quay Conservation Area",url:"https://www.ura.gov.sg/conservation/find-a-building/conservation-portal/ckqy/",publisher:"Urban Redevelopment Authority (URA)",checkedAt:"2026-10-31"},{title:"Clarke Quay",url:"https://en.wikipedia.org/wiki/Clarke_Quay",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"Warehouses by the water",seconds:90,captions:["Clarke Quay is named after Sir Andrew Clarke, a colonial governor.","Lighters once carried goods upstream to warehouses here.","Its warehouses are the largest conserved group of their kind.","Today they hold restaurants, bars and clubs."]},tiles:[{value:1873,label:"Clarke becomes governor",source:{title:"Clarke Quay",url:"https://en.wikipedia.org/wiki/Clarke_Quay",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:1880,label:"River House built",suffix:"s",source:{title:"Clarke Quay Conservation Area",url:"https://www.ura.gov.sg/conservation/find-a-building/conservation-portal/ckqy/",publisher:"Urban Redevelopment Authority (URA)",checkedAt:"2026-10-31"}},{value:1989,label:"conservation status",source:{title:"Clarke Quay Conservation Area",url:"https://www.ura.gov.sg/conservation/find-a-building/conservation-portal/ckqy/",publisher:"Urban Redevelopment Authority (URA)",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-clifford-pier-customs-house":{title:["Clifford Pier,","the Red Lamp Pier"],subtitle:"Collyer Quay · former landing pier, now a restaurant",lead:"Clifford Pier opened in 1933 and was the landing place for many sea passengers and immigrants who came to Singapore. It replaced Johnston Pier, built nearby in 1855.",more:["Many locals called it the Red Lamp Pier, after the red oil lamp that hung there to guide seafarers. The Public Works Department designed it, with a roof held up by arched concrete trusses.","Later, ferries left from here for the Southern Islands. The pier closed on 1 April 2006, when Marina South Pier took over. Today the pier hall is The Clifford Pier restaurant of the Fullerton Bay Hotel."],lookFor:["Arched concrete roof trusses over the hall","Small details like the brackets and fire hose boxes"],sources:[{title:"Clifford Pier",url:"https://www.roots.gov.sg/places/places-landing/places/historic-sites/clifford-pier",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"},{title:"Clifford Pier",url:"https://en.wikipedia.org/wiki/Clifford_Pier",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"Where new arrivals landed",seconds:90,captions:["Sea passengers and immigrants landed at this pier.","It opened in 1933, named after Governor Sir Hugh Clifford.","A red oil lamp once hung here to guide seafarers.","Ferries stopped in 2006; the pier hall is now a restaurant."],poster:{src:"nearby/cards/clifford-pier.webp",alt:"Inside the old Clifford Pier hall: white arched roof trusses over restaurant tables",credit:"Smuconlaw 2016 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:The_Clifford_Pier,_The_Fullerton_Bay_Hotel,_Singapore_-_20160514.jpg"}},tiles:[{value:1855,label:"Johnston Pier built",source:{title:"Clifford Pier",url:"https://www.roots.gov.sg/places/places-landing/places/historic-sites/clifford-pier",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:1933,label:"Clifford Pier opens",source:{title:"Clifford Pier",url:"https://www.roots.gov.sg/places/places-landing/places/historic-sites/clifford-pier",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:2006,label:"last ferries leave",source:{title:"Clifford Pier",url:"https://en.wikipedia.org/wiki/Clifford_Pier",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-cloudstreet":{title:["Cloudstreet,","Sri Lankan roots,","Australian training"],subtitle:"Amoy Street · innovative tasting menu",lead:"Cloudstreet is the tasting-menu restaurant of chef Rishi Naleendra and his wife Manuela Toniolo on Amoy Street. It is named after his favourite novel.",more:['Its menus use European techniques "through a Sri Lankan lens", reflecting Naleendra’s heritage. One dish pairs Australian marron with spiced Sri Lankan millet. The wine list has over 350 labels.','It won one MICHELIN star in 2021 and two in 2022. Amoy Street, marked "Amoi Street" on an 1836 map, is one of the streets of Raffles’ 1822 plan for Chinatown.'],lookFor:["Shophouse rows along Amoy Street","70 Amoy Street, where Anglo-Chinese School began in 1886"],sources:[{title:"Cloudstreet",url:"https://www.the50.com/asia/en/the-list/41-50/cloudstreet.html",publisher:"Asia's 50 Best Restaurants",checkedAt:"2026-10-29"},{title:"About",url:"https://cloudstreet.com.sg/about/",publisher:"Cloudstreet",checkedAt:"2026-10-29"},{title:"List of Michelin-starred restaurants in Singapore",url:"https://en.wikipedia.org/wiki/List_of_Michelin-starred_restaurants_in_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-29"},{title:"Amoy Street, Singapore",url:"https://en.wikipedia.org/wiki/Amoy_Street,_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-29"}],clip:{title:"Named after a novel",seconds:90,captions:["Cloudstreet is named after its chef’s favourite novel.","Rishi Naleendra runs it with his wife, Manuela Toniolo.","European technique meets his Sri Lankan heritage.","Diners can sit at a counter facing the open kitchen."],poster:{src:"nearby/cards/cloudstreet.webp",alt:"Amoy Street and its shophouse rows, the street where Cloudstreet is (not the restaurant itself)",credit:"Dudva 2013 · CC BY-SA 3.0",url:"https://commons.wikimedia.org/wiki/File:Amoy_Street,_Singapore_-_20130103.jpg"}},tiles:[{value:2021,label:"first MICHELIN star",source:{title:"List of Michelin-starred restaurants in Singapore",url:"https://en.wikipedia.org/wiki/List_of_Michelin-starred_restaurants_in_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-29"}},{value:2022,label:"second MICHELIN star",source:{title:"List of Michelin-starred restaurants in Singapore",url:"https://en.wikipedia.org/wiki/List_of_Michelin-starred_restaurants_in_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-29"}},{value:350,label:"wine labels",source:{title:"About",url:"https://cloudstreet.com.sg/about/",publisher:"Cloudstreet",checkedAt:"2026-10-29"},suffix:"+"}],reviewedAt:"2026-10-29"},"curated:sg-coleman-bridge":{title:["Coleman Bridge,","one crossing,","four bridges"],subtitle:"Hill Street to New Bridge Road · road bridge",lead:"Coleman Bridge crosses the Singapore River between Boat Quay and Clarke Quay, linking Hill Street and New Bridge Road. It is named after its architect, George Coleman.",more:["The first bridge, of brick with nine arches, was built in 1840. People called it the New Bridge, which gave New Bridge Road its name. A timber bridge replaced it in 1865, but it was not well built, so an iron bridge followed in 1886.","The wider bridge of today replaced the iron one late in the 20th century. It keeps the ornate columns, lamp posts and railings of the 1886 bridge. At night it is lit up."],lookFor:["Old-style lamp posts along the bridge","Ornate railings copied from the 1886 bridge","Murals in the underpass below"],sources:[{title:"Coleman Bridge #Heritage",url:"https://www.sg101.gov.sg/resources/archives/heritage-coleman-bridge/",publisher:"SG101 (Singapore Government)",checkedAt:"2026-10-31"},{title:"Coleman Bridge, Singapore",url:"https://en.wikipedia.org/wiki/Coleman_Bridge,_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"A bridge rebuilt",seconds:90,captions:["Coleman Bridge links Hill Street and New Bridge Road.","The first, built in 1840, was a brick bridge with nine arches.","It was rebuilt in timber in 1865, then in iron in 1886.","Today's bridge keeps lamp posts and railings from 1886."],poster:{src:"nearby/cards/sg-coleman-bridge.webp",alt:"Coleman Bridge over the Singapore River, with its old-style lamp posts",credit:"LN9267 2023 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Coleman_Bridge,_Singapore_09-11-2023.jpg"}},tiles:[{value:1840,label:"first brick bridge",source:{title:"Coleman Bridge #Heritage",url:"https://www.sg101.gov.sg/resources/archives/heritage-coleman-bridge/",publisher:"SG101 (Singapore Government)",checkedAt:"2026-10-31"}},{value:9,label:"arches on the first bridge",source:{title:"Coleman Bridge #Heritage",url:"https://www.sg101.gov.sg/resources/archives/heritage-coleman-bridge/",publisher:"SG101 (Singapore Government)",checkedAt:"2026-10-31"}},{value:1886,label:"iron bridge built",source:{title:"Coleman Bridge #Heritage",url:"https://www.sg101.gov.sg/resources/archives/heritage-coleman-bridge/",publisher:"SG101 (Singapore Government)",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-covenant-presbyterian-church":{title:["Covenant Presbyterian,","many languages","on Race Course Road"],subtitle:"Race Course Road · Presbyterian church",lead:"Covenant Presbyterian Church stands on Race Course Road in Little India, along the row of restaurants near Banana Leaf Apollo.",more:["On Sundays it holds a Mandarin service at 9.30am, an English service at 11am, and a Sinhalese service for its Sri Lankan ministry at 2pm, followed by Bible study."],lookFor:["The church among Race Course Road's restaurants","Service times in English, Mandarin and Sinhalese"],sources:[{title:"Service Timings",url:"https://www.cpc.sg/services",publisher:"Covenant Presbyterian Church",checkedAt:"2026-10-31"},{title:"华文事工 (Chinese)",url:"https://www.cpc.sg/chinese",publisher:"Covenant Presbyterian Church",checkedAt:"2026-10-31"},{title:"Sri Lankan Service",url:"https://www.cpc.sg/sri-lankan",publisher:"Covenant Presbyterian Church",checkedAt:"2026-10-31"}],clip:{title:"Four services, one church",seconds:80,captions:["A Presbyterian church on Race Course Road, Little India.","On Sundays a Mandarin service starts at 9.30am.","The English service follows at 11am.","At 2pm the Sri Lankan ministry meets in Sinhalese."]},reviewedAt:"2026-10-29"},"curated:sg-duke-nus-medical-school":{title:["Duke-NUS,","a medical school","for graduates"],subtitle:"College Road · graduate medical school, seen from outside",lead:"Duke-NUS Medical School is a partnership between Duke University in the United States and the National University of Singapore. It was set up in April 2005 as Singapore’s second medical school.",more:["As in American medical schools, its students already have a bachelor’s degree. The first class of 26 students started in August 2007, and 24 graduated in May 2011.","Its main building, the Khoo Teck Puat Building, was dedicated on 28 September 2009 on the Singapore General Hospital campus at Outram, next to the College of Medicine Building."],lookFor:["The Khoo Teck Puat Building on College Road","The College of Medicine Building next door"],sources:[{title:"Duke–NUS Medical School",url:"https://en.wikipedia.org/wiki/Duke%E2%80%93NUS_Medical_School",publisher:"Wikipedia",checkedAt:"2026-10-29"},{title:"Duke-National University of Singapore Graduate Medical School opens new state-of-the-art campus",url:"https://corporate.dukehealth.org/news/duke-national-university-singapore-graduate-medical-school-opens-new-state-art-campus",publisher:"Duke Health",checkedAt:"2026-10-29"},{title:"Duke-NUS Medical School celebrates inaugural class",url:"https://globalhealth.duke.edu/news/duke-nus-medical-school-celebrates-inaugural-class",publisher:"Duke Global Health Institute",checkedAt:"2026-10-29"}],clip:{title:"Doctors after a first degree",seconds:85,captions:["Duke-NUS is a medical school of Duke University and NUS.","It was set up in April 2005, Singapore’s second medical school.","Students join after a first degree, as in the United States.","Its building at Outram was dedicated in 2009."]},tiles:[{value:2005,label:"school set up",source:{title:"Duke–NUS Medical School",url:"https://en.wikipedia.org/wiki/Duke%E2%80%93NUS_Medical_School",publisher:"Wikipedia",checkedAt:"2026-10-29"}},{value:2009,label:"Outram building dedicated",source:{title:"Duke-National University of Singapore Graduate Medical School opens new state-of-the-art campus",url:"https://corporate.dukehealth.org/news/duke-national-university-singapore-graduate-medical-school-opens-new-state-art-campus",publisher:"Duke Health",checkedAt:"2026-10-29"}},{value:24,label:"first graduates (2011)",source:{title:"Duke-NUS Medical School celebrates inaugural class",url:"https://globalhealth.duke.edu/news/duke-nus-medical-school-celebrates-inaugural-class",publisher:"Duke Global Health Institute",checkedAt:"2026-10-29"}}],reviewedAt:"2026-10-29"},"curated:sg-duo":{title:["DUO,","twin towers","with scooped-out sides"],subtitle:"Ophir Road · offices, hotel and homes",lead:"DUO is a pair of towers by Büro Ole Scheeren, completed in 2018 next to the historic Kampong Glam district. The 186-metre tower holds 660 homes; the 170-metre tower holds offices and a hotel.",more:["The architects cut circular carvings out of the allowed building shapes, giving the towers their concave sides. A net-like hexagonal pattern of sunshades covers the faces.","The curved shapes catch the wind and send it through the site, keeping the shaded gardens cool. A plaza between the towers is open to the public 24 hours a day. In 2021 DUO won a CTBUH Urban Habitat Award."],lookFor:["Honeycomb sunshades on the curved faces","The plaza and gardens between the towers"],sources:[{title:"DUO",url:"https://www.buro-os.com/projects/duo",publisher:"Büro Ole Scheeren",checkedAt:"2026-10-31"}],clip:{title:"Carved towers",seconds:90,captions:["DUO is a pair of towers beside Kampong Glam.","Ole Scheeren carved circles out of their sides.","Hexagonal sunshades cover the curved faces.","A plaza between them is open 24 hours a day."],poster:{src:"nearby/cards/sg-duo.webp",alt:"Close-up of the honeycomb-pattern glass sunshades on DUO's hotel tower at sunset",credit:"Basile Morin 2018 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Sunlight_on_the_curved_honeycomb_glass_façade_of_the_hotel_Andaz_mixed_with_interior_lighting_at_sunset_in_Singapore.jpg"}},tiles:[{value:2018,label:"completed",source:{title:"DUO",url:"https://www.buro-os.com/projects/duo",publisher:"Büro Ole Scheeren",checkedAt:"2026-10-31"}},{value:186,label:"metres, taller tower",source:{title:"DUO",url:"https://www.buro-os.com/projects/duo",publisher:"Büro Ole Scheeren",checkedAt:"2026-10-31"}},{value:660,label:"homes",source:{title:"DUO",url:"https://www.buro-os.com/projects/duo",publisher:"Büro Ole Scheeren",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-elgin-bridge":{title:["Elgin Bridge,","the bridge in","Bridge Road"],subtitle:"North and South Bridge Road · road bridge",lead:"Elgin Bridge carries the road between North Bridge Road and South Bridge Road over the Singapore River. The two roads were named after the bridge.",more:["A wooden footbridge stood here in the 1820s, the first across the river. The first Elgin Bridge, an iron bridge from Calcutta, opened in 1862. It was named after Lord Elgin, Governor-General of India.","Today's bridge is the fifth on the site. It was designed by Municipal Engineer T. C. Hood and opened on 30 May 1929. In 2019 it became a National Monument, together with Cavenagh and Anderson Bridges."],lookFor:["Cast-iron lamps designed by Rudolfo Nolli","Medallions with a lion and a palm tree","Three arches over the roadway"],sources:[{title:"Singapore River Bridges: Cavenagh Bridge, Anderson Bridge and Elgin Bridge",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/singapore-river-bridges",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"},{title:"Elgin Bridge (Singapore)",url:"https://en.wikipedia.org/wiki/Elgin_Bridge_(Singapore)",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"The fifth bridge",seconds:90,captions:["Elgin Bridge stands where the first river bridge was built.","The first Elgin Bridge, of iron, came from Calcutta in 1862.","Today's concrete arch bridge opened on 30 May 1929.","Its lamps were designed by Italian sculptor Rudolfo Nolli."],poster:{src:"nearby/cards/sg-elgin-bridge.webp",alt:"The white arches of Elgin Bridge over the Singapore River",credit:"Frank Schulenburg 2023 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Elgin_Bridge,_Singapore_(2023)-L1003671.jpg"}},tiles:[{value:1862,label:"first Elgin Bridge",source:{title:"Singapore River Bridges: Cavenagh Bridge, Anderson Bridge and Elgin Bridge",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/singapore-river-bridges",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:1929,label:"present bridge opens",source:{title:"Singapore River Bridges: Cavenagh Bridge, Anderson Bridge and Elgin Bridge",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/singapore-river-bridges",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:2019,label:"national monument",source:{title:"Singapore River Bridges: Cavenagh Bridge, Anderson Bridge and Elgin Bridge",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/singapore-river-bridges",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-esplanade-theatres-on-the-bay":{title:["Esplanade,","twin shells","on the bay"],subtitle:"Esplanade Drive · national performing arts centre",lead:"Esplanade – Theatres on the Bay is Singapore's national performing arts centre. It opened on 12 October 2002, with a concert hall of about 1,600 seats and a theatre for about 2,000.",more:["DP Architects of Singapore designed it, at first with Michael Wilford & Partners of London. The first design had plain glass shells, and critics feared they would be too hot. Aluminium sunshades were added, which gave it the nickname 'The Durian'.","It stands on reclaimed land, on the site of the old Satay Club food area. About 70% of its events are free."],lookFor:["Aluminium sunshades covering the two shells","The Esplanade Mall, between the two halls"],sources:[{title:"Esplanade – Theatres on the Bay",url:"https://en.wikipedia.org/wiki/Esplanade_%E2%80%93_Theatres_on_the_Bay",publisher:"Wikipedia",checkedAt:"2026-10-31"},{title:"Our Story",url:"https://www.esplanade.com/about-us/our-story",publisher:"Esplanade – Theatres on the Bay",checkedAt:"2026-10-31"}],clip:{title:"The Durian by the bay",seconds:90,captions:["Esplanade is Singapore's national performing arts centre.","It opened on 12 October 2002, on reclaimed land.","People call it 'The Durian' for its spiky sunshades.","About 70% of its events are free for everyone."]},tiles:[{value:2002,label:"centre opens",source:{title:"Esplanade – Theatres on the Bay",url:"https://en.wikipedia.org/wiki/Esplanade_%E2%80%93_Theatres_on_the_Bay",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:1600,label:"concert hall seats (about)",grouped:!0,source:{title:"Esplanade – Theatres on the Bay",url:"https://en.wikipedia.org/wiki/Esplanade_%E2%80%93_Theatres_on_the_Bay",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:70,label:"of events free",suffix:"%",source:{title:"Our Story",url:"https://www.esplanade.com/about-us/our-story",publisher:"Esplanade – Theatres on the Bay",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-estiatorio-milos":{title:["Milos,","a Greek fish market","at Marina Bay"],subtitle:"The Shoppes at Marina Bay Sands · Greek seafood",lead:"estiatorio Milos is a Greek seafood restaurant founded by Costas Spiliadis, a Greek-born chef, in Montreal in 1979. The Singapore branch, its first in Asia, opened on 25 July 2024.",more:["Milos buys seafood and produce through long ties with fishermen and farmers in Greece and in each city. The 155-seat Singapore room has a fish market display at its centre, an open kitchen and private rooms.","Its entrance is made of Pendelikon marble from Athens, the stone of the Parthenon."],lookFor:["The fish market display","The Pendelikon marble entrance","The open kitchen"],sources:[{title:"About",url:"https://www.estiatoriomilos.com/about",publisher:"estiatorio Milos",checkedAt:"2026-10-31"},{title:"Singapore",url:"https://www.estiatoriomilos.com/singapore",publisher:"estiatorio Milos",checkedAt:"2026-10-31"},{title:"World-famous Greek restaurant estiatorio Milos opens its first Asian location at Marina Bay Sands",url:"https://www.aap.com.au/aapreleases/cision20240724ae68509",publisher:"AAP / PR Newswire (press release)",checkedAt:"2026-10-31"}],clip:{title:"From Montreal, 1979",seconds:90,captions:["Costas Spiliadis opened the first Milos in Montreal in 1979.","Singapore’s, opened in July 2024, is its first in Asia.","The entrance is Pendelikon marble, as used for the Parthenon.","Choose your fish at the fish market display."],poster:{src:"nearby/cards/estiatorio-milos.webp",alt:"Inside The Shoppes at Marina Bay Sands, under the glass vaulted roof; Milos is on the basement level (not the restaurant itself)",credit:"Basile Morin 2018 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Interior_of_The_Shoppes_at_Marina_Bay_Sands,_Singapore.jpg"}},tiles:[{value:1979,label:"first Milos, Montreal",source:{title:"About",url:"https://www.estiatoriomilos.com/about",publisher:"estiatorio Milos",checkedAt:"2026-10-31"}},{value:2024,label:"opens in Singapore",source:{title:"World-famous Greek restaurant estiatorio Milos opens its first Asian location at Marina Bay Sands",url:"https://www.aap.com.au/aapreleases/cision20240724ae68509",publisher:"AAP / PR Newswire (press release)",checkedAt:"2026-10-31"}},{value:155,label:"seats",source:{title:"Singapore",url:"https://www.estiatoriomilos.com/singapore",publisher:"estiatorio Milos",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-fairfield-methodist-church":{title:["Fairfield Methodist Church,","in a 1958 cinema"],subtitle:"Tanjong Pagar Road · church in a former cinema",lead:"Fairfield Methodist Church stands at the corner of Tanjong Pagar Road and Maxwell Road. The building opened in 1958 as the Metropole, also called the Jing Hwa Cinema.",more:["Local architect Wong Foo Nam designed it in the Modernist style, with a curved front of floor-to-ceiling windows. It was one of Chinatown's three famous cinemas, with the Oriental and the Majestic.","The cinema closed in October 1985. The church, whose congregation was formed on 1 February 1948, renovated the building in 1986, adding an altar and a communion rail but keeping most of the original spaces. In September 2005 the URA gazetted it for conservation."],lookFor:["The curved front with floor-to-ceiling windows","Maxwell Food Centre nearby"],sources:[{title:"Fairfield Methodist Church (Former Metropole Cinema)",url:"https://www.roots.gov.sg/places/places-landing/Places/surveyed-sites/fairfield-methodist-church",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"},{title:"About Us",url:"https://fairfieldmc.org/about",publisher:"Fairfield Methodist Church",checkedAt:"2026-10-31"},{title:"Fairfield Methodist Church",url:"https://en.wikipedia.org/wiki/Fairfield_Methodist_Church",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"From cinema to church",seconds:90,captions:["This church was built as the Metropole, a cinema, in 1958.","It was one of Chinatown's three famous cinemas.","The cinema closed in 1985; the church moved in in 1986.","Its curved front of tall windows was conserved in 2005."],poster:{src:"nearby/cards/sg-fairfield-methodist-church.webp",alt:"Fairfield Methodist Church, the former Metropole cinema, with its curved front of tall windows",credit:"Aaaatu 2024 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Fairfield_Methodist_Church_Singapore.jpg"}},tiles:[{value:1958,label:"cinema completed",source:{title:"Fairfield Methodist Church (Former Metropole Cinema)",url:"https://www.roots.gov.sg/places/places-landing/Places/surveyed-sites/fairfield-methodist-church",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:1986,label:"church moves in",source:{title:"About Us",url:"https://fairfieldmc.org/about",publisher:"Fairfield Methodist Church",checkedAt:"2026-10-31"}},{value:2005,label:"conserved by URA",source:{title:"Fairfield Methodist Church",url:"https://en.wikipedia.org/wiki/Fairfield_Methodist_Church",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-fort-canning-park-fort-gate-fort-canning-centre":{title:["Fort Canning,","the hill of kings","and a fort"],subtitle:"Cox Terrace · hilltop park, fort gate and heritage gallery",lead:"Fort Canning Hill was called Bukit Larangan, the ‘Forbidden Hill’, by the Malays. Kings of old Singapore are believed to have lived and been buried here; later Raffles built his house on the hill.",more:["In 1859 the governor’s house was pulled down to make way for a fort. It was finished in 1861 and named after Viscount Canning, the first Viceroy of India. The fort was pulled down in 1907; only its gate and two nine-pound cannons remain.","Fort Canning Centre was once a British Army barracks. Since 2022 it has held the Fort Canning Heritage Gallery, which traces more than 700 years of the hill’s history with objects dug up in the park. Nearby, the Spice Garden has more than 180 kinds of plants."],lookFor:["The Fort Gate, last part of the old fort","The Gothic gates of the old Christian cemetery","Gambier, pepper and nutmeg in the Spice Garden"],sources:[{title:"Fort Canning Hill",url:"https://en.wikipedia.org/wiki/Fort_Canning_Hill",publisher:"Wikipedia",checkedAt:"2026-10-31"},{title:"Fort Canning Park",url:"https://www.nparks.gov.sg/visit/parks/park-detail/fort-canning-park",publisher:"National Parks Board",checkedAt:"2026-10-31"},{title:"NParks opens new Fort Canning Heritage Gallery and enhanced Spice Garden at Fort Canning Park",url:"https://www.nparks.gov.sg/news/news-detail/nparks-opens-new-fort-canning-heritage-gallery-and-enhanced-spice-garden-at-fort-canning-park",publisher:"National Parks Board",checkedAt:"2026-10-31"}],clip:{title:"From palace hill to fort",seconds:90,captions:["Malays called this hill Bukit Larangan, the Forbidden Hill.","Gold jewellery from the 1300s was dug up here in 1928.","A fort was built in 1861; only its gate and two cannons remain.","Today a gallery and spice garden tell the hill’s story."],poster:{src:"nearby/cards/fort-canning-park-fort-gate-fort-canning-centre.webp",alt:"An old black cannon on a wall, pointing over the trees of Fort Canning Park",credit:"Elisa.rolle 2012 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:9-Pound_Cannon.jpg"}},tiles:[{value:1861,label:"fort completed and named",source:{title:"Fort Canning Hill",url:"https://en.wikipedia.org/wiki/Fort_Canning_Hill",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:1907,label:"fort pulled down",source:{title:"Fort Canning Hill",url:"https://en.wikipedia.org/wiki/Fort_Canning_Hill",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:180,label:"plant kinds in Spice Garden",suffix:"+",grouped:!0,source:{title:"NParks opens new Fort Canning Heritage Gallery and enhanced Spice Garden at Fort Canning Park",url:"https://www.nparks.gov.sg/news/news-detail/nparks-opens-new-fort-canning-heritage-gallery-and-enhanced-spice-garden-at-fort-canning-park",publisher:"National Parks Board",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-fullerton-building":{title:["The Fullerton,","from post office","to hotel"],subtitle:"Fullerton Square · hotel in the old General Post Office",lead:"The former Fullerton Building stands at the mouth of the Singapore River. It opened in 1928 as the General Post Office and offices, and has been The Fullerton Hotel since 2001.",more:["The site was once Fort Fullerton, named after Sir Robert Fullerton, the first Governor of the Straits Settlements. Building began in February 1924 to a design by Major Percy Keys. Inside were the post office, the Singapore Club, the Chamber of Commerce and government offices, with 14 lifts and a postal counter 300 feet long.","In February 1942 the Governor sheltered in the Singapore Club, and it was there that Lieutenant-General Arthur Percival told him of the decision to surrender. After the war the building held the Ministry of Finance and other departments. It was turned into a hotel from 1997 to 2000 and opened on 1 January 2001."],lookFor:["The giant two-storey row of Doric columns","Two bronze tablets at the Fullerton Road entrance","The vaulted coffered ceiling of the old Singapore Club"],sources:[{title:"Former Fullerton Building",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/former-fullerton-building",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}],clip:{title:"The General Post Office",seconds:100,captions:["This building at the river mouth was once the General Post Office.","It opened in 1928 on the site of old Fort Fullerton.","In 1942 the Governor heard here that Britain would surrender.","Since 2001 it has been The Fullerton Hotel."]},tiles:[{value:1928,label:"building opens",source:{title:"Former Fullerton Building",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/former-fullerton-building",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:14,label:"lifts when new",source:{title:"Former Fullerton Building",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/former-fullerton-building",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:2001,label:"opens as a hotel",source:{title:"Former Fullerton Building",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/former-fullerton-building",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}}],thenNow:{then:{src:"nearby/cards/fullerton-building-then.webp",alt:"Old postcard of the long columned Fullerton Building across the river, with bumboats in front",credit:"Unknown photographer, undated (KITLV 1404891) · CC BY 4.0",url:"https://commons.wikimedia.org/wiki/File:Singapore,_KITLV_1404891.tiff"},now:{src:"nearby/cards/fullerton-building-now.webp",alt:"The Fullerton Hotel with its row of columns and Cavenagh Bridge, seen from across the river",credit:"Vijayaraghavan2k5 2006 · CC BY-SA 2.5",url:"https://commons.wikimedia.org/wiki/File:The_Fullerton_Hotel_Singapore_seen_from_Boat_Quay_-_20061216.jpg"},thenLabel:"Undated",nowLabel:"2006",captions:{then:{lead:"Old postcard.",text:" The post office across the river, bumboats in front."},mid:{lead:"Same front, same river.",text:" The post office is now a hotel."},now:{lead:"2006.",text:" The Fullerton Hotel, seen from Boat Quay."}}},reviewedAt:"2026-10-29"},"curated:sg-fusionopolis-one":{title:["Fusionopolis One,","towers by","Kisho Kurokawa"],subtitle:"Fusionopolis Way · research and business complex",lead:"Fusionopolis One is the first phase of the Fusionopolis research complex at one-north. Research groups, tech firms, government agencies, shops and serviced apartments share its towers.",more:["Phase 1 has three towers, Connexis South, Connexis North and Symbiosis, with about 120,000 square metres of floor space. It was designed by the Japanese architect Kisho Kurokawa and opened on 17 October 2008.","JTC planned it as one-north’s first “work-live-play-learn” development. Next to offices and A*STAR research institutes there are serviced apartments, food outlets, a gym and a small theatre. One-north MRT station connects to the basement."],lookFor:["The Connexis and Symbiosis towers","The one-north MRT link in the basement"],sources:[{title:"Fusionopolis",url:"https://en.wikipedia.org/wiki/Fusionopolis",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"Work, live, play, learn",seconds:85,captions:["Fusionopolis puts labs, offices, flats and shops together.","Japanese architect Kisho Kurokawa designed Phase 1.","Its three towers hold about 120,000 m² of floor space.","PM Lee Hsien Loong opened it on 17 October 2008."],poster:{src:"nearby/cards/fusionopolis-one.webp",alt:"The twin glass towers of Fusionopolis linked by sky bridges, with building works in front",credit:"Kok Leng Yeo 2009 · CC BY 2.0",url:"https://commons.wikimedia.org/wiki/File:Fusionopolis-onenorth-BuonaVista-Singapore-20090219.jpg"}},tiles:[{value:2008,label:"officially opened",source:{title:"Fusionopolis",url:"https://en.wikipedia.org/wiki/Fusionopolis",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:3,label:"towers",source:{title:"Fusionopolis",url:"https://en.wikipedia.org/wiki/Fusionopolis",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:12e4,label:"m² floor area",grouped:!0,source:{title:"Fusionopolis",url:"https://en.wikipedia.org/wiki/Fusionopolis",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-galaxis":{title:["Galaxis,","offices above","one-north MRT"],subtitle:"Fusionopolis Place · business park tower",lead:"Galaxis is a business park building in the Fusionopolis cluster at one-north, with direct access to one-north MRT station. Firms such as Canon, Oracle and Sea have offices here.",more:["It has a 17-storey tower of business park and office space, a two-storey shop and food podium, and a five-storey block of work lofts. Its total floor area is 68,835 square metres.","Galaxis holds the BCA Green Mark Platinum rating. It is the fifth phase of Fusionopolis."],lookFor:["The direct link to one-north MRT station","Shops and food in the two-storey podium"],sources:[{title:"Ascendas Reit acquires 25% stake in Galaxis for S$102.91 million",url:"https://www.capitaland.com/en/about-capitaland/newsroom/news-releases/international/2020/mar/Ascendas-Reit-acquires-25-per-cent-stake-in-Galaxis.html",publisher:"CapitaLand",checkedAt:"2026-10-31"},{title:"Fusionopolis",url:"https://en.wikipedia.org/wiki/Fusionopolis",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"Offices on top of the MRT",seconds:80,captions:["Galaxis is a business park at the heart of Fusionopolis.","Its main tower is 17 storeys, beside a 5-storey loft block.","A two-storey podium of shops and food sits at its base.","It has direct access to one-north MRT station."]},tiles:[{value:17,label:"storeys in the main tower",source:{title:"Ascendas Reit acquires 25% stake in Galaxis for S$102.91 million",url:"https://www.capitaland.com/en/about-capitaland/newsroom/news-releases/international/2020/mar/Ascendas-Reit-acquires-25-per-cent-stake-in-Galaxis.html",publisher:"CapitaLand",checkedAt:"2026-10-31"}},{value:68835,label:"m² floor area",grouped:!0,source:{title:"Ascendas Reit acquires 25% stake in Galaxis for S$102.91 million",url:"https://www.capitaland.com/en/about-capitaland/newsroom/news-releases/international/2020/mar/Ascendas-Reit-acquires-25-per-cent-stake-in-Galaxis.html",publisher:"CapitaLand",checkedAt:"2026-10-31"}},{value:5,label:"storeys of work lofts",source:{title:"Ascendas Reit acquires 25% stake in Galaxis for S$102.91 million",url:"https://www.capitaland.com/en/about-capitaland/newsroom/news-releases/international/2020/mar/Ascendas-Reit-acquires-25-per-cent-stake-in-Galaxis.html",publisher:"CapitaLand",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-gillman-barracks":{title:["Gillman Barracks,","from army camp","to art galleries"],subtitle:"Lock Road · art galleries in old barracks",lead:"Gillman Barracks is a cluster of art galleries and restaurants in conserved colonial barracks off Alexandra Road. It was built in 1936 and named after General Sir Webb Gillman of the British Army.",more:["The camp housed British soldiers before World War Two and was one of Singapore’s last battle sites before it fell in 1942. In August 1971 the British handed it to the Singapore Armed Forces for a token $1, and the SAF used it until 1990.","It opened as an art cluster in September 2012 with 13 galleries, though several later left. The Singapore Land Authority has managed the site since March 2020 and is adding food and lifestyle shops."],lookFor:["The AKC army cinema logo on Block 7","Wide corridors and high arches of Block 9","Old steps up to the former hilltop school, near Block 37"],sources:[{title:"Gillman Barracks – A Vibrant Lifestyle Enclave",url:"https://www.sla.gov.sg/articles/gillman-barracks---a-vibrant-lifestyle-enclave/",publisher:"Singapore Land Authority",checkedAt:"2026-10-31"},{title:"Gillman Barracks",url:"https://en.wikipedia.org/wiki/Gillman_Barracks",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"From barracks to art cluster",seconds:95,captions:["Art galleries and restaurants fill these old army barracks.","The British Army built the camp in 1936.","In 1971 the British handed it to Singapore’s army for $1.","Spot the old army cinema logo on Block 7."]},tiles:[{value:1936,label:"barracks built",source:{title:"Gillman Barracks – A Vibrant Lifestyle Enclave",url:"https://www.sla.gov.sg/articles/gillman-barracks---a-vibrant-lifestyle-enclave/",publisher:"Singapore Land Authority",checkedAt:"2026-10-31"}},{value:17,label:"colonial State properties",source:{title:"Gillman Barracks – A Vibrant Lifestyle Enclave",url:"https://www.sla.gov.sg/articles/gillman-barracks---a-vibrant-lifestyle-enclave/",publisher:"Singapore Land Authority",checkedAt:"2026-10-31"}},{value:2012,label:"art cluster opens",source:{title:"Gillman Barracks",url:"https://en.wikipedia.org/wiki/Gillman_Barracks",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-golden-mile-complex":{title:["Golden Mile Complex,","a stepped","vertical city"],subtitle:"Beach Road · homes, offices and shops",lead:"Golden Mile Complex, first called Woh Hup Complex, is a 16-storey building between Nicoll Highway and Beach Road. It was one of the first in Singapore to put shops, offices and homes in one building.",more:["It was designed by Gan Eng Oon, William Lim and Tay Kheng Soon of Design Partnership, now DP Architects. Its stepped, terraced shape lets in natural light and air.","Thai shops and eateries made it a gathering place for the Thai community, and it became known as 'Little Thailand'. It was gazetted for conservation in October 2021 and sold in 2022 to a group that will redevelop it."],lookFor:["The stepped terraces facing Kallang Basin","Bus agencies for trips to Malaysia and Thailand"],sources:[{title:"Golden Mile Complex",url:"https://www.nlb.gov.sg/main/article-detail?cmsuuid=7df2d048-bab3-48cf-895f-2fc15a6410ab",publisher:"National Library Board (Singapore Infopedia)",checkedAt:"2026-10-31"},{title:"The Golden Mile, Singapore",url:"https://en.wikipedia.org/wiki/The_Golden_Mile,_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"Little Thailand",seconds:96,captions:["This 16-storey block mixes homes, offices and shops.","It was first called Woh Hup Complex.","Its stepped terraces let in light and air.","In 2021 it was gazetted for conservation."]},tiles:[{value:16,label:"storeys",source:{title:"Golden Mile Complex",url:"https://www.nlb.gov.sg/main/article-detail?cmsuuid=7df2d048-bab3-48cf-895f-2fc15a6410ab",publisher:"National Library Board (Singapore Infopedia)",checkedAt:"2026-10-31"}},{value:2021,label:"gazetted for conservation",source:{title:"Golden Mile Complex",url:"https://www.nlb.gov.sg/main/article-detail?cmsuuid=7df2d048-bab3-48cf-895f-2fc15a6410ab",publisher:"National Library Board (Singapore Infopedia)",checkedAt:"2026-10-31"}},{value:411,label:"shops (2007)",source:{title:"Golden Mile Complex",url:"https://www.nlb.gov.sg/main/article-detail?cmsuuid=7df2d048-bab3-48cf-895f-2fc15a6410ab",publisher:"National Library Board (Singapore Infopedia)",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-gu-um":{title:["Gu:um,","Korean food","over charcoal"],subtitle:"Keong Saik Road · Korean charcoal grill",lead:"Gu:um is a casual Korean grill from chef Louis Han, who also runs the Michelin-starred NAE:UM. It is in a heritage shophouse on Keong Saik Road.",more:["Its dishes are cooked over a modern charcoal grill, and it seats about 40 people.","Keong Saik Road is on the edge of the Bukit Pasoh area, built up in the early 1920s. Shophouses along the road received conservation status on 12 April 1990."],lookFor:["Two- and three-storey shophouses on Keong Saik Road","The Hindu temple at Keong Saik and Kreta Ayer Road"],sources:[{title:"Chef of Michelin-starred restaurant opens Korean grill eatery at Keong Saik Road",url:"https://mothership.sg/2024/06/korean-restaurant-chinatown/",publisher:"Mothership",checkedAt:"2026-10-31"},{title:"Chinatown - Bukit Pasoh Conservation Area",url:"https://www.ura.gov.sg/conservation/find-a-building/conservation-portal/bkps/",publisher:"Urban Redevelopment Authority (URA)",checkedAt:"2026-10-31"}],clip:{title:"Cooked over fire",seconds:90,captions:["Gu:um is a Korean grill by Louis Han, the chef of NAE:UM.","It is in a heritage shophouse on Keong Saik Road.","Its dishes are cooked over a modern charcoal grill.","It seats about 40 people."],poster:{src:"nearby/cards/sg-gu-um.webp",alt:"Keong Saik Road, the street where Gu:um is, with shophouses and the Hindu temple (not the restaurant itself)",credit:"Torbenbrinker 2015 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:KeongSaikRdSingapore.jpg"}},tiles:[{value:40,label:"seats (about)",source:{title:"Chef of Michelin-starred restaurant opens Korean grill eatery at Keong Saik Road",url:"https://mothership.sg/2024/06/korean-restaurant-chinatown/",publisher:"Mothership",checkedAt:"2026-10-31"}},{value:1920,label:"Bukit Pasoh area built",suffix:"s",source:{title:"Chinatown - Bukit Pasoh Conservation Area",url:"https://www.ura.gov.sg/conservation/find-a-building/conservation-portal/bkps/",publisher:"Urban Redevelopment Authority (URA)",checkedAt:"2026-10-31"}},{value:1990,label:"Keong Saik row conserved",source:{title:"Chinatown - Bukit Pasoh Conservation Area",url:"https://www.ura.gov.sg/conservation/find-a-building/conservation-portal/bkps/",publisher:"Urban Redevelopment Authority (URA)",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-guoco-tower":{title:["Guoco Tower,","Singapore's","tallest building"],subtitle:"Wallich Street · mixed-use skyscraper",lead:"At 290 metres, Guoco Tower is the tallest building in Singapore. It was formerly called Tanjong Pagar Centre and was designed by Skidmore, Owings & Merrill (SOM) for GuocoLand.",more:["It is the only skyscraper exempted from Singapore's 280-metre height limit. It broke the record held for more than 20 years by UOB Plaza, One Raffles Place and Republic Plaza.","The tower holds offices, the Wallich Residence apartments, Sofitel Singapore City Centre and a mall, with transit links and a large public park."],lookFor:["The large public park at Guoco Tower","Shops and food in the tower's mall"],sources:[{title:"Guoco Tower",url:"https://www.som.com/projects/guoco-tower/",publisher:"Skidmore, Owings & Merrill (SOM)",checkedAt:"2026-10-31"},{title:"Guoco Tower",url:"https://en.wikipedia.org/wiki/Guoco_Tower",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"290 metres up",seconds:90,captions:["Guoco Tower rises 290 metres at Tanjong Pagar.","It was once called Tanjong Pagar Centre.","SOM designed it with offices, homes, a hotel and shops.","It is the only tower allowed above the 280 m height limit."],poster:{src:"nearby/cards/sg-guoco-tower.webp",alt:"Guoco Tower's dark glass tower against a blue sky, with cranes on the right",credit:"Bjoertvedt 2020 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Singapore_-_Guoco_Tower_IMG_9657_cropped.jpg"}},tiles:[{value:290,label:"metres tall",source:{title:"Guoco Tower",url:"https://www.som.com/projects/guoco-tower/",publisher:"Skidmore, Owings & Merrill (SOM)",checkedAt:"2026-10-31"}},{value:2012,label:"design finished",source:{title:"Guoco Tower",url:"https://www.som.com/projects/guoco-tower/",publisher:"Skidmore, Owings & Merrill (SOM)",checkedAt:"2026-10-31"}},{value:2019,label:"ULI award for excellence",source:{title:"Guoco Tower",url:"https://www.som.com/projects/guoco-tower/",publisher:"Skidmore, Owings & Merrill (SOM)",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-haw-par-villa":{title:["Haw Par Villa,","a garden of","Chinese legends"],subtitle:"Pasir Panjang Road · folklore park and Hell’s Museum",lead:"Haw Par Villa is a theme park on Pasir Panjang Road. It has over 1,000 statues and 150 large dioramas of scenes from Chinese legends, folklore and history.",more:["Aw Boon Haw and Aw Boon Par, the brothers behind Tiger Balm, bought the site in 1935. The park’s name comes from theirs: “Haw” means tiger and “Par” means leopard. Until his death in 1954, Boon Haw paid for statues and scenes that taught traditional Chinese values.","Its best-known scene is the Ten Courts of Hell, a frightening picture of hell in Chinese myth and Buddhism. Since October 2021 it has been the centre of Hell’s Museum, a museum about death and the afterlife. From 8 December 2025 much of the park closed for repairs, while Hell’s Museum stayed open (daily, 10am to 6pm)."],lookFor:["The Ten Courts of Hell inside Hell’s Museum","Scenes from Journey to the West and the White Snake","Monuments to the Aw brothers and their parents"],sources:[{title:"Haw Par Villa",url:"https://en.wikipedia.org/wiki/Haw_Par_Villa",publisher:"Wikipedia",checkedAt:"2026-10-31"},{title:"Plan Your Visit",url:"https://www.hawparvilla.sg/plan-your-visit/",publisher:"Haw Par Villa",checkedAt:"2026-10-31"}],clip:{title:"Built by the Tiger Balm brothers",seconds:90,captions:["Over 1,000 statues tell Chinese legends and moral tales.","Tiger Balm’s Aw Boon Haw and Aw Boon Par opened it in 1937.","“Haw” and “Par” mean tiger and leopard: the brothers’ names.","Today Hell’s Museum shows the famous Ten Courts of Hell."]},tiles:[{value:1937,label:"park opens",source:{title:"Haw Par Villa",url:"https://en.wikipedia.org/wiki/Haw_Par_Villa",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:1e3,label:"statues",suffix:"+",grouped:!0,source:{title:"Haw Par Villa",url:"https://en.wikipedia.org/wiki/Haw_Par_Villa",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:2021,label:"Hell’s Museum opens",source:{title:"Haw Par Villa",url:"https://en.wikipedia.org/wiki/Haw_Par_Villa",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-helix-bridge":{title:["Helix Bridge,","a strand of DNA","over the bay"],subtitle:"Marina Bay · footbridge",lead:"The Helix is a footbridge linking Marina Centre with Marina South. Half of it opened on 24 April 2010, and the whole bridge on 18 July 2010, completing the walk around Marina Bay.",more:["The Cox Architecture team from Australia, the engineers Arup and Architects 61 of Singapore designed it. About 650 tonnes of duplex stainless steel went into it. Its twist turns left, the opposite way to real DNA.","At night, pairs of letters c and g, a and t light up in red and green. They stand for cytosine, guanine, adenine and thymine, the four bases of DNA."],lookFor:["The lit letters c, g, a and t after dark","Four viewing platforms over the bay","Glass and steel-mesh canopies giving shade"],sources:[{title:"Helix Bridge",url:"https://en.wikipedia.org/wiki/Helix_Bridge",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"A bridge shaped like DNA",seconds:90,captions:["The Helix is a footbridge between Marina Centre and Marina South.","Its steel twists like DNA, but the opposite way to real DNA.","At night, letters c, g, a and t light up in red and green.","Stop at its four viewing platforms over the bay."]},tiles:[{value:2010,label:"bridge opens",source:{title:"Helix Bridge",url:"https://en.wikipedia.org/wiki/Helix_Bridge",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:280,label:"long",suffix:" m",source:{title:"Helix Bridge",url:"https://en.wikipedia.org/wiki/Helix_Bridge",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:650,label:"tonnes of stainless steel",grouped:!0,source:{title:"Helix Bridge",url:"https://en.wikipedia.org/wiki/Helix_Bridge",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-hoo-kee-bak-chang":{title:["Hoo Kee,","Hokkien rice dumplings","since 1948"],subtitle:"Amoy Street Food Centre · bak chang",lead:"Hoo Kee Bak Chang sells Hokkien rice dumplings at Amoy Street Food Centre. Chew Hai Chwee began selling them along Amoy Street in 1948, with help from his wife, Lim Seok Loo.",more:["With his success he took over the Fu Xing coffee shop and gave his family of 13 a home. As Singapore’s city was rebuilt, the stall was moved into Amoy Street Food Centre, and the business passed among his three sons.","The dumplings are made fresh every morning and wrapped by hand. Eatbook lists four kinds, from a plain chestnut dumpling to one with pork, salted egg and mushroom."],lookFor:["Piles of wrapped dumplings at stall #01-18","Cut one open: pork, chestnut, salted egg yolk","Lunchtime trade: it closes in mid-afternoon"],sources:[{title:"Our Story",url:"https://www.hookeebakchang.sg/our-story",publisher:"Hoo Kee Bak Chang",checkedAt:"2026-10-29"},{title:"Hoo Kee Bak Chang: Michelin Bib Gourmand rice dumpling stall",url:"https://eatbook.sg/hoo-kee-bak-chang/",publisher:"Eatbook (food blog)",checkedAt:"2026-10-29"},{title:"Zongzi",url:"https://en.wikipedia.org/wiki/Zongzi",publisher:"Wikipedia",checkedAt:"2026-10-29"}],clip:{title:"Wrapped by hand since 1948",seconds:90,captions:["Bak chang is Hokkien for a meat rice dumpling.","Chew Hai Chwee began selling them on Amoy Street in 1948.","His success fed and housed a family of 13.","The dumplings are still made fresh every morning."],poster:{src:"nearby/cards/sg-hoo-kee-bak-chang.webp",alt:"Amoy Street Food Centre in 2006, where the stall is (not the stall itself)",credit:"Terence Ong 2006 · CC BY 2.5",url:"https://commons.wikimedia.org/wiki/File:Amoy_Street_Food_Centre.JPG"}},tiles:[{value:1948,label:"first dumplings on Amoy St",source:{title:"Our Story",url:"https://www.hookeebakchang.sg/our-story",publisher:"Hoo Kee Bak Chang",checkedAt:"2026-10-29"}},{value:13,label:"family members housed",source:{title:"Our Story",url:"https://www.hookeebakchang.sg/our-story",publisher:"Hoo Kee Bak Chang",checkedAt:"2026-10-29"}},{value:3,label:"sons who ran it in turn",source:{title:"Our Story",url:"https://www.hookeebakchang.sg/our-story",publisher:"Hoo Kee Bak Chang",checkedAt:"2026-10-29"}}],orderProposal:{kind:"bak-chang",title:"Order bak chang",intro:"Bak chang means “meat zong”: glutinous rice with pork, wrapped in leaves. Pick the filling.",base:"one bak chang",baseMeaning:"One rice dumpling",steps:[{id:"greet",question:"Who is at the counter?",options:[{id:"uncle",label:"Uncle",term:"Uncle,",meaning:""},{id:"auntie",label:"Auntie",term:"Auntie,",meaning:""}]},{id:"filling",question:"Which filling?",options:[{id:"chestnut",label:"Chestnut",term:"chestnut",meaning:"with chestnut"},{id:"egg",label:"Salted egg + chestnut",term:"salted egg",meaning:"with salted egg and chestnut"},{id:"mushroom",label:"Mushroom + chestnut",term:"mushroom",meaning:"with mushroom and chestnut"},{id:"all",label:"All in",term:"salted egg and mushroom",meaning:"with pork, chestnut, salted egg and mushroom"}],note:"Eatbook (June 2023) lists these four; all have pork belly in the rice."},{id:"where",question:"Eat here or take away?",options:[{id:"here",label:"Having here",term:"having here",meaning:"to eat here"},{id:"dabao",label:"Da bao",term:"da bao",meaning:"to take away"}]}],sources:[{title:"Hoo Kee Bak Chang: Michelin Bib Gourmand rice dumpling stall",url:"https://eatbook.sg/hoo-kee-bak-chang/",publisher:"Eatbook (food blog)",checkedAt:"2026-10-29"},{title:"Zongzi",url:"https://en.wikipedia.org/wiki/Zongzi",publisher:"Wikipedia",checkedAt:"2026-10-29"},{title:"Singlish vocabulary",url:"https://en.wikipedia.org/wiki/Singlish_vocabulary",publisher:"Wikipedia",checkedAt:"2026-10-29"}]},reviewedAt:"2026-10-29"},"curated:sg-hortpark":{title:["HortPark,","a park for","learning to garden"],subtitle:"Hyderabad Road · gardening park on the Southern Ridges",lead:"HortPark is a 9-hectare park on the Southern Ridges. NParks calls it a one-stop gardening resource hub, with gardens to explore, workshops and plant shops.",more:["It opened in December 2007 and was officially launched by Prime Minister Lee Hsien Loong in May 2008. Its two-storey HortCentre is the visitor centre and has a display of green roofs.","A butterfly garden opened in 2009 to help breed native butterflies. Along the bee trail, bee hotels give nesting space to bees such as the Pearly-banded Bee. Please do not touch them."],lookFor:["Bee hotels along the bee trail (don’t touch)","Common Rose and Lime butterflies in the butterfly garden","The green roof display on the HortCentre"],sources:[{title:"HortPark",url:"https://www.nparks.gov.sg/visit/parks/park-detail/hortpark",publisher:"National Parks Board (NParks)",checkedAt:"2026-10-31"},{title:"HortPark",url:"https://en.wikipedia.org/wiki/HortPark",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"A hub for gardeners",seconds:90,captions:["NParks calls HortPark a one-stop gardening resource hub.","The 9-hectare park opened in December 2007.","Bee hotels on the bee trail give bees a place to nest.","Bridges and walkways link it to Kent Ridge and Mount Faber."],poster:{src:"nearby/cards/hortpark.webp",alt:"The Silver Garden at HortPark: silver-leaved palms and plants around a lawn and a pond",credit:"kallerna 2026 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Silver_Garden_HortPark_Singapore.jpg"}},tiles:[{value:2007,label:"park opens",source:{title:"HortPark",url:"https://en.wikipedia.org/wiki/HortPark",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:9,label:"park area",suffix:" ha",source:{title:"HortPark",url:"https://en.wikipedia.org/wiki/HortPark",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:2009,label:"butterfly garden opens",source:{title:"HortPark",url:"https://en.wikipedia.org/wiki/HortPark",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-house-of-tan-teng-niah":{title:["Tan Teng Niah’s house,","Little India’s last","Chinese villa"],subtitle:"Kerbau Road · former Chinese villa",lead:"Built in 1900, the house of Tan Teng Niah is the last surviving Chinese villa in Little India. Tan was a businessman who owned sweet-making factories along Serangoon Road.",more:["Behind the house he had a smoke-house for drying rubber, fuelled by waste from sugarcane. The house has eight rooms, and its upper floor hangs over a five-foot way.","Over the door is a gilded name plate reading ‘Siew Song’, elegant pine, a sign of endurance. Many believe Tan built the house for his wife. It was restored in the 1980s for shops and won an architecture award in 1991."],lookFor:["Carved pintu pagar half doors","The gilded ‘Siew Song’ name plate","The upper floor over the five-foot way"],sources:[{title:"Former House of Tan Teng Niah",url:"https://www.roots.gov.sg/places/places-landing/Places/landmarks/little-india-heritage-trail-serangoon-in-the-1900s/former-house-of-tan-teng-niah",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}],clip:{title:"A sweet-maker’s villa",seconds:85,captions:["This is the last Chinese villa left in Little India.","Tan Teng Niah, a sweet-maker, built it in 1900.","Over the door, a gilded sign reads ‘Siew Song’, elegant pine.","Many believe he built the house for his wife."]},tiles:[{value:1900,label:"villa built",source:{title:"Former House of Tan Teng Niah",url:"https://www.roots.gov.sg/places/places-landing/Places/landmarks/little-india-heritage-trail-serangoon-in-the-1900s/former-house-of-tan-teng-niah",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:8,label:"rooms",grouped:!0,source:{title:"Former House of Tan Teng Niah",url:"https://www.roots.gov.sg/places/places-landing/Places/landmarks/little-india-heritage-trail-serangoon-in-the-1900s/former-house-of-tan-teng-niah",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:1991,label:"restoration award",source:{title:"Former House of Tan Teng Niah",url:"https://www.roots.gov.sg/places/places-landing/Places/landmarks/little-india-heritage-trail-serangoon-in-the-1900s/former-house-of-tan-teng-niah",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-indian-heritage-centre":{title:["Indian Heritage Centre,","a stepwell","of glass"],subtitle:"Campbell Lane · museum of Indian heritage",lead:"The Indian Heritage Centre on Campbell Lane tells the story of the Indian and South Asian community in Singapore. It opened in May 2015.",more:["The four-storey building has five permanent galleries. Its front is inspired by the baoli, an Indian stepwell: a deep well with steps going down to the water. Visitors move between galleries along stairs and balconies behind the glass.","By day the glass reflects the sky. At night it lights up as a bright mural of Little India. Visit first, then walk through Little India's streets."],lookFor:["Stairs behind the glass front, like a stepwell","The front lit up as a mural after dark","Nandi bull sculptures from the old Sri Sivan temple"],sources:[{title:"Introduction",url:"https://www.indianheritage.gov.sg/en/about-us/introduction",publisher:"Indian Heritage Centre",checkedAt:"2026-10-31"},{title:"Indian Heritage Centre",url:"https://en.wikipedia.org/wiki/Indian_Heritage_Centre",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"A stepwell in Little India",seconds:90,captions:["This museum tells the story of Indians in Singapore.","It opened in May 2015 on Campbell Lane.","Its front is inspired by the baoli, an Indian stepwell.","At night the glass front glows like a mural of Little India."]},tiles:[{value:2015,label:"centre opens",source:{title:"Introduction",url:"https://www.indianheritage.gov.sg/en/about-us/introduction",publisher:"Indian Heritage Centre",checkedAt:"2026-10-31"}},{value:5,label:"permanent galleries",source:{title:"Introduction",url:"https://www.indianheritage.gov.sg/en/about-us/introduction",publisher:"Indian Heritage Centre",checkedAt:"2026-10-31"}},{value:4,label:"storeys",source:{title:"Introduction",url:"https://www.indianheritage.gov.sg/en/about-us/introduction",publisher:"Indian Heritage Centre",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-jaan-by-kirk-westaway":{title:["JAAN,","British cooking","70 floors up"],subtitle:"Stamford Road · modern British, two MICHELIN stars",lead:"JAAN is a modern British restaurant on level 70 of Swissôtel The Stamford. Chef Kirk Westaway calls his food “reinvented British cuisine”, drawn from memories of his childhood in Devon.",more:["The menu changes with the seasons, and the chef also picks the suppliers, the furniture and the tableware. JAAN had one MICHELIN star from the first Singapore guide in 2016 and has held two since 2021.","The hotel, designed by I. M. Pei, opened in 1986. At 226 metres it was the world’s tallest hotel until 1997. Julien Royer led JAAN’s kitchen before he opened Odette."],lookFor:["The city view from the 70th floor","Furniture and tableware chosen by the chef"],sources:[{title:"JAAN by Kirk Westaway",url:"https://www.swissotel.com/hotels/singapore-stamford/dining/jaan",publisher:"Swissôtel The Stamford",checkedAt:"2026-10-31"},{title:"About",url:"https://www.jaan.sg/about",publisher:"JAAN by Kirk Westaway",checkedAt:"2026-10-31"},{title:"Jaan by Kirk Westaway",url:"https://www.the50.com/asia/en/the-list/Jaan-by-Kirk-Westaway.html",publisher:"Asia's 50 Best Restaurants",checkedAt:"2026-10-31"},{title:"Swissôtel The Stamford",url:"https://en.wikipedia.org/wiki/Swissôtel_The_Stamford",publisher:"Wikipedia",checkedAt:"2026-10-31"},{title:"List of Michelin-starred restaurants in Singapore",url:"https://en.wikipedia.org/wiki/List_of_Michelin-starred_restaurants_in_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"},{title:"Odette (restaurant)",url:"https://en.wikipedia.org/wiki/Odette_(restaurant)",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"Devon, 70 floors up",seconds:90,captions:["JAAN sits on level 70 of Swissôtel The Stamford.","Chef Kirk Westaway cooks modern British food.","He draws on memories of growing up in Devon.","The 35-seat room looks out over the city."],poster:{src:"nearby/cards/jaan-by-kirk-westaway.webp",alt:"The round tower of Swissôtel The Stamford; JAAN is on level 70 (not the restaurant itself)",credit:"Diego Delso 2023 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Swiss%C3%B4tel_The_Stamford,_Singapur,_2023-08-18,_DD_18.jpg"}},tiles:[{value:70,label:"level of the restaurant",source:{title:"JAAN by Kirk Westaway",url:"https://www.swissotel.com/hotels/singapore-stamford/dining/jaan",publisher:"Swissôtel The Stamford",checkedAt:"2026-10-31"}},{value:1986,label:"hotel opens, world’s tallest",source:{title:"Swissôtel The Stamford",url:"https://en.wikipedia.org/wiki/Swissôtel_The_Stamford",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:2021,label:"two MICHELIN stars",source:{title:"JAAN by Kirk Westaway",url:"https://www.swissotel.com/hotels/singapore-stamford/dining/jaan",publisher:"Swissôtel The Stamford",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-jin-ting-wan":{title:["Jin Ting Wan,","Cantonese food","on level 55"],subtitle:"Marina Bay Sands Tower 1 · Cantonese",lead:"Jin Ting Wan is a Cantonese restaurant that takes up all of level 55 in Marina Bay Sands Hotel Tower One. Its name means “Golden Dragonfly Bay”.",more:["“Jin” means gold, the first character of Marina Bay Sands in Chinese; “ting” is dragonfly and “wan” is water, which brings luck. The floor is split by view: one side faces the city, the other the sea.","Chef Albert Li, born in Guangxi, has cooked for about two decades and led MICHELIN-starred kitchens such as Imperial Treasure Fine Chinese Cuisine in Shanghai. Jin Ting Wan won its first MICHELIN star in 2026."],lookFor:["Dragonfly motifs in the décor","City views on one side, sea views on the other","The Chef’s Table for eight"],sources:[{title:"Jin Ting Wan at Marina Bay Sands",url:"https://www.robbreport.com.sg/jin-ting-wan-marina-bay-sands/",publisher:"Robb Report Singapore",checkedAt:"2026-10-31"},{title:"Jin Ting Wan: high-rise dining at Marina Bay Sands",url:"https://elle.com.sg/life-culture/food/marina-bay-sands-jin-ting-wan-high-rise-dining/",publisher:"ELLE Singapore",checkedAt:"2026-10-31"},{title:"List of Michelin-starred restaurants in Singapore",url:"https://en.wikipedia.org/wiki/List_of_Michelin-starred_restaurants_in_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"Golden Dragonfly Bay",seconds:90,captions:["Jin Ting Wan means “Golden Dragonfly Bay” in Mandarin.","“Jin”, gold, is the first character of Marina Bay Sands.","It fills a whole floor, level 55 of Hotel Tower One.","Its pipa duck is finished in a custom-built oven."],poster:{src:"nearby/cards/jin-ting-wan.webp",alt:"Marina Bay Sands’ three hotel towers across the water; Jin Ting Wan is on level 55 of Tower 1 (not the restaurant itself)",credit:"Dietmar Rabich 2019 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Singapore_(SG),_Marina_Bay_Sands_Hotel_--_2019_--_4535.jpg"}},tiles:[{value:55,label:"level, Hotel Tower One",source:{title:"Jin Ting Wan at Marina Bay Sands",url:"https://www.robbreport.com.sg/jin-ting-wan-marina-bay-sands/",publisher:"Robb Report Singapore",checkedAt:"2026-10-31"}},{value:4,label:"private rooms and suites",source:{title:"Jin Ting Wan: high-rise dining at Marina Bay Sands",url:"https://elle.com.sg/life-culture/food/marina-bay-sands-jin-ting-wan-high-rise-dining/",publisher:"ELLE Singapore",checkedAt:"2026-10-31"}},{value:2026,label:"first MICHELIN star",source:{title:"List of Michelin-starred restaurants in Singapore",url:"https://en.wikipedia.org/wiki/List_of_Michelin-starred_restaurants_in_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-jinrikisha-station":{title:["Jinrikisha Station,","where rickshaws","were run"],subtitle:"Neil Road · former rickshaw office",lead:"The former Jinrikisha Station stands on a triangle-shaped corner at 1 Neil Road in Tanjong Pagar. The Municipal Council built it in 1903 as the administration centre for rickshaws.",more:["Rickshaws came to Singapore from Japan, by way of Shanghai, in the 1880s. Many early Chinese immigrants made a hard living as rickshaw pullers.","The building has a square corner tower with an eight-sided cupola, a curved pediment and Ionic pilasters. In 1987 it was one of the first buildings in Tanjong Pagar to be restored by the Urban Redevelopment Authority."],lookFor:["The square tower with an eight-sided cupola","The Municipal Council crest: lion and palm tree","Ionic pilasters and the curved pediment"],sources:[{title:"1 Neil Road",url:"https://www.ura.gov.sg/conservation/find-a-building/conservation-portal/tjpa-00150/",publisher:"Urban Redevelopment Authority (URA)",checkedAt:"2026-10-31"},{title:"Former Jinricksha Station",url:"https://www.roots.gov.sg/places/places-landing/Places/landmarks/chinatown-clans-associations-trail/former-jinricksha-station",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"},{title:"Jinrikisha Station",url:"https://en.wikipedia.org/wiki/Jinrikisha_Station",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"The rickshaw office",seconds:90,captions:["This corner building was the office that ran Singapore's rickshaws.","Rickshaws came from Japan, by way of Shanghai, in the 1880s.","The Municipal Council built it in 1903.","Look up at the corner tower and its eight-sided cupola."]},tiles:[{value:1880,label:"rickshaws arrive",suffix:"s",source:{title:"1 Neil Road",url:"https://www.ura.gov.sg/conservation/find-a-building/conservation-portal/tjpa-00150/",publisher:"Urban Redevelopment Authority (URA)",checkedAt:"2026-10-31"}},{value:1903,label:"station built",source:{title:"1 Neil Road",url:"https://www.ura.gov.sg/conservation/find-a-building/conservation-portal/tjpa-00150/",publisher:"Urban Redevelopment Authority (URA)",checkedAt:"2026-10-31"}},{value:1987,label:"restored by URA",source:{title:"Jinrikisha Station",url:"https://en.wikipedia.org/wiki/Jinrikisha_Station",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-kok-sen":{title:["Kok Sen,","zi char on","Keong Saik Road"],subtitle:"Keong Saik Road · zi char restaurant",lead:"Kok Sen is a zi char restaurant at 2/4 Keong Saik Road, run by the third generation of the Wong family. Its history goes back to the 1960s.",more:["The menu has classics such as seafood, eggplant, tofu in claypot and curry fish tail. Some special dishes, like braised pork belly with salted mustard greens, are made only from April to September. In January 2025 it opened a second outlet at City Square Mall, its first expansion in 54 years on Keong Saik Road.","Keong Saik Road was named in 1926 after Tan Keong Saik, a businessman born in Malacca. Its shophouses were given conservation status in 1990 and 1991."],lookFor:["Conserved shophouses along Keong Saik Road","Cundhi Gong Temple (1928) on the same road","Tables of six or more can book ahead"],sources:[{title:"Kok Sen Restaurant 国成餐室",url:"https://chinatown.sg/dine/kok-sen/",publisher:"Chinatown Singapore (Chinatown Business Association)",checkedAt:"2026-10-29"},{title:"Zi char institution Kok Sen opens new restaurant at City Square Mall",url:"https://www.stomp.sg/trending-now/food-picks-zi-char-institution-kok-sen-opens-new-restaurant-city-square-mall",publisher:"Stomp (SPH Media)",checkedAt:"2026-10-29"},{title:"Keong Saik Road",url:"https://en.wikipedia.org/wiki/Keong_Saik_Road",publisher:"Wikipedia",checkedAt:"2026-10-29"}],clip:{title:"Three generations of zi char",seconds:90,captions:["Kok Sen serves zi char classics like curry fish tail.","Its history goes back to the 1960s.","The Wong family runs it now, in the third generation.","In 2025 it had been on Keong Saik Road for 54 years."],poster:{src:"nearby/cards/sg-kok-sen.webp",alt:"Keong Saik Road at dusk, with shophouses and a corner building (the street, not the restaurant)",credit:"Vavavis 2017 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Keong_Saik_Road_Singapore.jpg"}},tiles:[{value:1960,label:"history begins",source:{title:"Zi char institution Kok Sen opens new restaurant at City Square Mall",url:"https://www.stomp.sg/trending-now/food-picks-zi-char-institution-kok-sen-opens-new-restaurant-city-square-mall",publisher:"Stomp (SPH Media)",checkedAt:"2026-10-29"},suffix:"s"},{value:3,label:"generations of Wongs",source:{title:"Kok Sen Restaurant 国成餐室",url:"https://chinatown.sg/dine/kok-sen/",publisher:"Chinatown Singapore (Chinatown Business Association)",checkedAt:"2026-10-29"}},{value:54,label:"years on Keong Saik (2025)",source:{title:"Zi char institution Kok Sen opens new restaurant at City Square Mall",url:"https://www.stomp.sg/trending-now/food-picks-zi-char-institution-kok-sen-opens-new-restaurant-city-square-mall",publisher:"Stomp (SPH Media)",checkedAt:"2026-10-29"}}],reviewedAt:"2026-10-29"},"curated:sg-kum-yan-methodist-church":{title:["Kum Yan Methodist,","a Cantonese church","since 1918"],subtitle:"Queen Street · Methodist church",lead:"Kum Yan Methodist Church began in 1918 as a church for Cantonese speakers. Its home is at 1 Queen Street, in the Bras Basah area.",more:["A small group of Christian teachers came from China to lead Yeung Ching School in Chinatown. They started Cantonese worship services at the school, and the church grew from there.","It began as a purely dialect-speaking church. Over the years it added services in English and Mandarin. On 4 March 2018 all its congregations met for a centennial thanksgiving service; it then had over 1,200 members."],lookFor:["The church at 1 Queen Street","Notices for Cantonese, English and Mandarin services"],sources:[{title:"Heart of KYMC",url:"https://kumyan.org.sg/about/heart-of-kymc/",publisher:"Kum Yan Methodist Church",checkedAt:"2026-10-31"},{title:"Kum Yan MC: 100 years in thanks",url:"https://methodistmessage.sg/kum-yan-mc-100-years-in-thanks/",publisher:"Methodist Message",checkedAt:"2026-10-31"}],clip:{title:"Sermons in Cantonese",seconds:85,captions:["Teachers from China came to run Yeung Ching School.","They began Cantonese services at the school.","The church grew from that start in 1918.","Today it worships in Cantonese, English and Mandarin."],poster:{src:"nearby/cards/sg-kum-yan-methodist-church.webp",alt:"The church’s long, multi-storey buildings with verandahs, and its name sign at the gate",credit:"Terence Ong 2006 · CC BY 2.5",url:"https://commons.wikimedia.org/wiki/File:Kum_Yan_Methodist_Church.JPG"}},tiles:[{value:1918,label:"church begins",source:{title:"Heart of KYMC",url:"https://kumyan.org.sg/about/heart-of-kymc/",publisher:"Kum Yan Methodist Church",checkedAt:"2026-10-31"}},{value:2018,label:"centennial service",source:{title:"Kum Yan MC: 100 years in thanks",url:"https://methodistmessage.sg/kum-yan-mc-100-years-in-thanks/",publisher:"Methodist Message",checkedAt:"2026-10-31"}},{value:1200,label:"members (2018)",suffix:"+",grouped:!0,source:{title:"Kum Yan MC: 100 years in thanks",url:"https://methodistmessage.sg/kum-yan-mc-100-years-in-thanks/",publisher:"Methodist Message",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-kwan-im-thong-hood-cho-temple":{title:["Kwan Im Thong Hood Cho,","goddess of mercy"],subtitle:"Waterloo Street · Chinese Buddhist temple",lead:"Kwan Im Thong Hood Cho Temple on Waterloo Street is dedicated to Kuan Yin, the goddess of mercy. Inscriptions at the temple say it began in 1884, when a company donated the land.",more:["It was renovated in 1895. In 1980 it was greatly expanded at a cost of $5 million and now covers 1,500 square metres, almost twice its first size.","Many worshippers here also pray at the Sri Krishnan Temple next door, and that temple has a statue of Guanyin for them. This ‘cross-worshipping’ is often seen as a picture of Singapore’s many faiths."],lookFor:["The Four Heavenly Kings above the altar","A Buddha statue behind Kuan Yin","The Sri Krishnan Temple next door"],sources:[{title:"Kwan Im Thong Hood Cho Temple",url:"https://en.wikipedia.org/wiki/Kwan_Im_Thong_Hood_Cho_Temple",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"Two temples, one street",seconds:90,captions:["People come here to pray to Kuan Yin, goddess of mercy.","The temple began in 1884 on land given by a company.","In 1980 it was rebuilt at almost double its first size.","Many visitors also pray at the Hindu temple next door."]},tiles:[{value:1884,label:"temple begins",source:{title:"Kwan Im Thong Hood Cho Temple",url:"https://en.wikipedia.org/wiki/Kwan_Im_Thong_Hood_Cho_Temple",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:1980,label:"rebuilt and enlarged",source:{title:"Kwan Im Thong Hood Cho Temple",url:"https://en.wikipedia.org/wiki/Kwan_Im_Thong_Hood_Cho_Temple",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:1500,label:"square metres today",grouped:!0,source:{title:"Kwan Im Thong Hood Cho Temple",url:"https://en.wikipedia.org/wiki/Kwan_Im_Thong_Hood_Cho_Temple",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-labyrinth":{title:["Labyrinth,","Singapore food","remembered and remade"],subtitle:"Esplanade · modern Singaporean, one MICHELIN star",lead:"Labyrinth is chef LG Han’s restaurant of “New Singaporean” food. He founded it in 2014 from his roots and memories of growing up in Singapore.",more:["Han was a banker before he turned to cooking. His menu revisits old, often forgotten Singapore recipes with new techniques: chilli crab becomes a cold, sorbet-like dish, and orh luak a small ball topped with caviar.","Labyrinth won a MICHELIN star in 2017 and has kept it. It sits in the Esplanade mall; Esplanade, opened in 2002, is nicknamed “the durian” for its spiky shells."],lookFor:["More than 7,000 sunshades on Esplanade’s shells","Why locals call the building “the durian”"],sources:[{title:"Our Restaurant",url:"https://www.restaurantlabyrinth.com/our-restaurant",publisher:"Labyrinth",checkedAt:"2026-10-31"},{title:"Awards",url:"https://www.restaurantlabyrinth.com/awards",publisher:"Labyrinth",checkedAt:"2026-10-31"},{title:"Restaurant Labyrinth",url:"https://www.esplanade.com/visit/shop-and-dine/directory/restaurant-labyrinth",publisher:"Esplanade",checkedAt:"2026-10-31"},{title:"Robb Report Singapore Thought Leader: LG Han",url:"https://robbreport.com.sg/robb-report-singapore-thought-leader-lg-han/",publisher:"Robb Report Singapore",checkedAt:"2026-10-31"},{title:"Esplanade – Theatres on the Bay",url:"https://en.wikipedia.org/wiki/Esplanade_–_Theatres_on_the_Bay",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"From banker to chef",seconds:90,captions:["Chef LG Han was a banker before he became a chef.","He opened Labyrinth in 2014, from memories of growing up here.","His chilli crab comes cold, like a sorbet.","It has held a MICHELIN star since 2017."],poster:{src:"nearby/cards/labyrinth.webp",alt:"One of Esplanade’s spiky “durian” shells, the building where Labyrinth is (not the restaurant itself)",credit:"CEphoto, Uwe Aranas 2015 · CC BY-SA 3.0",url:"https://commons.wikimedia.org/wiki/File:Singapore_Esplanade-Theatres-on-the-Bay-01.jpg"}},tiles:[{value:2014,label:"Labyrinth opens",source:{title:"Our Restaurant",url:"https://www.restaurantlabyrinth.com/our-restaurant",publisher:"Labyrinth",checkedAt:"2026-10-31"}},{value:2017,label:"MICHELIN star",source:{title:"Our Restaurant",url:"https://www.restaurantlabyrinth.com/our-restaurant",publisher:"Labyrinth",checkedAt:"2026-10-31"}},{value:11,label:"rank, Asia’s 50 Best 2023",source:{title:"Awards",url:"https://www.restaurantlabyrinth.com/awards",publisher:"Labyrinth",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-lasalle-college-of-the-arts":{title:["LASALLE,","an arts college","on McNally Street"],subtitle:"McNally Street · arts college",lead:"LASALLE College of the Arts was founded in 1984 by Brother Joseph McNally, a De La Salle teacher who had lived in Singapore since 1946. It is now part of the University of the Arts Singapore.",more:["McNally paid for much of the college himself. The first class of 27 students studied painting, ceramics, sculpture and music. The college moved to its city campus at 1 McNally Street in 2007.","The campus has 1,500 square metres of gallery space for contemporary art and a workshop for building full-size stage sets."],lookFor:["Contemporary art in the campus galleries"],sources:[{title:"LASALLE College of the Arts",url:"https://en.wikipedia.org/wiki/LASALLE_College_of_the_Arts",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"A brother’s art school",seconds:85,captions:["LASALLE is an arts college with eight schools.","Brother Joseph McNally founded it in 1984.","Its first students, 27 of them, studied painting and music.","It moved to this campus at 1 McNally Street in 2007."],poster:{src:"nearby/cards/lasalle-college-of-the-arts.webp",alt:"The dark grey LASALLE campus buildings beside a road, with palm trees in front",credit:"LN9267 2024 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Lasalle_College_Of_The_Arts_01-12-2024.jpg"}},tiles:[{value:1984,label:"college founded",source:{title:"LASALLE College of the Arts",url:"https://en.wikipedia.org/wiki/LASALLE_College_of_the_Arts",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:27,label:"students in the first class",grouped:!0,source:{title:"LASALLE College of the Arts",url:"https://en.wikipedia.org/wiki/LASALLE_College_of_the_Arts",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:2007,label:"McNally Street campus",source:{title:"LASALLE College of the Arts",url:"https://en.wikipedia.org/wiki/LASALLE_College_of_the_Arts",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-lau-pa-sat":{title:["Lau Pa Sat,","the old market","of cast iron"],subtitle:"Raffles Quay · historic market, now a food centre",lead:"Lau Pa Sat, the Former Telok Ayer Market, is the only one left of the five markets that once served Singapore's town. Municipal Engineer James MacRitchie designed this hall, finished in 1894.",more:["MacRitchie kept the eight-sided shape of George Coleman's earlier market. The cast-iron parts were made by Walter MacFarlane & Company in Glasgow, Scotland. Eight passageways lead to eight large entrances, which let air flow through.","It became a hawker centre in 1972. In the mid-1980s it was taken apart piece by piece so MRT lines could be built underneath, then put back together. It was renamed Lau Pa Sat in 1989."],lookFor:["The clock tower on top of the central lantern","Cast-iron columns with lacy fretwork","The bell-striker figure, added in 1991"],order:"kopi",sources:[{title:"Former Telok Ayer Market (now known as Lau Pa Sat)",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/former-telok-ayer-market-now-known-as-lau-pa-sat",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"},{title:"Lau Pa Sat",url:"https://en.wikipedia.org/wiki/Lau_Pa_Sat",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"The old market",seconds:95,captions:["Lau Pa Sat means 'old market' in Hokkien.","This eight-sided cast-iron hall was finished in 1894.","Its iron parts were made in Glasgow and shipped here.","Since 1972 it has been a food centre for the city."]},tiles:[{value:1894,label:"market hall completed",source:{title:"Former Telok Ayer Market (now known as Lau Pa Sat)",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/former-telok-ayer-market-now-known-as-lau-pa-sat",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:1972,label:"becomes a hawker centre",source:{title:"Former Telok Ayer Market (now known as Lau Pa Sat)",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/former-telok-ayer-market-now-known-as-lau-pa-sat",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:1973,label:"national monument",source:{title:"Lau Pa Sat",url:"https://en.wikipedia.org/wiki/Lau_Pa_Sat",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-lei-garden":{title:["Lei Garden,","Cantonese cooking","inside CHIJMES"],subtitle:"CHIJMES · Cantonese restaurant",lead:"Lei Garden is a Cantonese restaurant group started in 1973 by Chan Shu Kit, with its first restaurant in Sham Shui Po, Hong Kong. Its Singapore restaurant is at #01-24 CHIJMES on Victoria Street.",more:["Chan was an engineer who had never cooked before. Today the group runs 17 restaurants in Hong Kong, mainland China and Singapore, with a central kitchen at Tai Po in Hong Kong.","Its signature dishes include rice with deep-fried rice in lobster soup, crispy roasted pork and barbecued honey pork. The group asks guests to order some dishes in advance."],lookFor:["Rice in lobster soup on the menu","The CHIJMES chapel next to the restaurant"],sources:[{title:"About Lei Garden",url:"https://leigarden.hk/about-lei-garden/",publisher:"Lei Garden Restaurant Group",checkedAt:"2026-10-31"},{title:"About the Group Founder",url:"https://leigarden.hk/about-the-ceo/",publisher:"Lei Garden Restaurant Group",checkedAt:"2026-10-31"},{title:"Branches (Singapore): Chijmes",url:"https://leigarden.hk/location/chijmes/",publisher:"Lei Garden Restaurant Group",checkedAt:"2026-10-31"},{title:"Signature Dishes",url:"https://leigarden.hk/signature-dishes/",publisher:"Lei Garden Restaurant Group",checkedAt:"2026-10-31"},{title:"CHIJMES",url:"https://www.nlb.gov.sg/main/article-detail?cmsuuid=a1145bd1-7c99-4dce-ba0b-2626122ebdbd",publisher:"National Library Board (Singapore Infopedia)",checkedAt:"2026-10-31"}],clip:{title:"From Hong Kong, 1973",seconds:90,captions:["Lei Garden began in Hong Kong in 1973.","Its founder, Chan Shu Kit, was an engineer, not a cook.","The group now runs 17 restaurants.","In Singapore it is at CHIJMES, a former convent."],poster:{src:"nearby/cards/sg-lei-garden.webp",alt:"The white Gothic chapel of CHIJMES and its gate on Victoria Street, the former convent where Lei Garden is",credit:"Mike Peel 2023 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:At_Singapore_2023_059.jpg"}},tiles:[{value:1973,label:"first Lei Garden opens",source:{title:"About Lei Garden",url:"https://leigarden.hk/about-lei-garden/",publisher:"Lei Garden Restaurant Group",checkedAt:"2026-10-31"}},{value:17,label:"restaurants in the group",source:{title:"About Lei Garden",url:"https://leigarden.hk/about-lei-garden/",publisher:"Lei Garden Restaurant Group",checkedAt:"2026-10-31"}},{value:1904,label:"CHIJMES chapel consecrated",source:{title:"CHIJMES",url:"https://www.nlb.gov.sg/main/article-detail?cmsuuid=a1145bd1-7c99-4dce-ba0b-2626122ebdbd",publisher:"National Library Board (Singapore Infopedia)",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-lim-chee-guan-new-bridge-road":{title:["Lim Chee Guan,","bak kwa since 1938"],subtitle:"New Bridge Road · bak kwa shop",lead:"Lim Chee Guan is a family bak kwa (barbecued meat) business. Lim Kay Eng, who came from Xiamen in the 1920s, started it in 1938 as a pushcart stall at the foot of a staircase on Chin Chiew Street.",more:["In 1956 he moved to a shophouse on New Bridge Road to get away from gang clashes nearby. His son Rod Lim took over in 1988, and his grandsons Jerre and Benny Lim later joined.","Its bak kwa is cooked as it is sold, so it is fresh. Before Lunar New Year the wait can be six to eight hours, with queues 300 to 500 metres long."],lookFor:["The red shop sign with its Chinese name 林志源","Bak kwa cooked as it is sold","Long queues in the weeks before Lunar New Year"],sources:[{title:"Lim Chee Guan 林志源 (New Bridge Road)",url:"https://chinatown.sg/shop/lim-chee-guan-newbridge/",publisher:"Chinatown Singapore (Chinatown Business Association)",checkedAt:"2026-10-29"},{title:"Lim Chee Guan bak kwa",url:"https://vulcanpost.com/730566/lim-chee-guan-bak-kwa-singapore",publisher:"Vulcan Post",checkedAt:"2026-10-29"}],clip:{title:"From pushcart to shophouse",seconds:90,captions:["Bak kwa is barbecued meat, a Lunar New Year favourite.","Lim Kay Eng started a pushcart on Chin Chiew Street in 1938.","In 1956 he moved to a shophouse here on New Bridge Road.","Before Lunar New Year, queues can stretch 300 to 500 metres."],poster:{src:"nearby/cards/sg-lim-chee-guan-new-bridge-road.webp",alt:"Lim Chee Guan’s shop sign in Chinatown with a festive paper decoration (the file does not name the branch)",credit:"Ypsilon from Finland 2013 · CC0",url:"https://commons.wikimedia.org/wiki/File:Lim_Chee_Guan_sign.jpg"}},tiles:[{value:1938,label:"pushcart on Chin Chiew St",source:{title:"Lim Chee Guan 林志源 (New Bridge Road)",url:"https://chinatown.sg/shop/lim-chee-guan-newbridge/",publisher:"Chinatown Singapore (Chinatown Business Association)",checkedAt:"2026-10-29"}},{value:1956,label:"moves to New Bridge Road",source:{title:"Lim Chee Guan bak kwa",url:"https://vulcanpost.com/730566/lim-chee-guan-bak-kwa-singapore",publisher:"Vulcan Post",checkedAt:"2026-10-29"}},{value:500,label:"queues before CNY (up to)",source:{title:"Lim Chee Guan bak kwa",url:"https://vulcanpost.com/730566/lim-chee-guan-bak-kwa-singapore",publisher:"Vulcan Post",checkedAt:"2026-10-29"},suffix:" m"}],reviewedAt:"2026-10-29"},"curated:sg-little-india":{title:["Little India,","temples, shophouses","and Serangoon Road"],subtitle:"Serangoon Road · historic district",lead:"Little India grew up around Serangoon Road, where Europeans once traded cattle and Indian migrants worked looking after them. Many Indian Singaporeans also call the area Tekka.",more:["When the swamps were drained, the European traders left, but many workers stayed. In 1909 the town decided to rebuild the area under the Kampong Kapor Improvement Scheme; the Little India Arcade shophouses were finished in 1913.","Temples, mosques and churches stand close together here. In the 1980s the tourism board led the change of name from Serangoon to Little India, and the area became a conservation area on 7 July 1989."],lookFor:["Little India Arcade’s shophouses","Sri Veeramakaliamman Temple on Serangoon Road","The Kerbau Road arts belt"],sources:[{title:"Little India, Singapore",url:"https://en.wikipedia.org/wiki/Little_India,_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"},{title:"Tekka Market",url:"https://www.roots.gov.sg/stories-landing/stories/Hawker-Centres/Tekka-Market",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"},{title:"Sri Veeramakaliamman Temple",url:"https://www.roots.gov.sg/places/places-landing/Places/landmarks/little-india-heritage-trail-walk-of-faiths/sri-veeramakaliamman-temple",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}],clip:{title:"From cattle pens to Tekka",seconds:95,captions:["Little India began as an area for cattle trading.","Indian workers who tended the cattle stayed on.","A shrine to the goddess Kali stood here by 1855.","It became a conservation area on 7 July 1989."],poster:{src:"nearby/cards/little-india.webp",alt:"Serangoon Road lined with low shophouses, with festive decorations hung over the street",credit:"KimonBerlin 2009 · CC BY-SA 2.0",url:"https://commons.wikimedia.org/wiki/File:Little_India_(4048444495).jpg"}},tiles:[{value:1855,label:"Kali shrine (as early as)",source:{title:"Sri Veeramakaliamman Temple",url:"https://www.roots.gov.sg/places/places-landing/Places/landmarks/little-india-heritage-trail-walk-of-faiths/sri-veeramakaliamman-temple",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:1913,label:"Little India Arcade built",source:{title:"Tekka Market",url:"https://www.roots.gov.sg/stories-landing/stories/Hawker-Centres/Tekka-Market",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:1989,label:"conservation area",source:{title:"Little India, Singapore",url:"https://en.wikipedia.org/wiki/Little_India,_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-macdonald-house":{title:["MacDonald House,","red brick and","the first cool office"],subtitle:"Orchard Road · former bank office building",lead:"MacDonald House was built in 1948–1949 for the Hong Kong and Shanghai Banking Corporation. It was the first office building in Southeast Asia to be fully air-conditioned, with a separate control in every room.",more:["The ten-storey block was named after Malcolm MacDonald, Commissioner-General for Southeast Asia, and was one of the tallest buildings in Singapore. Its red sand-faced bricks came from the local Alexandra Brickworks.","On 10 March 1965, during Indonesia’s Konfrontasi, a bomb exploded near a lift on the mezzanine floor, killing three people. Two Indonesian soldiers were later convicted of murder."],lookFor:["Red brick with white window frames","The bank’s crest with two Chinese junks","The old night safe beside the entrance"],sources:[{title:"MacDonald House",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/macdonald-house",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}],clip:{title:"Cool air, then a bomb",seconds:90,captions:["This red-brick block opened in 1949 as a bank office.","It was the first fully air-conditioned office in Southeast Asia.","On 10 March 1965, a bomb here killed three people.","Look for the old bank crest and night safe at the door."],poster:{src:"nearby/cards/macdonald-house.webp",alt:"The red-brick MacDonald House with rows of white-framed windows",credit:"ProjectManhattan 2013 · CC0",url:"https://commons.wikimedia.org/wiki/File:MacDonald_House,_Singapore_-_20131120.jpg"}},tiles:[{value:1949,label:"building completed",source:{title:"MacDonald House",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/macdonald-house",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:10,label:"storeys",grouped:!0,source:{title:"MacDonald House",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/macdonald-house",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:1965,label:"Konfrontasi bombing",source:{title:"MacDonald House",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/macdonald-house",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-maghain-aboth":{title:["Maghain Aboth,","'Shield of Our Fathers'"],subtitle:"Waterloo Street · synagogue and Jews of Singapore Museum",lead:"Maghain Aboth means 'Shield of Our Fathers' in Hebrew. The synagogue on Waterloo Street was consecrated on 4 April 1878 and is the oldest surviving synagogue in Southeast Asia.",more:["Singapore's small Jewish community, many of them merchants, first prayed in a shophouse on Synagogue Street. In 1873 Manasseh Meyer asked to sell it and buy land for a new synagogue. Building took about five years. A simple wooden gallery for women came first; a solid one was built in 1925.","The front has Roman columns, arches and three Stars of David. Inside, the ark that holds the Torah scrolls faces west towards Jerusalem. The Jews of Singapore Museum opened next door in the Jacob Ballas Centre in December 2021. Visits must be booked at least three days ahead."],lookFor:["Three Stars of David on the front","Roman columns, arches and a dentilled cornice","The Jacob Ballas Centre next door, home of the museum"],sources:[{title:"Maghain Aboth Synagogue",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/maghain-aboth-synagogue",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"},{title:"Maghain Aboth Synagogue",url:"https://en.wikipedia.org/wiki/Maghain_Aboth_Synagogue",publisher:"Wikipedia",checkedAt:"2026-10-31"},{title:"Visit Us",url:"https://museum.singaporejews.com/visit-us/",publisher:"Jews of Singapore Museum",checkedAt:"2026-10-31"}],clip:{title:"Shield of Our Fathers",seconds:95,captions:["Jews first prayed in a shophouse on Synagogue Street.","This synagogue was consecrated on 4 April 1878.","It is the oldest surviving synagogue in Southeast Asia.","Next door, a museum tells the community's story."],poster:{src:"nearby/cards/sg-maghain-aboth.webp",alt:"The cream-coloured synagogue with Stars of David, arched porch and white shutters, seen from its garden",credit:"Chainwit. 2023 · CC BY 4.0",url:"https://commons.wikimedia.org/wiki/File:Maghain_Aboth_Synagogue_-_Singapore_(2023)_img_01.jpg"}},tiles:[{value:1878,label:"synagogue consecrated",source:{title:"Maghain Aboth Synagogue",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/maghain-aboth-synagogue",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:1925,label:"solid women's gallery",source:{title:"Maghain Aboth Synagogue",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/maghain-aboth-synagogue",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:2021,label:"museum opens next door",source:{title:"Maghain Aboth Synagogue",url:"https://en.wikipedia.org/wiki/Maghain_Aboth_Synagogue",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-malabar-mosque":{title:["Malabar Mosque,","blue tiles","at Kampong Gelam"],subtitle:"Victoria Street · mosque of the Malabar Muslim community",lead:"This is the only mosque in Singapore built and run by the Malabar Muslim community, who came from Kerala in India. Yusof Ishak, then head of state, opened it in 1963.",more:["In the 1950s the community needed a large place for prayer and gatherings, and raised money to build one. Many donors from outside the Malabar community helped. The architect, A. H. Siddique, was known for designing religious buildings of any faith for free.","The building stands diagonally at the corner of Victoria Street and Jalan Sultan, so that the prayer hall faces Mecca. The blue tiles on the outside were put up in 1995. After a three-year renovation, the mosque reopened in July 2023."],lookFor:["Blue tiles and golden onion domes","Small domed pavilions (chatris) on the roofline","'Interlocking coin' lattice on the windows"],sources:[{title:"Malabar Muslim Jama-Ath Mosque",url:"https://www.ura.gov.sg/conservation/find-a-building/conservation-portal/kpgl-00665/",publisher:"Urban Redevelopment Authority",checkedAt:"2026-10-31"},{title:"Malabar Mosque",url:"https://en.wikipedia.org/wiki/Malabar_Mosque",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"The blue mosque",seconds:90,captions:["The only mosque built by Malabar Muslims from Kerala.","The community raised funds for it in the 1950s.","Yusof Ishak opened it in 1963.","Its blue tiles and golden domes face the street corner."]},tiles:[{value:1927,label:"Malabar Jama'at founded",source:{title:"Malabar Mosque",url:"https://en.wikipedia.org/wiki/Malabar_Mosque",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:1963,label:"officially opened",source:{title:"Malabar Muslim Jama-Ath Mosque",url:"https://www.ura.gov.sg/conservation/find-a-building/conservation-portal/kpgl-00665/",publisher:"Urban Redevelopment Authority",checkedAt:"2026-10-31"}},{value:1995,label:"blue tiles put up",source:{title:"Malabar Mosque",url:"https://en.wikipedia.org/wiki/Malabar_Mosque",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-malay-heritage-centre-istana-kampong-gelam":{title:["Istana Kampong Gelam,","a sultan’s palace","now a museum"],subtitle:"Sultan Gate · Malay heritage museum in a former palace",lead:"The Malay Heritage Centre is inside Istana Kampong Gelam, the former palace of the Sultan of Johor’s family. It shows the heritage and history of Malay Singaporeans.",more:["Sultan Hussein Shah built the first, wooden istana here in 1819. The two-storey palace you see was later built for his son, Sultan Ali. Its design mixes the Palladian style with Malay motifs.","Prime Minister Lee Hsien Loong opened the Malay Heritage Centre in June 2005. The palace became a national monument on 6 August 2015. The centre closed in October 2022 for a revamp and reopened in 2026."],lookFor:["The yellow two-storey palace in its walled compound","Palladian columns mixed with Malay details","Sultan Mosque’s golden dome nearby"],sources:[{title:"Malay Heritage Centre",url:"https://en.wikipedia.org/wiki/Malay_Heritage_Centre",publisher:"Wikipedia",checkedAt:"2026-10-31"},{title:"Istana Kampong Glam",url:"https://en.wikipedia.org/wiki/Istana_Kampong_Glam",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"The palace of Kampong Gelam",seconds:90,captions:["This yellow palace was the home of Sultan Hussein’s family.","The first istana here was built of wood in 1819.","Since 2005 it has been the Malay Heritage Centre.","After a long revamp, the galleries opened again in 2026."]},tiles:[{value:1819,label:"first istana built",source:{title:"Istana Kampong Glam",url:"https://en.wikipedia.org/wiki/Istana_Kampong_Glam",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:2005,label:"heritage centre opens",source:{title:"Malay Heritage Centre",url:"https://en.wikipedia.org/wiki/Malay_Heritage_Centre",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:2015,label:"national monument",source:{title:"Istana Kampong Glam",url:"https://en.wikipedia.org/wiki/Istana_Kampong_Glam",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-marina-bay-financial-centre":{title:["Marina Bay Financial Centre,","towers by the bay"],subtitle:"Marina Boulevard · offices, homes and a mall",lead:"Marina Bay Financial Centre has three office towers, two residential towers and the Marina Bay Link Mall, on a 3.55-hectare site. It was built in two phases, finished in 2010 and 2012.",more:["Tower 1 has 33 storeys, Tower 2 has 50 and Tower 3 has 46. Banks such as Standard Chartered and DBS are the main tenants. Prime Minister Lee Hsien Loong officiated its grand opening on 15 May 2013.","Marina Bay Link Mall is mostly underground, with shops in the basement and at ground level, and outdoor dining at the Ground Plaza."],lookFor:["Marina Bay Link Mall, mostly underground","Outdoor dining at the Ground Plaza"],sources:[{title:"Marina Bay Financial Centre",url:"https://en.wikipedia.org/wiki/Marina_Bay_Financial_Centre",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"Offices, homes and a mall",seconds:90,captions:["MBFC has three office towers and two homes towers.","The first phase was done in 2010, the whole site in 2012.","Its tallest office tower, Tower 2, has 50 storeys.","Shops and food are below ground in Marina Bay Link Mall."],poster:{src:"nearby/cards/marina-bay-financial-centre.webp",alt:"The glass towers of Marina Bay Financial Centre seen across the bay",credit:"Diego Delso 2023 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Skyline,_Marina_Bay_Financial_Centre,_Singapore,_2023-08-17,_DD_28.jpg"}},tiles:[{value:2010,label:"first phase done",source:{title:"Marina Bay Financial Centre",url:"https://en.wikipedia.org/wiki/Marina_Bay_Financial_Centre",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:2012,label:"whole centre done",source:{title:"Marina Bay Financial Centre",url:"https://en.wikipedia.org/wiki/Marina_Bay_Financial_Centre",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:50,label:"storeys in Tower 2",source:{title:"Marina Bay Financial Centre",url:"https://en.wikipedia.org/wiki/Marina_Bay_Financial_Centre",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-marina-bay-sands":{title:["Marina Bay Sands,","a park on","three towers"],subtitle:"Bayfront Avenue · hotel, casino and convention resort",lead:"Marina Bay Sands is an integrated resort on Marina Bay with a 1,850-room hotel, a casino, a convention centre, a mall, a theatre and the ArtScience Museum. It officially opened on 23 June 2010.",more:["Moshe Safdie designed it. Its three 55-storey hotel towers are joined at the top by the Sands SkyPark, a 1.2-hectare rooftop that hangs out past the north tower.","The SkyPark has a pool with a 146-metre infinity edge, 191 metres above the ground. A canal runs through The Shoppes mall below, and each evening a light and water show, Spectra, plays by the bay."],lookFor:["The SkyPark across the tops of the three towers","The canal running through The Shoppes","Spectra, the evening light and water show"],sources:[{title:"Marina Bay Sands",url:"https://en.wikipedia.org/wiki/Marina_Bay_Sands",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"A park in the sky",seconds:90,captions:["Moshe Safdie designed this resort; card decks inspired him.","It officially opened on 23 June 2010.","The SkyPark joins its three 55-storey towers at the top.","The rooftop pool has a 146-metre infinity edge."],poster:{src:"nearby/cards/marina-bay-sands.webp",alt:"Marina Bay Sands' three hotel towers joined by the SkyPark, seen across the bay",credit:"Supanut Arunoprayote 2020 · CC BY 4.0",url:"https://commons.wikimedia.org/wiki/File:Marina_Bay_Sands_(I).jpg"}},tiles:[{value:2010,label:"official opening",source:{title:"Marina Bay Sands",url:"https://en.wikipedia.org/wiki/Marina_Bay_Sands",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:55,label:"storeys in each tower",source:{title:"Marina Bay Sands",url:"https://en.wikipedia.org/wiki/Marina_Bay_Sands",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:1850,label:"hotel rooms and suites",grouped:!0,source:{title:"Marina Bay Sands",url:"https://en.wikipedia.org/wiki/Marina_Bay_Sands",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-marina-one":{title:["Marina One,","a green heart","in the city"],subtitle:"Marina Way · offices and homes around a garden",lead:"Marina One is a mix of offices, homes and shops in Marina South. Building began on 11 July 2012, and it was opened on 15 January 2018.",more:["Christoph Ingenhoven designed it: two 34-storey residential towers with 1,042 apartments and two 30-storey office towers. They wrap around 'The Heart', a green space with shops and lush planting.","The landscape architects Gustafson Porter and ICN Design, who also worked on Gardens by the Bay, planned its greenery."],lookFor:["The garden of 'The Heart' between the towers","Shops and food in the podium at its centre"],sources:[{title:"Marina One",url:"https://en.wikipedia.org/wiki/Marina_One",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"A garden inside the block",seconds:90,captions:["Marina One has two office towers and two homes towers.","Christoph Ingenhoven designed it; it opened in January 2018.","At its centre is 'The Heart', a garden full of plants.","The garden team also worked on Gardens by the Bay."]},tiles:[{value:2012,label:"ground broken",source:{title:"Marina One",url:"https://en.wikipedia.org/wiki/Marina_One",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:2018,label:"opened",source:{title:"Marina One",url:"https://en.wikipedia.org/wiki/Marina_One",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:1042,label:"apartments",grouped:!0,source:{title:"Marina One",url:"https://en.wikipedia.org/wiki/Marina_One",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-masjid-abdul-gafoor":{title:["Abdul Gafoor Mosque,","a sunburst","over Dunlop Street"],subtitle:"Dunlop Street · mosque",lead:"Abdul Gafoor Mosque grew from an older mosque on Dunlop Street that served Tamil Muslim traders and Baweanese horse grooms from the nearby race course.",more:["Shaik Abdul Gafoor, a law clerk, became a trustee in 1881. He built shophouses round the old mosque and used the rents to pay for a new one. Work began in 1907, and the mosque was later named after him.","Above the main door is a sunburst with the names of 25 prophets, from Adam to Muhammad, in Arabic. In 1998 a long-forgotten basement was found from the old plans; with it, the prayer hall holds 1,200 people."],lookFor:["The sunburst with 25 prophets’ names","Small onion domes along the roof","Cinquefoil arches round the verandahs"],sources:[{title:"Abdul Gafoor Mosque",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/abdul-gafoor-mosque",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"},{title:"Masjid Abdul Gaffoor",url:"https://en.wikipedia.org/wiki/Masjid_Abdul_Gaffoor",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"Twenty-five prophets",seconds:90,captions:["This mosque first served Tamil Muslims and Baweanese grooms.","Building began in 1907, paid for by shophouse rents.","Over the door, a sunburst names 25 prophets in Arabic.","A forgotten basement was found again in 1998."]},tiles:[{value:1907,label:"building begins",source:{title:"Abdul Gafoor Mosque",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/abdul-gafoor-mosque",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:25,label:"prophets named over the door",grouped:!0,source:{title:"Abdul Gafoor Mosque",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/abdul-gafoor-mosque",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:1200,label:"people in the prayer hall",grouped:!0,source:{title:"Abdul Gafoor Mosque",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/abdul-gafoor-mosque",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-masjid-al-burhani":{title:["Masjid Al-Burhani,","home of the","Dawoodi Bohras"],subtitle:"Hill Street · Dawoodi Bohra mosque",lead:"Masjid Al-Burhani is the spiritual home of Singapore’s Dawoodi Bohra community. Bohra Muslims came here from Gujarat, India, from the late 19th century, mostly as merchants.",more:["The first mosque building on the site was paid for by the merchant A.M. Essbhoy. It was rebuilt as a four-storey mosque, declared open in 1959. As the community grew, the site was redeveloped in the 1990s.","The present complex was opened in 2000 by Syedna Mohammed Burhanuddin, the 52nd head of the worldwide Dawoodi Bohra community. The mosque can hold up to 150 people, and office workers from Hill Street and High Street often come here."],lookFor:["The mosque’s single dome and single minaret","Its place between high-rise blocks on Hill Street"],sources:[{title:"Masjid Al-Burhani",url:"https://www.roots.gov.sg/places/places-landing/Places/landmarks/Civic-District-Heritage-Trail/Masjid-Al-Burhani",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"},{title:"Burhani",url:"https://muis.gov.sg/Mosque/Our-Mosques/Mosque-Directory/Burhani",publisher:"Majlis Ugama Islam Singapura (MUIS)",checkedAt:"2026-10-31"},{title:"Burhani Mosque",url:"https://en.wikipedia.org/wiki/Burhani_Mosque",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"From Gujarat to Hill Street",seconds:90,captions:["This mosque is the spiritual home of Singapore’s Dawoodi Bohras.","Bohra Muslims came from Gujarat, India, from the late 1800s.","Many were traders in timber, tin, rubber, scrap and spices.","Today’s mosque complex opened in 2000, among tall buildings."],poster:{src:"nearby/cards/masjid-al-burhani.webp",alt:"The white mosque with its dome and arches beside tall buildings on Hill Street",credit:"M. Adrian Jurhami 2025 · CC BY 4.0",url:"https://commons.wikimedia.org/wiki/File:Al-Burhani_Mosque,_along_Hill_Street.jpg"}},tiles:[{value:1959,label:"four-storey mosque opens",source:{title:"Masjid Al-Burhani",url:"https://www.roots.gov.sg/places/places-landing/Places/landmarks/Civic-District-Heritage-Trail/Masjid-Al-Burhani",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:2e3,label:"today’s complex opens",source:{title:"Masjid Al-Burhani",url:"https://www.roots.gov.sg/places/places-landing/Places/landmarks/Civic-District-Heritage-Trail/Masjid-Al-Burhani",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:150,label:"people it can hold",source:{title:"Burhani",url:"https://muis.gov.sg/Mosque/Our-Mosques/Mosque-Directory/Burhani",publisher:"Majlis Ugama Islam Singapura (MUIS)",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-masjid-bencoolen":{title:["Masjid Bencoolen,","an old mosque","in a new tower"],subtitle:"Bencoolen Street · mosque",lead:"Masjid Bencoolen was first built in the 1820s by Indian Muslim workers from Bengkulu in Sumatra. MUIS dates the original masjid building to 1845.",more:["The first mosque, in attap, went up between 1825 and 1828. In 1845 Syed Omar Aljunied rebuilt it in brick. From 1906 it was known as the Hanafi Mosque, after the Hanafi school of Sunni Islam.","From 2001 the site was redeveloped with a commercial block and a 12-storey residential tower, and the new mosque opened in May 2004. It was rebuilt again from 2020 and fully reopened in March 2023."],lookFor:["The mosque's dome on Bencoolen Street","The Somerset Bencoolen complex around it"],sources:[{title:"Masjid Bencoolen",url:"https://www.muis.gov.sg/community/mosque/mosque-directory/bencoolen/",publisher:"MUIS",checkedAt:"2026-10-31"},{title:"Masjid Bencoolen",url:"https://en.wikipedia.org/wiki/Masjid_Bencoolen",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"A mosque under a tower",seconds:85,captions:["Workers from Bengkulu built an attap mosque here in the 1820s.","It was rebuilt in brick in 1845.","From 1906 it was known as the Hanafi Mosque.","Since 2004 it has been part of a block with a tower of flats."],poster:{src:"nearby/cards/sg-masjid-bencoolen.webp",alt:"The mint-green front of Masjid Bencoolen with its minaret and patterned windows",credit:"M. Adrian Jurhami 2026 · CC BY 4.0",url:"https://commons.wikimedia.org/wiki/File:Bencoolen_Mosque.jpg"}},tiles:[{value:1845,label:"brick mosque built",source:{title:"Masjid Bencoolen",url:"https://www.muis.gov.sg/community/mosque/mosque-directory/bencoolen/",publisher:"MUIS",checkedAt:"2026-10-31"}},{value:2004,label:"new mosque opens",source:{title:"Masjid Bencoolen",url:"https://www.muis.gov.sg/community/mosque/mosque-directory/bencoolen/",publisher:"MUIS",checkedAt:"2026-10-31"}},{value:12,label:"storey residential block",source:{title:"Masjid Bencoolen",url:"https://www.muis.gov.sg/community/mosque/mosque-directory/bencoolen/",publisher:"MUIS",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-masjid-mujahidin":{title:["Masjid Mujahidin,","a round prayer hall","in Queenstown"],subtitle:"Stirling Road · mosque on the Queenstown heritage trail",lead:"Masjid Mujahidin is a mosque on Stirling Road in Queenstown. It was the second mosque designed by HDB under the Mosque Building Fund, and it opened on 9 October 1977.",more:["Before it was built, religious classes were held at a nearby police unit because the estate’s prayer rooms were too small. A building committee formed in 1967 and raised money by selling calendars across the island and running food bazaars.","Its prayer hall is round, with glass panels all around. Verses of the Throne Verse (Ayat al-Kursi) are written high on the front wall of the hall. A classroom wing was finished in 1994, and an upgrade with barrier-free facilities opened in 2014."],lookFor:["The box-shaped top with semi-oval openings","The round, glass-panelled prayer hall","Ayat al-Kursi verses high on the prayer hall wall"],sources:[{title:"Mujahidin Mosque – My Queenstown Heritage Trail",url:"https://www.roots.gov.sg/places/places-landing/places/landmarks/my-queenstown-heritage-trail/mujahidin-mosque",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"},{title:"Mujahidin",url:"https://www.muis.gov.sg/community/mosque/mosque-directory/mujahidin",publisher:"Majlis Ugama Islam Singapura (MUIS)",checkedAt:"2026-10-31"},{title:"Mujahidin Mosque",url:"https://en.wikipedia.org/wiki/Mujahidin_Mosque",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"Eleven years of fundraising",seconds:90,captions:["Queenstown’s Muslims planned and raised funds for 11 years.","They sold calendars and ran food bazaars to pay for it.","Its box-shaped top has semi-oval openings on all four sides.","It opened in 1977 and can hold up to 3,500 people."],poster:{src:"nearby/cards/masjid-mujahidin.webp",alt:"Masjid Mujahidin on Stirling Road: a round white prayer hall with its name on the front",credit:"GoAheadFan95 2026 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Masjid_Mujahidin,_March_2026.jpg"}},tiles:[{value:1967,label:"building committee set up",source:{title:"Mujahidin Mosque – My Queenstown Heritage Trail",url:"https://www.roots.gov.sg/places/places-landing/places/landmarks/my-queenstown-heritage-trail/mujahidin-mosque",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:1977,label:"mosque opens",source:{title:"Mujahidin Mosque – My Queenstown Heritage Trail",url:"https://www.roots.gov.sg/places/places-landing/places/landmarks/my-queenstown-heritage-trail/mujahidin-mosque",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:3500,label:"people it can hold",grouped:!0,source:{title:"Mujahidin",url:"https://www.muis.gov.sg/community/mosque/mosque-directory/mujahidin",publisher:"Majlis Ugama Islam Singapura (MUIS)",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-masjid-omar-kampong-melaka":{title:["Masjid Omar","Kampong Melaka,","Singapore's oldest mosque"],subtitle:"Keng Cheow Street · mosque",lead:"Masjid Omar Kampong Melaka, in a lane off Havelock Road, is Singapore's oldest mosque. It was founded in 1820, one year after the British set up a trading post here.",more:["Its founder, the Arab merchant Syed Omar Aljunied, was welcomed by Raffles himself. He and his family are buried in the mosque grounds. The first mosque was a timber building with an attap roof.","As the congregation grew, his son paid for a larger brick mosque in 1855. Later rebuilding added a minaret, and a 2009 renovation replaced the roof. Its main pillars and columns and some chengal wood from 1855 remain."],lookFor:["The Aljunied family graves in the courtyard","The minaret at the entrance","Pillars kept from the 1855 mosque"],sources:[{title:"Masjid Omar Kampong Melaka",url:"https://roots.gov.sg/places/places-landing/Places/surveyed-sites/Masjid-Omar-Kampong-Melaka",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"},{title:"Omar Kampong Melaka – Mosque directory",url:"https://www.muis.gov.sg/community/mosque/mosque-directory/omar-kampong-melaka/",publisher:"Majlis Ugama Islam Singapura (MUIS)",checkedAt:"2026-10-31"},{title:"Masjid Omar Kampong Melaka",url:"https://en.wikipedia.org/wiki/Masjid_Omar_Kampong_Melaka",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"The first mosque",seconds:90,captions:["Founded in 1820, this is Singapore's oldest mosque.","Arab merchant Syed Omar Aljunied set it up.","The first mosque was timber, with an attap roof and no minaret.","Today office workers come here for daily and Friday prayers."],poster:{src:"nearby/cards/sg-masjid-omar-kampong-melaka.webp",alt:"The minaret of Masjid Omar Kampong Melaka among trees and office buildings",credit:"M. Adrian Jurhami 2026 · CC BY 4.0",url:"https://commons.wikimedia.org/wiki/File:General_view,_Masjid_Omar_Kampong_Melaka_01.jpg"}},tiles:[{value:1820,label:"mosque founded",source:{title:"Masjid Omar Kampong Melaka",url:"https://roots.gov.sg/places/places-landing/Places/surveyed-sites/Masjid-Omar-Kampong-Melaka",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:1855,label:"brick mosque built",source:{title:"Masjid Omar Kampong Melaka",url:"https://roots.gov.sg/places/places-landing/Places/surveyed-sites/Masjid-Omar-Kampong-Melaka",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:2001,label:"listed as historic site",source:{title:"Masjid Omar Kampong Melaka",url:"https://roots.gov.sg/places/places-landing/Places/surveyed-sites/Masjid-Omar-Kampong-Melaka",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-maxwell-food-centre":{title:["Maxwell Food Centre,","a 1920s market","turned food centre"],subtitle:"Kadayanallur Street · hawker centre",lead:"Maxwell Food Centre stands on land that was a Chinese burial ground until 1907. A municipal market was built here from 1927, and cooked food stalls with tables were added in 1930.",more:["After the Second World War, a government “Family Restaurant” here sold cheap meals from December 1946. In 1972, 73 produce stalls moved in from Telok Ayer Market, and in 1986 about 70 back-lane hawkers from the China Square area joined them.","In 1987 the market officially became a food centre. It was also known as Kim Hua Market. After an upgrade it reopened as Maxwell Food Centre in 2001, with 103 hawkers."],lookFor:["The heritage signboard telling the centre’s story","Tian Tian, its first stall with a Bib Gourmand","Its old name: it was once Kim Hua Market"],order:"kopi",sources:[{title:"Maxwell Road Food Centre",url:"https://www.roots.gov.sg/en/stories-landing/stories/Hawker-Centres/Maxwell-Road-Food-Centre",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-29"},{title:"Maxwell Food Centre",url:"https://en.wikipedia.org/wiki/Maxwell_Food_Centre",publisher:"Wikipedia",checkedAt:"2026-10-29"},{title:"File:Maxwell Food Centre heritage signboard - 2022-08-13.jpg",url:"https://commons.wikimedia.org/wiki/File:Maxwell_Food_Centre_heritage_signboard_-_2022-08-13.jpg",publisher:"Wikimedia Commons",checkedAt:"2026-10-29"}],clip:{title:"From market to food centre",seconds:95,captions:["This food centre began life as a municipal market.","Its land was a Chinese burial ground, cleared in 1907.","Cooked food stalls and tables were first added in 1930.","In 1987 the market officially became a food centre."],poster:{src:"nearby/cards/sg-maxwell-food-centre.webp",alt:"Maxwell Food Centre at night, seen across the road from South Bridge Road",credit:"Kbseah 2025 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Maxwell_Food_Centre,_external_view.jpg"}},tiles:[{value:1930,label:"cooked food stalls added",source:{title:"Maxwell Road Food Centre",url:"https://www.roots.gov.sg/en/stories-landing/stories/Hawker-Centres/Maxwell-Road-Food-Centre",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-29"}},{value:1987,label:"officially a food centre",source:{title:"Maxwell Road Food Centre",url:"https://www.roots.gov.sg/en/stories-landing/stories/Hawker-Centres/Maxwell-Road-Food-Centre",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-29"}},{value:103,label:"hawkers after 2001 upgrade",source:{title:"Maxwell Food Centre",url:"https://en.wikipedia.org/wiki/Maxwell_Food_Centre",publisher:"Wikipedia",checkedAt:"2026-10-29"}}],reviewedAt:"2026-10-29"},"curated:sg-mediacorp-campus":{title:["Mediacorp Campus,","a broadcaster","with open doors"],subtitle:"Stars Avenue · broadcast centre by Maki and Associates",lead:"Mediacorp Campus is the home of Singapore’s national broadcaster at Mediapolis, one-north. Prime Minister Lee Hsien Loong opened it on 8 December 2015.",more:["Maki and Associates, working with DP Architects, won the design in an invited international competition in 2011. Three forms hold a theatre, the broadcast centre and the offices. Between them runs a public plaza with a grand stairway of 50 steps, for Singapore’s 50th anniversary.","The old Caldecott site was gated and spread over 12 buildings. Here, 48 departments share one open campus with atriums, green spaces and cafés. About 65 guided tours a month show visitors how the newsroom works."],lookFor:["The grand stairway of 50 steps","The viewing plateau at the top of the stairs","The open-air Town Square used for events"],sources:[{title:"PM Lee Hsien Loong at the opening of Mediacorp's new campus at Mediapolis@one-north",url:"https://pmo.gov.sg/Newsroom/pm-lee-hsien-loong-opening-mediacorps-new-campus-mediapolisone-north-8-december-2015",publisher:"Prime Minister's Office Singapore",checkedAt:"2026-10-31"},{title:"MediaCorp @ Mediapolis",url:"https://www.e-architect.com/singapore/mediacorp-buona-vista",publisher:"e-architect",checkedAt:"2026-10-31"},{title:"Opening up at Mediapolis: Mediacorp's renewed community focus",url:"https://jtc.gov.sg/about-jtc/news-and-stories/feature-stories/opening-up-at-mediapolis-mediacorps-renewed-community-focus",publisher:"JTC Corporation",checkedAt:"2026-10-31"}],clip:{title:"Fifty steps for SG50",seconds:90,captions:["Mediacorp’s new home opened on 8 December 2015.","It replaced Caldecott, its base for almost 80 years.","The public stairway has 50 steps, for Singapore’s 50th year.","Guided tours let visitors watch the newsroom at work."],poster:{src:"nearby/cards/mediacorp-campus.webp",alt:"The curved glass front of Mediacorp Campus seen from the road",credit:"Froming1132 2015 · CC0",url:"https://commons.wikimedia.org/wiki/File:224_Mediacorp_Campus_Building.jpg"}},tiles:[{value:2015,label:"campus opens",source:{title:"PM Lee Hsien Loong at the opening of Mediacorp's new campus at Mediapolis@one-north",url:"https://pmo.gov.sg/Newsroom/pm-lee-hsien-loong-opening-mediacorps-new-campus-mediapolisone-north-8-december-2015",publisher:"Prime Minister's Office Singapore",checkedAt:"2026-10-31"}},{value:50,label:"steps on the grand stairway",source:{title:"MediaCorp @ Mediapolis",url:"https://www.e-architect.com/singapore/mediacorp-buona-vista",publisher:"e-architect",checkedAt:"2026-10-31"}},{value:48,label:"departments under one roof",source:{title:"Opening up at Mediapolis: Mediacorp's renewed community focus",url:"https://jtc.gov.sg/about-jtc/news-and-stories/feature-stories/opening-up-at-mediapolis-mediacorps-renewed-community-focus",publisher:"JTC Corporation",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-merlion-park":{title:["Merlion Park,","a lion's head,","a fish's tail"],subtitle:"One Fullerton · statue and waterfront park",lead:"The Merlion was first created in 1964 as the logo of the Singapore Tourist Promotion Board. The fish body recalls Temasek, the old fishing village, and the lion head the legend of Sang Nila Utama, who named the island Singapura.",more:["Sculptor Lim Nang Seng built the statue from a design by Kwan Sai Kheong, helped by his eight children. Prime Minister Lee Kuan Yew unveiled it at the mouth of the Singapore River on 15 September 1972. It is 8.6 metres tall, and a 2-metre 'Merlion cub' stands with it.","The Esplanade Bridge, built in 1997, blocked the view of it. So in 2002 the 70-tonne statue was lifted over the bridge by cranes and moved by barge to One Fullerton, 120 metres away. In 2009 lightning knocked a piece off its mane."],lookFor:["The 2-metre 'Merlion cub' near the big statue","The viewing deck for photos","The Fullerton Hotel behind the statue"],sources:[{title:"Celebrating 50 Years of the Merlion: Stories Behind the National Icon",url:"https://www.roots.gov.sg/en/stories-landing/stories/celebrating-50-years-of-the-merlion-stories-behind-the-national-icon/story",publisher:"Singapore Tourism Board, on Roots (National Heritage Board)",checkedAt:"2026-10-31"},{title:"Merlion Park",url:"https://en.wikipedia.org/wiki/Merlion_Park",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"Half lion, half fish",seconds:90,captions:["The Merlion has a lion's head and the body of a fish.","It began in 1964 as a logo for the tourist board.","Lim Nang Seng built the statue with help from his 8 children.","In 2002 it moved here, 120 metres from its first home."]},tiles:[{value:1964,label:"Merlion logo created",source:{title:"Celebrating 50 Years of the Merlion: Stories Behind the National Icon",url:"https://www.roots.gov.sg/en/stories-landing/stories/celebrating-50-years-of-the-merlion-stories-behind-the-national-icon/story",publisher:"Singapore Tourism Board, on Roots (National Heritage Board)",checkedAt:"2026-10-31"}},{value:1972,label:"statue unveiled",source:{title:"Celebrating 50 Years of the Merlion: Stories Behind the National Icon",url:"https://www.roots.gov.sg/en/stories-landing/stories/celebrating-50-years-of-the-merlion-stories-behind-the-national-icon/story",publisher:"Singapore Tourism Board, on Roots (National Heritage Board)",checkedAt:"2026-10-31"}},{value:8.6,label:"tall statue",suffix:" m",source:{title:"Celebrating 50 Years of the Merlion: Stories Behind the National Icon",url:"https://www.roots.gov.sg/en/stories-landing/stories/celebrating-50-years-of-the-merlion-stories-behind-the-national-icon/story",publisher:"Singapore Tourism Board, on Roots (National Heritage Board)",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-meta":{title:["Meta,","Korean cooking","that keeps changing"],subtitle:"Mohamed Sultan Road · modern Korean tasting menu",lead:"Meta is chef Sun Kim’s Korean tasting-menu restaurant. Its name is short for metamorphosis, because the restaurant is about change.",more:["Sun Kim was born in Busan and raised in Seoul. He started cooking in his mother’s gamja-tang eatery, moved to Sydney at 26 and trained under Tetsuya Wakuda, then worked at Waku Ghin in Singapore.","He opened Meta on Keong Saik Road in November 2015. It won its first MICHELIN star in 2017 and a second in 2024, after moving to Mohamed Sultan Road in 2023."],lookFor:["The shophouse rows along Mohamed Sultan Road","Thevar, another two-star restaurant, on the same road"],sources:[{title:"About us",url:"https://metarestaurant.sg/about-us/",publisher:"Meta",checkedAt:"2026-10-29"},{title:"List of Michelin-starred restaurants in Singapore",url:"https://en.wikipedia.org/wiki/List_of_Michelin-starred_restaurants_in_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-29"}],clip:{title:"From Busan to two stars",seconds:90,captions:["Meta is short for metamorphosis: a restaurant about change.","Sun Kim, born in Busan, opened it on Keong Saik Road in 2015.","He trained under Tetsuya Wakuda in Sydney and at Waku Ghin.","Since 2023 it has been on Mohamed Sultan Road, with two stars."],poster:{src:"nearby/cards/meta.webp",alt:"An old shophouse front on Mohamed Sultan Road, the street where Meta now is (not the restaurant itself)",credit:"Terence Ong 2007 · CC BY 2.5",url:"https://commons.wikimedia.org/wiki/File:Old_shophouse_at_Mohamed_Sultan_Road.jpg"}},tiles:[{value:2015,label:"opened on Keong Saik Road",source:{title:"About us",url:"https://metarestaurant.sg/about-us/",publisher:"Meta",checkedAt:"2026-10-29"}},{value:2017,label:"first MICHELIN star",source:{title:"About us",url:"https://metarestaurant.sg/about-us/",publisher:"Meta",checkedAt:"2026-10-29"}},{value:2024,label:"second MICHELIN star",source:{title:"About us",url:"https://metarestaurant.sg/about-us/",publisher:"Meta",checkedAt:"2026-10-29"}}],reviewedAt:"2026-10-29"},"curated:sg-muthu-s-curry-little-india":{title:["Muthu's Curry,","fish head curry","since 1969"],subtitle:"Race Course Road · Indian restaurant",lead:"Muthu's Curry began in 1969, when its founder Ayyakkannu sold his fish head curry from a stall in a Klang Road coffee shop. The recipe came from Chettinad in Tamil Nadu.",more:["In 1974 a second shop opened at 78 Race Course Road; it was later renamed Muthu's Curry. The restaurant moved to 138 Race Course Road, close to the first shop.","The fish head is cooked in a tamarind gravy with okra, tomatoes, brinjal and pineapple, and served in a claypot. Meals are served on banana leaf. His sons carry on the closely guarded family recipe."],lookFor:["Fish head curry served in a claypot","Meals served on banana leaf","Race Course Road, near the first 1974 shop"],sources:[{title:"Our Story",url:"https://www.muthuscurry.com/our-story",publisher:"Muthu's Curry",checkedAt:"2026-10-31"}],clip:{title:"A fish head from Chettinad",seconds:90,captions:["In 1969 Ayyakkannu opened a stall in a Klang Road coffee shop.","He sold a Chettinad-style fish head curry.","In 1974 a shop opened at 78 Race Course Road.","His sons still keep the family spice blend."]},tiles:[{value:1969,label:"stall on Klang Road",source:{title:"Our Story",url:"https://www.muthuscurry.com/our-story",publisher:"Muthu's Curry",checkedAt:"2026-10-31"}},{value:1974,label:"Race Course Road shop",source:{title:"Our Story",url:"https://www.muthuscurry.com/our-story",publisher:"Muthu's Curry",checkedAt:"2026-10-31"}},{value:1982,label:"named Muthu's Curry",source:{title:"Our Story",url:"https://www.muthuscurry.com/our-story",publisher:"Muthu's Curry",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-nae-um":{title:["Nae:um,","a fragrance","that brings back memories"],subtitle:"Telok Ayer Street · modern Korean tasting menu",lead:"Nae:um is chef Louis Han’s modern Korean restaurant on Telok Ayer Street. Its name is a Korean word for a fragrance that brings back memories.",more:["Louis Han was born in Seoul. He served with the United Nations in Lebanon and worked in Abu Dhabi before settling in Singapore. He started planning Nae:um in late 2019 and opened it in 2021, his first restaurant of his own.","It has held one MICHELIN star since 2022. In 2025 Korea’s agriculture ministry named it an outstanding Korean restaurant abroad, citing dishes like tomato dongchimi and buckwheat noodles.","Telok Ayer Street was set aside for the Chinese community in 1822 and was once the shoreline, before land was reclaimed."],lookFor:["Shophouse rows on one of Chinatown’s first streets","Thian Hock Keng temple, a short walk along the street"],sources:[{title:"About",url:"https://naeum.sg/about/",publisher:"Nae:um",checkedAt:"2026-10-29"},{title:"Korea designates 7 new outstanding Korean restaurants worldwide",url:"https://www.koreatimes.co.kr/lifestyle/travel-food/20251118/korea-designates-7-new-outstanding-korean-restaurants-worldwide",publisher:"The Korea Times",checkedAt:"2026-10-29"},{title:"Telok Ayer Street",url:"https://en.wikipedia.org/wiki/Telok_Ayer_Street",publisher:"Wikipedia",checkedAt:"2026-10-29"}],clip:{title:"A scent of Seoul",seconds:90,captions:["Nae:um is a Korean word for a fragrance that brings back memories.","Seoul-born chef Louis Han planned it from late 2019.","He opened in 2021, during the pandemic; a star followed in 2022.","Its dishes rework Korean classics such as cold buckwheat noodles."],poster:{src:"nearby/cards/nae-um.webp",alt:"Restored shophouses on Telok Ayer Street, the street where Nae:um is (not the restaurant itself)",credit:"Elisa.rolle 2010 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Telok_Ayer_Street,_2010.jpg"}},tiles:[{value:1822,label:"Telok Ayer set for Chinese",source:{title:"Telok Ayer Street",url:"https://en.wikipedia.org/wiki/Telok_Ayer_Street",publisher:"Wikipedia",checkedAt:"2026-10-29"}},{value:2021,label:"Nae:um opens",source:{title:"About",url:"https://naeum.sg/about/",publisher:"Nae:um",checkedAt:"2026-10-29"}},{value:2022,label:"first MICHELIN star",source:{title:"Korea designates 7 new outstanding Korean restaurants worldwide",url:"https://www.koreatimes.co.kr/lifestyle/travel-food/20251118/korea-designates-7-new-outstanding-korean-restaurants-worldwide",publisher:"The Korea Times",checkedAt:"2026-10-29"}}],reviewedAt:"2026-10-29"},"curated:sg-nagore-dargah":{title:["Nagore Dargah,","a shrine for","a saint from Nagore"],subtitle:"Telok Ayer Street · Indian Muslim heritage centre",lead:"Nagore Dargah on Telok Ayer Street was built by Chulias, Muslim migrants from South India. It honours Shahul Hamid, a holy man from Nagore in Tamil Nadu.",more:["The land was granted to a man named Kaderpillai in 1827, and colonial records date the building to 1828–1830. Its style mixes Indian-Islamic and classical forms: Corinthian capitals line the walls, and four tall corner towers end in onion domes. It became a National Monument in 1974.","The building fell into poor repair and was closed in 1996. After restoration it reopened on 29 May 2011 as the Nagore Dargah Indian Muslim Heritage Centre. The saint's birthday is still marked here each year with a 10-day maulid and the raising of flags."],lookFor:["Four corner towers topped with onion domes","Corinthian capitals along the front","Exhibits on Indian Muslim history inside"],sources:[{title:"About the Organisation",url:"https://ndsociety.sg/?p=171",publisher:"ND Society (Nagore Dargah Indian Muslim Heritage Centre)",checkedAt:"2026-10-31"},{title:"Nagore Durgha, Singapore",url:"https://en.wikipedia.org/wiki/Nagore_Durgha,_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"A saint from Nagore",seconds:90,captions:["Chulias, Muslims from South India, built this shrine.","It honours Shahul Hamid, a holy man from Nagore in Tamil Nadu.","Four corner towers of 14 layers end in onion domes.","Since 2011 it has been an Indian Muslim heritage centre."],poster:{src:"nearby/cards/sg-nagore-dargah.webp",alt:"Nagore Dargah on Telok Ayer Street, with its tall layered corner towers",credit:"Chainwit. 2025 · CC BY 4.0",url:"https://commons.wikimedia.org/wiki/File:Chinatown_SG_-_Nagore_Durgha_(Nagore_Dargah)_Sufi_Shrine_(2025)_-_img_01.jpg"}},tiles:[{value:1827,label:"land granted",source:{title:"About the Organisation",url:"https://ndsociety.sg/?p=171",publisher:"ND Society (Nagore Dargah Indian Muslim Heritage Centre)",checkedAt:"2026-10-31"}},{value:1974,label:"national monument",source:{title:"About the Organisation",url:"https://ndsociety.sg/?p=171",publisher:"ND Society (Nagore Dargah Indian Muslim Heritage Centre)",checkedAt:"2026-10-31"}},{value:2011,label:"heritage centre opens",source:{title:"About the Organisation",url:"https://ndsociety.sg/?p=171",publisher:"ND Society (Nagore Dargah Indian Muslim Heritage Centre)",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-national-gallery-singapore":{title:["National Gallery,","two monuments,","one museum"],subtitle:"St Andrew's Road · art museum",lead:"National Gallery Singapore opened in 2015 inside two National Monuments, the former Supreme Court and the former City Hall. It holds the largest public collection of modern art from Singapore and Southeast Asia.",more:["City Hall was built from 1926 to 1929 as the Municipal Building. Here, on 12 September 1945, Lord Louis Mountbatten accepted the Japanese surrender. The Supreme Court next door opened on 3 August 1939; its copper-green dome looks like that of St Paul's Cathedral in London.","The two buildings are joined by bridges and a new basement. The collection has more than 9,000 artworks, by artists such as Georgette Chen, Liu Kang and Raden Saleh."],lookFor:["Lady Justice in the Supreme Court's pediment","The copper-green dome of the Supreme Court","18 tall Corinthian columns on City Hall's front"],sources:[{title:"Former Supreme Court",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/former-supreme-court",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"},{title:"National Gallery Singapore",url:"https://en.wikipedia.org/wiki/National_Gallery_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"Court and town hall",seconds:95,captions:["The Gallery fills the old Supreme Court and City Hall.","The Supreme Court, with its green dome, opened in 1939.","In City Hall, the Japanese surrendered on 12 September 1945.","Since 2015, its halls show art of Singapore and Southeast Asia."]},tiles:[{value:1939,label:"Supreme Court opens",source:{title:"Former Supreme Court",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/former-supreme-court",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:2015,label:"Gallery opens",source:{title:"Former Supreme Court",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/former-supreme-court",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:9e3,label:"artworks",suffix:"+",grouped:!0,source:{title:"National Gallery Singapore",url:"https://en.wikipedia.org/wiki/National_Gallery_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-national-library-building":{title:["National Library,","16 storeys","of books"],subtitle:"Victoria Street · national library",lead:"The National Library Building at 100 Victoria Street opened on 22 July 2005. It replaced the old library on Stamford Road, which closed in 2004.",more:["Its twin 16-storey blocks are linked by bridges on the upper floors. The design contract went to T. R. Hamzah & Yeang, the firm of Malaysian architect Ken Yeang. The Lee Kong Chian Reference Library takes up Levels 7 to 13.","When it opened, the library could bring out almost its whole collection of about 500,000 items, including some 5,000 rare titles. Old bricks from the Stamford Road library were built into the new building."],lookFor:["The Pod, a bubble-like room on the roof","Bricks from the old Stamford Road library","The plaza with a café on the ground floor"],sources:[{title:"National Library, Singapore",url:"https://en.wikipedia.org/wiki/National_Library,_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"},{title:"A New Chapter",url:"https://biblioasia.nlb.gov.sg/inaugural-issue/new-chapter",publisher:"BiblioAsia (National Library Board)",checkedAt:"2026-10-31"}],clip:{title:"A library since 1823",seconds:90,captions:["The library's history goes back to 1823.","This building on Victoria Street opened in July 2005.","Two 16-storey blocks are linked by bridges.","The reference library fills Levels 7 to 13."],poster:{src:"nearby/cards/sg-national-library-building.webp",alt:"The National Library's two white blocks with open frames and a curved roof, trees in front",credit:"Diego Delso 2023 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Librería_nacional,_Singapur,_2023-08-17,_DD_15.jpg"}},tiles:[{value:1823,label:"library history begins",source:{title:"National Library, Singapore",url:"https://en.wikipedia.org/wiki/National_Library,_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:2005,label:"Victoria Street opening",source:{title:"A New Chapter",url:"https://biblioasia.nlb.gov.sg/inaugural-issue/new-chapter",publisher:"BiblioAsia (National Library Board)",checkedAt:"2026-10-31"}},{value:16,label:"storeys",source:{title:"National Library, Singapore",url:"https://en.wikipedia.org/wiki/National_Library,_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-national-museum-of-singapore":{title:["National Museum,","a dome on","Stamford Road"],subtitle:"Stamford Road · history museum",lead:"The National Museum of Singapore is the country’s oldest existing museum. Governor Sir Frederick Weld unlocked the front door of the building on Stamford Road on 12 October 1887.",more:["It opened as the Raffles Library and Museum, first filled with animal specimens from the region. In 1960 the museum split from the library and became the National Museum; its animal collection went to the university in 1972.","It was the Singapore History Museum from 1993 to 2006. After renovation it reopened in 2006 as the National Museum of Singapore. The front block was designed by Henry McCallum in the Neo-Palladian style."],lookFor:["The dome covered in fish-scale tiles","Queen Victoria’s coat of arms on the pediments","Coloured glass panels in the rotunda"],sources:[{title:"National Museum of Singapore",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/national-museum-of-singapore",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}],clip:{title:"A museum of many names",seconds:95,captions:["This is Singapore’s oldest existing museum.","Governor Weld opened its doors on 12 October 1887.","It began as the Raffles Library and Museum.","It took the name National Museum of Singapore in 2006."],poster:{src:"nearby/cards/national-museum-of-singapore.webp",alt:"The white National Museum building with its grey tiled dome, seen across Stamford Road",credit:"Marcin Konsek 2016 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:2016_Singapur,_Museum_Planning_Area,_Narodowe_Muzeum_Singapuru_(02).jpg"}},tiles:[{value:1887,label:"building opened",source:{title:"National Museum of Singapore",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/national-museum-of-singapore",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:1960,label:"named National Museum",source:{title:"National Museum of Singapore",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/national-museum-of-singapore",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:2006,label:"reopens after renovation",source:{title:"National Museum of Singapore",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/national-museum-of-singapore",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}}],thenNow:{then:{src:"nearby/cards/national-museum-of-singapore-then.webp",alt:"The Raffles Museum around 1900, its dome half hidden behind a large tree, with a low wall and gate in front",credit:"KITLV 105738, c.1900 · public domain",url:"https://commons.wikimedia.org/wiki/File:KITLV_-_105738_-_Raffles_Museum_in_Singapore_-_circa_1900.tif"},now:{src:"nearby/cards/national-museum-of-singapore-now.webp",alt:"The National Museum of Singapore in 2016, the white building and its tiled dome seen across Stamford Road",credit:"Marcin Konsek 2016 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:2016_Singapur,_Museum_Planning_Area,_Narodowe_Muzeum_Singapuru_(02).jpg"},thenLabel:"c.1900",nowLabel:"2016",captions:{then:{lead:"c.1900.",text:" The Raffles Library and Museum, behind trees and a low wall."},mid:{lead:"Same dome, new names.",text:" It became the National Museum in 1960."},now:{lead:"2016.",text:" The restored building, reopened in 2006, on Stamford Road."}}},reviewedAt:"2026-10-29"},"curated:sg-national-university-of-singapore":{title:["NUS,","from a medical school","of 1905"],subtitle:"Kent Ridge · national university campus",lead:"The National University of Singapore (NUS) is the country’s national public research university. Its main campus is at Kent Ridge, in Queenstown.",more:["Its story starts on 3 July 1905, when a medical school opened after Tan Jiak Kim and other community leaders raised money for it. It was later renamed King Edward VII College of Medicine, and in 1949 it joined Raffles College to form the University of Malaya.","NUS was formed in 1980, when the University of Singapore merged with Nanyang University. The three rings of the Nanyang University crest became part of the NUS coat of arms. Most departments moved from Bukit Timah to Kent Ridge between 1969 and 1986."],sources:[{title:"National University of Singapore",url:"https://en.wikipedia.org/wiki/National_University_of_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"From one school to a university",seconds:90,captions:["NUS is Singapore’s national public research university.","It began as a medical school, founded on 3 July 1905.","In 1980 two universities merged to form NUS.","Its main campus at Kent Ridge covers about 170 hectares."],poster:{src:"nearby/cards/national-university-of-singapore.webp",alt:"A road into the NUS Kent Ridge campus at Entrance C, with the NUS sign and a glass-fronted building",credit:"RFNirmala 2026 · CC BY 4.0",url:"https://commons.wikimedia.org/wiki/File:National_University_of_Singapore_Entrance_C_17Jul2026.jpg"}},tiles:[{value:1905,label:"medical school founded",source:{title:"National University of Singapore",url:"https://en.wikipedia.org/wiki/National_University_of_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:1980,label:"NUS formed by a merger",source:{title:"National University of Singapore",url:"https://en.wikipedia.org/wiki/National_University_of_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:170,label:"Kent Ridge campus",suffix:" ha",source:{title:"National University of Singapore",url:"https://en.wikipedia.org/wiki/National_University_of_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-oasia-hotel-downtown":{title:["Oasia Hotel Downtown,","a red tower","turning green"],subtitle:"Peck Seah Street · hotel and office tower",lead:"Oasia Hotel Downtown is a 27-storey hotel and office tower in the business district. It was designed by the Singapore firm WOHA and opened in April 2016.",more:["Its outside is a grid of orange, pink and maroon aluminium mesh, planted with 21 species of climbing plants. Over time the plants are meant to cover most of the mesh. About 40 percent of the building's volume is open green space.","Four sky gardens are cut into the tower, so the public spaces are cooled by moving air, not air conditioning. In 2018 the Council on Tall Buildings and Urban Habitat named it the best tall building in the world."],lookFor:["Climbing plants growing over the mesh","Open sky gardens cut into the tower","Red, pink and orange mesh between the leaves"],sources:[{title:"Oasia Hotel Downtown",url:"https://en.wikipedia.org/wiki/Oasia_Hotel_Downtown",publisher:"Wikipedia",checkedAt:"2026-10-31"},{title:"Oasia Hotel Downtown",url:"https://www.woha.net/project/oasia-hotel-downtown/",publisher:"WOHA",checkedAt:"2026-10-31"}],clip:{title:"A tower of climbing plants",seconds:90,captions:["This 27-storey tower holds a hotel and offices.","Singapore firm WOHA designed it; it opened in April 2016.","21 kinds of climbing plants grow on its coloured metal mesh.","Open sky gardens let the wind blow through the tower."]},tiles:[{value:2016,label:"hotel opens",source:{title:"Oasia Hotel Downtown",url:"https://en.wikipedia.org/wiki/Oasia_Hotel_Downtown",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:21,label:"climbing plant species",source:{title:"Oasia Hotel Downtown",url:"https://en.wikipedia.org/wiki/Oasia_Hotel_Downtown",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:2018,label:"best tall building award",source:{title:"Oasia Hotel Downtown",url:"https://en.wikipedia.org/wiki/Oasia_Hotel_Downtown",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-obba-bbq":{title:["O.BBa BBQ,","pork belly","on Little Korea’s strip"],subtitle:"Tanjong Pagar Road · Korean barbecue",lead:"O.BBa is a Korean barbecue and black bean noodle brand that started in Singapore in 2012. This walk-in grill is on Tanjong Pagar Road.",more:['The brand opened its first outlet at Bukit Timah on 5 May 2012 and its first Tanjong Pagar barbecue on 10 April 2014. It aims to give "the original taste of Korea at a reasonable price".',"So many Korean restaurants have opened along Tanjong Pagar Road that it is called Singapore’s Little Korea. Wikipedia counts as many as 15 Korean food outlets in a 300 m stretch near Duxton Hill."],lookFor:["Korean signs along the Tanjong Pagar Road shophouses","Other O.BBa shops nearby on the same road"],sources:[{title:"Brand OBBA",url:"https://obba-sg.com/obba",publisher:"O.BBa",checkedAt:"2026-10-29"},{title:"Tanjong Pagar",url:"https://en.wikipedia.org/wiki/Tanjong_Pagar",publisher:"Wikipedia",checkedAt:"2026-10-29"}],clip:{title:"Grilling on Little Korea’s strip",seconds:90,captions:["O.BBa is a Korean barbecue and jjajang brand in Singapore.","It started at Bukit Timah on 5 May 2012.","Its first Tanjong Pagar barbecue opened on 10 April 2014.","Today Tanjong Pagar Road is often called Singapore’s Little Korea."],poster:{src:"nearby/cards/obba-bbq.webp",alt:"Korean barbecue restaurants in the shophouses along Tanjong Pagar Road (not O.BBa itself)",credit:"Deoma12 2024 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Korean_BBQ_restaurants_along_Tanjong_Pagar_Road.jpg"}},tiles:[{value:2012,label:"O.BBa starts, Bukit Timah",source:{title:"Brand OBBA",url:"https://obba-sg.com/obba",publisher:"O.BBa",checkedAt:"2026-10-29"}},{value:2014,label:"first Tanjong Pagar BBQ",source:{title:"Brand OBBA",url:"https://obba-sg.com/obba",publisher:"O.BBa",checkedAt:"2026-10-29"}},{value:15,label:"Korean outlets in 300 m",source:{title:"Tanjong Pagar",url:"https://en.wikipedia.org/wiki/Tanjong_Pagar",publisher:"Wikipedia",checkedAt:"2026-10-29"},suffix:" "}],reviewedAt:"2026-10-29"},"curated:sg-ocbc-centre":{title:["OCBC Centre,","I. M. Pei's","first in Singapore"],subtitle:"Chulia Street · bank headquarters tower",lead:"OCBC Centre opened on 1 October 1976 as the headquarters of OCBC Bank. It was the first building in Singapore by the American architect I. M. Pei, and it rises 52 storeys.",more:["Two massive semi-circular concrete cores hold up the tower. Steel girders across the cores on the 4th, 20th and 35th floors each carry 14 floors of offices, so the tower could be built in three sections at the same time.","It cost S$100 million. The building is an example of Brutalist architecture. In 2025 a pair of peregrine falcons raised chicks in a gravel tray on its side facing the Singapore River."],lookFor:["Two curved concrete cores on the sides","The tower split into three blocks of floors"],sources:[{title:"OCBC Centre",url:"https://docomomo.sg/modernist-100/ocbc-centre",publisher:"Docomomo Singapore",checkedAt:"2026-10-31"},{title:"OCBC Centre",url:"https://en.wikipedia.org/wiki/OCBC_Centre",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"Built in three sections",seconds:92,captions:["OCBC Centre opened on 1 October 1976 by the river.","It was I. M. Pei's first building in Singapore.","Two huge concrete cores hold the 52-storey tower up.","Today it is still OCBC Bank's headquarters."]},tiles:[{value:1976,label:"officially opens",source:{title:"OCBC Centre",url:"https://docomomo.sg/modernist-100/ocbc-centre",publisher:"Docomomo Singapore",checkedAt:"2026-10-31"}},{value:52,label:"storeys",source:{title:"OCBC Centre",url:"https://docomomo.sg/modernist-100/ocbc-centre",publisher:"Docomomo Singapore",checkedAt:"2026-10-31"}},{value:198,label:"metres tall",source:{title:"OCBC Centre",url:"https://docomomo.sg/modernist-100/ocbc-centre",publisher:"Docomomo Singapore",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-ocean-financial-centre":{title:["Ocean Financial Centre,","an old shipping corner","since 1864"],subtitle:"Collyer Quay · office tower",lead:"Ocean Financial Centre is a 43-storey office tower at 10 Collyer Quay. It opened in 2011 on a corner where an Ocean Building has stood since 1864.",more:["The first Ocean Building had two storeys. It was built in 1864, the same year Collyer Quay was laid on reclaimed land. A five-storey Ocean Building replaced it in 1923 and held the head office of the Straits Steamship Company. A 28-storey Ocean Building followed in 1974, home to many shipping firms and air agencies.","The new tower has about 871,000 square feet of offices, with large floors free of columns. It is linked underground to Raffles Place MRT station and to Marina Bay. Ocean Colours, on the ground floor and in the basement, has places to eat."],lookFor:["Ocean Colours food outlets on the ground floor","The underground link to Raffles Place MRT","Collyer Quay, a road on 1864 reclaimed land"],sources:[{title:"Speech by Mr Tharman Shanmugaratnam at the opening of the Ocean Financial Centre (31 August 2011)",url:"https://www.mof.gov.sg/news-resources/newsroom/speech-by-mr-tharman-shanmugaratnam-deputy-prime-minister-minister-for-finance-minister-for-manpower-at-the-opening-of-the-ocean-financial-centre/",publisher:"Ministry of Finance Singapore",checkedAt:"2026-10-31"},{title:"Ocean Financial Centre",url:"https://www.keppelreit.com/property-portfolio/singapore/ocean-financial-centre/",publisher:"Keppel REIT",checkedAt:"2026-10-31"},{title:"Ocean Financial Centre",url:"https://en.wikipedia.org/wiki/Ocean_Financial_Centre",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"Four Ocean Buildings",seconds:90,captions:["A 43-storey office tower now stands at the end of Collyer Quay.","The first Ocean Building, two storeys high, went up here in 1864.","Shipping firms filled the Ocean Buildings of 1923 and 1974.","Today banks and law firms work here, above places to eat."]},tiles:[{value:1864,label:"first Ocean Building",source:{title:"Speech by Mr Tharman Shanmugaratnam at the opening of the Ocean Financial Centre (31 August 2011)",url:"https://www.mof.gov.sg/news-resources/newsroom/speech-by-mr-tharman-shanmugaratnam-deputy-prime-minister-minister-for-finance-minister-for-manpower-at-the-opening-of-the-ocean-financial-centre/",publisher:"Ministry of Finance Singapore",checkedAt:"2026-10-31"}},{value:43,label:"storeys",source:{title:"Ocean Financial Centre",url:"https://www.keppelreit.com/property-portfolio/singapore/ocean-financial-centre/",publisher:"Keppel REIT",checkedAt:"2026-10-31"}},{value:2011,label:"officially opened",source:{title:"Speech by Mr Tharman Shanmugaratnam at the opening of the Ocean Financial Centre (31 August 2011)",url:"https://www.mof.gov.sg/news-resources/newsroom/speech-by-mr-tharman-shanmugaratnam-deputy-prime-minister-minister-for-finance-minister-for-manpower-at-the-opening-of-the-ocean-financial-centre/",publisher:"Ministry of Finance Singapore",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-odette":{title:["Odette,","named after","the chef’s grandmother"],subtitle:"St Andrew’s Road · modern French, three MICHELIN stars",lead:"Odette is a modern French restaurant in National Gallery Singapore. Chef Julien Royer named it after his grandmother, who taught him that great dishes start with pure ingredients.",more:["Royer was born into a family of fourth-generation farmers in Cantal, France. He moved to Singapore in 2008, led the kitchen at JAAN, and opened Odette in the gallery’s Supreme Court wing in 2015.","Odette won two MICHELIN stars in 2016 and three in 2019, and has kept three in every guide since. For its tenth year, in 2025, the dining room was refreshed."],lookFor:["The former Supreme Court, opened in 1939","The dome over the old court’s rotunda","The Padang, the field in front of the gallery"],sources:[{title:"Odette (restaurant)",url:"https://en.wikipedia.org/wiki/Odette_(restaurant)",publisher:"Wikipedia",checkedAt:"2026-10-31"},{title:"Evolution",url:"https://odetterestaurant.com/evolution/",publisher:"Odette",checkedAt:"2026-10-31"},{title:"Chef Julien Royer",url:"https://odetterestaurant.com/chef-julien-royer/",publisher:"Odette",checkedAt:"2026-10-31"},{title:"National Gallery Singapore",url:"https://en.wikipedia.org/wiki/National_Gallery_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"},{title:"List of Michelin-starred restaurants in Singapore",url:"https://en.wikipedia.org/wiki/List_of_Michelin-starred_restaurants_in_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"A grandmother’s name",seconds:90,captions:["Odette is named after chef Julien Royer’s grandmother.","Royer grew up in Cantal, France, in a family of farmers.","It opened in 2015 and won three MICHELIN stars in 2019.","It sits in the old Supreme Court, now the National Gallery."],poster:{src:"nearby/cards/odette.webp",alt:"The former Supreme Court with its columns and green dome, now part of National Gallery Singapore (not the restaurant itself)",credit:"Philip Nalangan 2006 · CC BY 4.0",url:"https://commons.wikimedia.org/wiki/File:Former_Supreme_Court_Singapore.jpg"}},tiles:[{value:2015,label:"opens at National Gallery",source:{title:"Odette (restaurant)",url:"https://en.wikipedia.org/wiki/Odette_(restaurant)",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:2016,label:"two MICHELIN stars",source:{title:"Evolution",url:"https://odetterestaurant.com/evolution/",publisher:"Odette",checkedAt:"2026-10-31"}},{value:2019,label:"three MICHELIN stars",source:{title:"Evolution",url:"https://odetterestaurant.com/evolution/",publisher:"Odette",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-old-hill-street-police-station":{title:["Old Hill Street","Police Station,","rainbow windows"],subtitle:"Hill Street · former police station, now government offices",lead:"The former Hill Street Police Station was built from 1931 to 1934. Its six storeys held a police station and homes for hundreds of police officers and their families.",more:["Frank D. Ward, chief architect of the Public Works Department, designed it in the Neoclassical style. The barracks housed 180 single men, 140 married constables and their inspectors.","The Japanese painted it brown in 1943, and it was white again in 1949. The police moved out in December 1980. After a renovation in 1999 its more than 900 windows were painted in rainbow colours, and it reopened in 2000 as government offices."],lookFor:["Over 900 windows in rainbow colours","Tall Doric pilasters across two storeys","A pediment over the old main entrance"],sources:[{title:"Former Hill Street Police Station",url:"https://roots.gov.sg/places/places-landing/Places/national-monuments/former-hill-street-police-station",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-29"}],clip:{title:"The police skyscraper",seconds:95,captions:["It was called the biggest and grandest of its kind in Malaya.","It opened in 1934, with homes for police families above.","In 1943 it was painted brown to hide it from Allied pilots.","Since 1999 its 900-plus windows have been painted in rainbow colours."],poster:{src:"nearby/cards/old-hill-street-police-station.webp",alt:"The six-storey former police station with its rows of coloured window shutters",credit:"GoAheadFan95 2025 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Old_Hill_Street_Police_Station,_October_2025.jpg"}},tiles:[{value:1934,label:"building completed",source:{title:"Former Hill Street Police Station",url:"https://roots.gov.sg/places/places-landing/Places/national-monuments/former-hill-street-police-station",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-29"}},{value:900,label:"windows",suffix:"+",grouped:!0,source:{title:"Former Hill Street Police Station",url:"https://roots.gov.sg/places/places-landing/Places/national-monuments/former-hill-street-police-station",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-29"}},{value:1999,label:"windows painted in colours",source:{title:"Former Hill Street Police Station",url:"https://roots.gov.sg/places/places-landing/Places/national-monuments/former-hill-street-police-station",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-29"}}],reviewedAt:"2026-10-29"},"curated:sg-one-raffles-place":{title:["One Raffles Place,","a 280-metre bank tower","by Kenzo Tange"],subtitle:"Raffles Place · office towers and mall",lead:"One Raffles Place began as the OUB Centre, head office of Overseas Union Bank. Designed by Japanese architect Kenzo Tange, its 280-metre tower opened in 1986.",more:["Work began in 1981. The ground was full of large boulders, and because Raffles Place was so busy, dug-out earth could only be cleared at night. When the tower opened, The Business Times claimed it was the tallest in the world outside the United States.","In 2008 the old shopping podium made way for a second, 38-storey tower designed by Paul Noritake Tange. It opened in 2012, and the whole complex was renamed One Raffles Place. The rebuilt six-level shopping podium reopened in 2014."],lookFor:["Tower One, 60 storeys of steel and concrete","Tower Two, 38 storeys, opened in 2012","The underground link to Raffles Place MRT"],sources:[{title:"One Raffles Place",url:"https://en.wikipedia.org/wiki/One_Raffles_Place",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"The OUB Centre",seconds:90,captions:["This 280-metre tower was built as the OUB Centre, for a bank.","Kenzo Tange designed it, and it opened in two phases in 1986.","Boulders filled the site, and earth could be taken away only at night.","A second tower came in 2012, and shops fill the podium today."]},tiles:[{value:1986,label:"OUB Centre opens",source:{title:"One Raffles Place",url:"https://en.wikipedia.org/wiki/One_Raffles_Place",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:280,label:"metres, Tower One",suffix:" m",source:{title:"One Raffles Place",url:"https://en.wikipedia.org/wiki/One_Raffles_Place",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:2012,label:"Tower Two opens",source:{title:"One Raffles Place",url:"https://en.wikipedia.org/wiki/One_Raffles_Place",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-outram-park-fried-kway-teow":{title:["Outram Park,","char kway teow","now at Hong Lim"],subtitle:"Hong Lim Market and Food Centre · char kway teow",lead:"Outram Park Fried Kway Teow Mee sells one dish: char kway teow, flat rice noodles fried with dark soy sauce, chilli, cockles, bean sprouts, egg and pork lard. It keeps the name of Outram Park, where it used to trade, but it is now at Hong Lim Market and Food Centre.",more:["Orders are cooked in batches from scratch, and Eatbook singles out its wok hei. Seth Lui reports queues of up to 90 minutes, even outside lunch hours.","Mr Ng runs the stall with his wife. His father founded it as a streetside stall, and Mr Ng has said it may have no successor when he retires."],lookFor:["The queue at stall #02-17","Extra cockles or an extra egg for a little more","Parcels of pork lard on top"],sources:[{title:"Outram Park Fried Kway Teow Mee",url:"https://eatbook.sg/outram-park-fried-kway-teow-mee/",publisher:"Eatbook (food blog)",checkedAt:"2026-10-29"},{title:"Outram Park Fried Kway Teow Mee: 90-minute queue",url:"https://sethlui.com/outram-park-fried-kway-teow-mee-singapore/",publisher:"Seth Lui (food blog)",checkedAt:"2026-10-29"},{title:"Char kway teow",url:"https://en.wikipedia.org/wiki/Char_kway_teow",publisher:"Wikipedia",checkedAt:"2026-10-29"}],clip:{title:"One dish, long queues",seconds:90,captions:["Char kway teow is flat rice noodles fried with soy sauce.","The stall keeps the name of Outram Park, where it once was.","It sells one dish, cooked in batches from scratch.","Queues can last 90 minutes; ask for it with or without chilli."],poster:{src:"nearby/cards/sg-outram-park-fried-kway-teow.webp",alt:"Hong Lim Market and Food Centre entrance in the evening, where the stall is (not the stall itself)",credit:"Kbseah 2025 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Hong_Lim_Market_and_Food_Centre,_entrance.jpg"}},orderProposal:{kind:"char-kway-teow",title:"Order char kway teow",intro:"Char kway teow is flat rice noodles stir-fried with soy sauce, cockles, egg and bean sprouts.",base:"one char kway teow",baseMeaning:"One plate of fried flat rice noodles",steps:[{id:"greet",question:"Who is at the counter?",options:[{id:"uncle",label:"Uncle",term:"Uncle,",meaning:""},{id:"auntie",label:"Auntie",term:"Auntie,",meaning:""}]},{id:"chilli",question:"Chilli?",options:[{id:"yes",label:"With chilli",term:"with chilli",meaning:"with chilli"},{id:"no",label:"No chilli",term:"no chilli",meaning:"without chilli"}]},{id:"extra",question:"Anything extra?",options:[{id:"none",label:"Nothing",term:"",meaning:""},{id:"cockles",label:"Add cockles",term:"add cockles",meaning:"with extra cockles"},{id:"egg",label:"Add egg",term:"add egg",meaning:"with an extra egg"}],note:"At this stall extra cockles cost S$2 and extra egg S$0.50 (Seth Lui, 2025)."},{id:"where",question:"Eat here or take away?",options:[{id:"here",label:"Having here",term:"having here",meaning:"to eat here"},{id:"dabao",label:"Da bao",term:"da bao",meaning:"to take away"}]}],sources:[{title:"Outram Park Fried Kway Teow Mee: 90-minute queue",url:"https://sethlui.com/outram-park-fried-kway-teow-mee-singapore/",publisher:"Seth Lui (food blog)",checkedAt:"2026-10-29"},{title:"Outram Park Fried Kway Teow Mee",url:"https://eatbook.sg/outram-park-fried-kway-teow-mee/",publisher:"Eatbook (food blog)",checkedAt:"2026-10-29"},{title:"Char kway teow",url:"https://en.wikipedia.org/wiki/Char_kway_teow",publisher:"Wikipedia",checkedAt:"2026-10-29"},{title:"Singlish vocabulary",url:"https://en.wikipedia.org/wiki/Singlish_vocabulary",publisher:"Wikipedia",checkedAt:"2026-10-29"}]},reviewedAt:"2026-10-29"},"curated:sg-parkroyal-collection-pickering":{title:["PARKROYAL COLLECTION","Pickering,","a hotel of gardens"],subtitle:"Hong Lim Park · garden hotel",lead:"PARKROYAL COLLECTION Pickering is a hotel between the business district and Chinatown, next to Hong Lim Park. It was designed by the Singapore firm WOHA and opened in January 2013.",more:["The design was inspired by the park, by rice terraces and by natural landscapes. Its sky gardens, green walls and water features add up to 15,000 square metres of greenery, around double the area of the site.","Each of its 367 rooms has a garden view. Solar-powered watering, rainwater retention and sun shading helped it reach Green Mark Platinum, Singapore's highest green building rating. It was renamed from PARKROYAL on Pickering in January 2020."],lookFor:["Curving terraces planted with trees","Green walls and water features","Views across Hong Lim Park"],sources:[{title:"Parkroyal Collection Pickering",url:"https://www.woha.net/project/parkroyal-on-pickering/",publisher:"WOHA",checkedAt:"2026-10-31"},{title:"Parkroyal Collection Pickering",url:"https://en.wikipedia.org/wiki/Parkroyal_Collection_Pickering",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"Terraces in the sky",seconds:90,captions:["This hotel by the Singapore firm WOHA stands by Hong Lim Park.","It opened in January 2013 as PARKROYAL on Pickering.","Its terraces hold 15,000 m² of greenery, about twice the site.","Every one of its 367 rooms looks out on a garden."],poster:{src:"nearby/cards/sg-parkroyal-collection-pickering.webp",alt:"The hotel’s glass towers with planted sky terraces, seen across Hong Lim Park",credit:"Basile Morin 2018 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Hotel_Park_Royal_on_Pickering_from_Hong_Lim_Park_in_Singapore.jpg"}},tiles:[{value:2013,label:"hotel opens",source:{title:"Parkroyal Collection Pickering",url:"https://en.wikipedia.org/wiki/Parkroyal_Collection_Pickering",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:15e3,label:"m² of greenery",grouped:!0,source:{title:"Parkroyal Collection Pickering",url:"https://www.woha.net/project/parkroyal-on-pickering/",publisher:"WOHA",checkedAt:"2026-10-31"}},{value:367,label:"guest rooms",source:{title:"Parkroyal Collection Pickering",url:"https://www.woha.net/project/parkroyal-on-pickering/",publisher:"WOHA",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-parkview-square":{title:["Parkview Square,","Art Deco","in the 2000s"],subtitle:"North Bridge Road · office building",lead:"Parkview Square was completed in 2002 but designed in the Art Deco style, inspired by New York's 1929 Chanin Building. American architect James Adams designed it, with DP Architects as local architect.",more:["The outside is clad in brown granite, bronze, lacquer and glass. Eight giant statues of men holding a ball of light guard the crown, and gargoyles decorate the walls. The Art Deco lobby has a 15-metre-high ceiling.","In the plaza stand bronze figures such as Sun Yat-sen, Abraham Lincoln, Salvador Dalí and Mozart, and a golden crane with a Chinese poem. The lobby bar, Atlas, has a three-storey tower of over a thousand gins."],lookFor:["The golden crane statue in the plaza","Bronze statues of Lincoln, Dalí and Mozart","Gargoyles and giant statues at the top"],sources:[{title:"Parkview Square",url:"https://en.wikipedia.org/wiki/Parkview_Square",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"New York style, 2002",seconds:90,captions:["Parkview Square was completed in 2002.","Its Art Deco look comes from New York's 1929 Chanin Building.","Eight giant statues stand around the crown.","Bronze figures of famous people fill the plaza."]},tiles:[{value:2002,label:"completed",source:{title:"Parkview Square",url:"https://en.wikipedia.org/wiki/Parkview_Square",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:8,label:"giant statues on the crown",source:{title:"Parkview Square",url:"https://en.wikipedia.org/wiki/Parkview_Square",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:15,label:"metre-high lobby ceiling",source:{title:"Parkview Square",url:"https://en.wikipedia.org/wiki/Parkview_Square",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-parliament-house":{title:["Parliament House,","where the House","has met since 1999"],subtitle:"North Bridge Road · seat of Parliament",lead:"Parliament House on North Bridge Road is where Singapore's Parliament meets. It was finished in 1999, after the old building next door grew too small.",more:["Members of Parliament grew from 51 in 1963 to 75 in 1983, and the old chamber ran out of room. Building began in 1995. On 6 September 1999, MPs walked from the old house to the new one and carried on their debate in the new Chamber.","The grey colour and rows of columns echo the older colonial buildings nearby. The complex takes in a restored 1864 building that once held the Attorney-General's Chambers; it became a national monument in 1992.","Sittings usually start at 1.30 pm and are open to the public, with passes given at the Public Entrance on Parliament Place. Bring photo ID and dress modestly. Photography is not allowed inside."],lookFor:["The prism-shaped peak above the main foyer","The palm-lined driveway and fountain pools","The restored 1864 block, now part of the complex"],sources:[{title:"Parliament House, Singapore",url:"https://en.wikipedia.org/wiki/Parliament_House,_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"},{title:"Visit & Learn",url:"https://www.parliament.gov.sg/visit-learn",publisher:"Parliament of Singapore",checkedAt:"2026-10-31"}],clip:{title:"The walk over",seconds:90,captions:["Singapore's Parliament has met in this building since 1999.","That year MPs walked over from the old Parliament House next door.","The prism on the roof was designed by President Ong Teng Cheong.","Sittings are open to the public, who watch from a gallery."]},tiles:[{value:1864,label:"oldest block built",source:{title:"Parliament House, Singapore",url:"https://en.wikipedia.org/wiki/Parliament_House,_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:1999,label:"MPs move in",source:{title:"Parliament House, Singapore",url:"https://en.wikipedia.org/wiki/Parliament_House,_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:100,label:"seats in the Chamber",source:{title:"Parliament House, Singapore",url:"https://en.wikipedia.org/wiki/Parliament_House,_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-pasir-panjang-christ-church":{title:["Pasir Panjang Christ Church,","from a Sunday class","of 1935"],subtitle:"Pasir Panjang Road · independent church",lead:"Pasir Panjang Christ Church is a church on Pasir Panjang Road. It began in 1935 as a Sunday School class in a rented bungalow.",more:["The class met at 356 Pasir Panjang Road and moved a few times during the Japanese occupation. In the late 1950s Pastor Phoa Hock Seng bought the bungalow with gifts from friends and family. He named it Pasir Panjang Christ Church because he believed the church belonged to Christ, not to him.","In 1973 the church bought the site at 302 Pasir Panjang Road, and Pastor Phoa laid the foundation stone. The building was completed in 1974. A multi-purpose hall block followed in 1991."],sources:[{title:"About",url:"https://ppcc.org.sg/about/",publisher:"Pasir Panjang Christ Church",checkedAt:"2026-10-31"}],clip:{title:"A Sunday class in a bungalow",seconds:85,captions:["In 1935 a school principal began a Sunday class at home.","His rented bungalow stood at 356 Pasir Panjang Road.","Pastor Phoa Hock Seng bought it and named the church.","The church at No. 302 was completed in 1974."]},tiles:[{value:1935,label:"Sunday class begins",source:{title:"About",url:"https://ppcc.org.sg/about/",publisher:"Pasir Panjang Christ Church",checkedAt:"2026-10-31"}},{value:1974,label:"church building completed",source:{title:"About",url:"https://ppcc.org.sg/about/",publisher:"Pasir Panjang Christ Church",checkedAt:"2026-10-31"}},{value:1991,label:"hall block added",source:{title:"About",url:"https://ppcc.org.sg/about/",publisher:"Pasir Panjang Christ Church",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-peach-blossoms":{title:["Peach Blossoms,","Singapore’s Chinese","food traditions"],subtitle:"Raffles Boulevard · modern Chinese",lead:"Peach Blossoms is a Chinese restaurant shaped by Singapore’s food heritage: Hakka, Teochew, Hokkien, Cantonese and Hainanese cooking, with Southeast Asian touches.",more:["It was part of the former Marina Mandarin hotel and reopened in December 2020, after the hotel became PARKROYAL COLLECTION Marina Bay. It is on level 5 and seats 132.","Executive Chinese Chef Edward Chong trained under Sam Leong and Yong Bing Ngen. His menu turns Hainanese chicken rice into a tart, and bak kut teh into a take on Buddha Jumps Over the Wall."],lookFor:["The chicken rice tart","Bak kut teh as Buddha Jumps Over the Wall"],sources:[{title:"Peach Blossoms",url:"https://www.panpacific.com/en/hotels-and-resorts/pr-collection-marina-bay/dining/peach-blossoms.html",publisher:"Pan Pacific Hotels Group",checkedAt:"2026-10-31"},{title:"Peach Blossoms review: modern Chinese cuisine comes into full flower",url:"https://www.factmagazines.com/singapore/peach-blossoms-review-modern-chinese-cuisine-comes-into-full-flower",publisher:"Fact Magazine",checkedAt:"2026-10-31"}],clip:{title:"Chicken rice as a tart",seconds:90,captions:["The menu draws on Hakka, Teochew, Hokkien and Cantonese food.","It was part of the old Marina Mandarin hotel.","It reopened in December 2020 in the renamed hotel.","Chicken rice comes as a tart with kampachi and caviar."],poster:{src:"nearby/cards/peach-blossoms.webp",alt:"The PARKROYAL COLLECTION Marina Bay hotel, home of Peach Blossoms (not the restaurant itself)",credit:"Diego Delso 2023 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Hotel_Marina_Mandarin,_Nicoll_Highway,_Singapur,_2023-08-18,_DD_13.jpg"}},tiles:[{value:2020,label:"reopens in the new hotel",source:{title:"Peach Blossoms review: modern Chinese cuisine comes into full flower",url:"https://www.factmagazines.com/singapore/peach-blossoms-review-modern-chinese-cuisine-comes-into-full-flower",publisher:"Fact Magazine",checkedAt:"2026-10-31"}},{value:132,label:"guests it seats",source:{title:"Peach Blossoms",url:"https://www.panpacific.com/en/hotels-and-resorts/pr-collection-marina-bay/dining/peach-blossoms.html",publisher:"Pan Pacific Hotels Group",checkedAt:"2026-10-31"}},{value:78,label:"rank, 2026 Asia’s 51–100",source:{title:"Peach Blossoms",url:"https://www.panpacific.com/en/hotels-and-resorts/pr-collection-marina-bay/dining/peach-blossoms.html",publisher:"Pan Pacific Hotels Group",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-people-s-park-complex":{title:["People’s Park Complex,","a “city room”","in Chinatown"],subtitle:"Park Road · flats above a shopping centre",lead:"People’s Park Complex was completed in 1973. It puts a 25-storey block of flats on top of a six-storey podium of shops and offices, and was the first mixed-use building of its kind in Southeast Asia.",more:["The site was once an open park, and later held the People’s Market, which a fire destroyed in 1966. The complex was designed by Design Partnership (now DP Architects), set up in 1967 by William Lim, Tay Kheng Soon and Koh Seow Chuan.","Inside, its “city room” of linked atriums was Singapore’s first shopping-centre atrium, an idea from Japan’s Metabolist architects of the 1960s. In the 1970s it was the largest shopping complex in Singapore."],lookFor:["The long slab of flats above the shops","The open atrium inside the shopping centre","The red and white paint from 2025"],sources:[{title:"People's Park Complex",url:"https://roots.gov.sg/places/places-landing/Places/surveyed-sites/peoples-park-complex",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-29"},{title:"People's Park Complex",url:"https://en.wikipedia.org/wiki/People%27s_Park_Complex",publisher:"Wikipedia",checkedAt:"2026-10-29"}],clip:{title:"A city room",seconds:90,captions:["Shops and offices below, 25 storeys of flats above.","The site was a park, then a market that burned down in 1966.","Its atrium was Singapore’s first shopping-centre atrium.","In 2025 its outside was repainted red and white."],poster:{src:"nearby/cards/people-s-park-complex.webp",alt:"People’s Park Complex painted red and white, its Chinese name down the side of the slab of flats",credit:"S5A-0043 2026 · CC BY 4.0",url:"https://commons.wikimedia.org/wiki/File:(SGP-Singapore)_People%27s_Park_Complex_2026-02-17_-_2.jpg"}},tiles:[{value:1970,label:"shopping centre completed",source:{title:"People's Park Complex",url:"https://en.wikipedia.org/wiki/People%27s_Park_Complex",publisher:"Wikipedia",checkedAt:"2026-10-29"}},{value:1973,label:"complex completed",source:{title:"People's Park Complex",url:"https://roots.gov.sg/places/places-landing/Places/surveyed-sites/peoples-park-complex",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-29"}},{value:31,label:"storeys",source:{title:"People's Park Complex",url:"https://en.wikipedia.org/wiki/People%27s_Park_Complex",publisher:"Wikipedia",checkedAt:"2026-10-29"}}],reviewedAt:"2026-10-29"},"curated:sg-peranakan-museum":{title:["Peranakan Museum,","in a 1912 school"],subtitle:"Armenian Street · museum in the former Tao Nan School",lead:"The Peranakan Museum presents Peranakan culture in Singapore and Southeast Asia. It is housed in the former Tao Nan School, completed in 1912 and now a National Monument.",more:["Tao Nan School was started in 1906 by a group of Hokkien merchants and moved to Armenian Street in 1912. In 1916 it began teaching in Mandarin instead of Hokkien. The school moved to Marine Parade in 1982.","The museum opened here in 2008 and reopened on 17 February 2023 after a renovation. Its three permanent galleries, Origins, Home and Style, show more than 800 objects."],lookFor:["Two black cast-iron eagles on the gate posts","Corinthian capitals on fluted columns","Wide verandahs and large windows for the breeze"],sources:[{title:"Former Tao Nan School (now The Peranakan Museum)",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/former-tao-nan-school-now-the-peranakan-museum",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-29"},{title:"About Peranakan Museum",url:"https://www.peranakanmuseum.nhb.gov.sg/about-us/about-peranakan-museum",publisher:"Peranakan Museum (National Heritage Board)",checkedAt:"2026-10-29"}],clip:{title:"From school to museum",seconds:90,captions:["This museum shows the life and arts of the Peranakans.","The building was Tao Nan School, completed in 1912.","Two cast-iron eagles, about 200 kg each, guard the gate.","Three floors cover origins, home and style."],poster:{src:"nearby/cards/peranakan-museum.webp",alt:"The white former Tao Nan School building on Armenian Street, now the Peranakan Museum",credit:"GoAheadFan95 2024 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Peranakan_Museum_(Old_Tao_Nan_School),_August_2024.jpg"}},tiles:[{value:1912,label:"school building completed",source:{title:"About Peranakan Museum",url:"https://www.peranakanmuseum.nhb.gov.sg/about-us/about-peranakan-museum",publisher:"Peranakan Museum (National Heritage Board)",checkedAt:"2026-10-29"}},{value:2008,label:"Peranakan Museum opens",source:{title:"About Peranakan Museum",url:"https://www.peranakanmuseum.nhb.gov.sg/about-us/about-peranakan-museum",publisher:"Peranakan Museum (National Heritage Board)",checkedAt:"2026-10-29"}},{value:800,label:"objects on display",suffix:"+",grouped:!0,source:{title:"About Peranakan Museum",url:"https://www.peranakanmuseum.nhb.gov.sg/about-us/about-peranakan-museum",publisher:"Peranakan Museum (National Heritage Board)",checkedAt:"2026-10-29"}}],reviewedAt:"2026-10-29"},"curated:sg-pinnacle-duxton":{title:["Pinnacle@Duxton,","public housing","50 storeys high"],subtitle:"Cantonment Road · public housing with a sky bridge",lead:"Pinnacle@Duxton is a public housing estate of seven 50-storey towers, completed in 2009. The towers are linked at the 26th and 50th floors by sky gardens.",more:["The site, Duxton Plain, once had the first two ten-storey HDB blocks in the Tanjong Pagar area. The design, by ARC Studio Architecture + Urbanism with RSP Architects Planners & Engineers, won an international competition held in 2001.","The 26th-floor sky garden is for residents only. The public can visit the 50th-storey skybridge from 9 am to 9 pm for $6, up to 150 people a day; register and pay at the kiosk at Block 1G."],lookFor:["Sky gardens joining all seven towers","Views of the city and port from the 50th storey"],sources:[{title:"The Pinnacle@Duxton",url:"https://en.wikipedia.org/wiki/The_Pinnacle@Duxton",publisher:"Wikipedia",checkedAt:"2026-10-29"},{title:"Access by the Public",url:"http://www.pinnacleduxton.com.sg/Public.html",publisher:"The Pinnacle@Duxton",checkedAt:"2026-10-29"}],clip:{title:"Homes in the sky",seconds:90,captions:["Seven towers of public flats, 50 storeys high, finished in 2009.","The site once had the first ten-storey HDB blocks in Tanjong Pagar.","Sky gardens on the 26th and 50th floors join all seven towers.","Visitors can pay $6 to walk the 50th-storey skybridge."],poster:{src:"nearby/cards/pinnacle-duxton.webp",alt:"The tall towers of Pinnacle@Duxton linked by sky bridges",credit:"Someformofhuman 2010 · CC BY-SA 3.0",url:"https://commons.wikimedia.org/wiki/File:Pinnacle@Duxton,_Singapore_-_20100101.jpg"}},tiles:[{value:2009,label:"completed",source:{title:"The Pinnacle@Duxton",url:"https://en.wikipedia.org/wiki/The_Pinnacle@Duxton",publisher:"Wikipedia",checkedAt:"2026-10-29"}},{value:50,label:"storeys",source:{title:"The Pinnacle@Duxton",url:"https://en.wikipedia.org/wiki/The_Pinnacle@Duxton",publisher:"Wikipedia",checkedAt:"2026-10-29"}},{value:150,label:"public visitors a day, max",source:{title:"Access by the Public",url:"http://www.pinnacleduxton.com.sg/Public.html",publisher:"The Pinnacle@Duxton",checkedAt:"2026-10-29"}}],reviewedAt:"2026-10-29"},"curated:sg-queenstown-baptist-church":{title:["Queenstown Baptist Church,","from a Sunday school","of 1955"],subtitle:"Margaret Drive · Baptist church on the heritage trail",lead:"Queenstown Baptist Church is on Margaret Drive and is a stop on the My Queenstown Heritage Trail. It started in 1955 as a Sunday school run by an American Baptist missionary.",more:["The first services were held in Cantonese and English at her home on Barbary Walk. In 1956 the Sunday school moved to Birkhall Primary School. Then the Malaya Baptist Mission bought land from the Singapore Improvement Trust, and a chapel for 120 people was dedicated on 3 August 1958.","The church was organised with 33 charter members in 1962. Its early years came as new residents moved into the newly built Dawson Estate. In 2011 the old chapel was pulled down for a new building with two 600-seat halls and 19 classrooms."],sources:[{title:"Queenstown Baptist Church – My Queenstown Heritage Trail",url:"https://www.roots.gov.sg/places/places-landing/Places/landmarks/my-queenstown-heritage-trail/queenstown-baptist-church",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"},{title:"Our History",url:"https://qbc.org.sg/our-history/",publisher:"Queenstown Baptist Church",checkedAt:"2026-10-31"}],clip:{title:"Born in a missionary’s home",seconds:90,captions:["It began in 1955 as a Sunday school in a missionary’s home.","Services were in Cantonese and English, on Barbary Walk.","A chapel for 120 people was dedicated on 3 August 1958.","Its new building has two worship halls of 600 seats each."]},tiles:[{value:1955,label:"Sunday school begins",source:{title:"Queenstown Baptist Church – My Queenstown Heritage Trail",url:"https://www.roots.gov.sg/places/places-landing/Places/landmarks/my-queenstown-heritage-trail/queenstown-baptist-church",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:1958,label:"first chapel dedicated",source:{title:"Queenstown Baptist Church – My Queenstown Heritage Trail",url:"https://www.roots.gov.sg/places/places-landing/Places/landmarks/my-queenstown-heritage-trail/queenstown-baptist-church",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:600,label:"seats in each of two halls",source:{title:"Queenstown Baptist Church – My Queenstown Heritage Trail",url:"https://www.roots.gov.sg/places/places-landing/Places/landmarks/my-queenstown-heritage-trail/queenstown-baptist-church",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-raffles-city":{title:["Raffles City,","I. M. Pei's city","in one block"],subtitle:"North Bridge Road · mall, hotels and offices",lead:"Raffles City fills a whole block between Stamford Road, Beach Road, Bras Basah Road and North Bridge Road. Designed by I. M. Pei, it opened in 1986 on the former site of Raffles Institution.",more:["The plan was first announced in 1969 as the Raffles International Centre. Rising costs held it up, and building only began in 1980. Its aluminium finish and simple shapes were a sharp modern contrast to the Victorian and classical buildings of the district.","The complex has the 73-storey Swissôtel The Stamford, once the world's tallest hotel, the twin-tower Fairmont Singapore and the 42-storey Raffles City Tower of offices, all above a shopping mall and a convention centre."],lookFor:["Aluminium-clad towers with simple geometric lines","Swissôtel The Stamford, 73 storeys tall","Escalators to City Hall MRT (Exit A)"],sources:[{title:"Raffles City Singapore",url:"https://en.wikipedia.org/wiki/Raffles_City_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"Where a school once stood",seconds:90,captions:["One block holds a mall, two hotels, offices and a convention centre.","It stands where Raffles Institution, Singapore's first school, stood.","Its 73-storey hotel was once the tallest hotel in the world.","Today you can walk in straight from City Hall MRT station."],poster:{src:"nearby/cards/raffles-city.webp",alt:"The round Raffles City mall entrance with tall white hotel and office towers rising behind",credit:"Diego Delso 2023 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Raffles_City,_Singapur,_2023-08-17,_DD_18.jpg"}},tiles:[{value:1980,label:"groundbreaking",source:{title:"Raffles City Singapore",url:"https://en.wikipedia.org/wiki/Raffles_City_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:1986,label:"opens to the public",source:{title:"Raffles City Singapore",url:"https://en.wikipedia.org/wiki/Raffles_City_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:73,label:"storeys, Swissôtel",source:{title:"Raffles City Singapore",url:"https://en.wikipedia.org/wiki/Raffles_City_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-raffles-hotel":{title:["Raffles Hotel,","home of","the Singapore Sling"],subtitle:"Beach Road · historic hotel",lead:"Four Armenian brothers, Martin, Tigran, Aviet and Arshak Sarkies, founded the Raffles Hotel in 1887. The three-storey Main Building, designed by Regent A. J. Bidwell of Swan & Maclaren, was completed in 1899.",more:["The Neo-Renaissance building has wide verandahs, rows of Palladian windows and Corinthian and Doric columns. The cast-iron porch you see is a copy of the 1913 original, made during the 1989–1991 restoration.","The Singapore Sling was created here by the barman Ngiam Tong Boon. During the Second World War the hotel was renamed Syonan Ryokan. Guests have included Charlie Chaplin, Rudyard Kipling and Michael Jackson."],lookFor:["The cast-iron porch at the entrance","The Victorian fountain in the Palm Garden","Rows of Palladian windows on the verandahs"],sources:[{title:"Raffles Hotel",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/raffles-hotel",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}],clip:{title:"Four brothers' hotel",seconds:98,captions:["Four Armenian brothers, the Sarkies, opened it in 1887.","The three-storey Main Building was finished in 1899.","Barman Ngiam Tong Boon created the Singapore Sling here.","Today it has more than 100 suites and courtyards."]},tiles:[{value:1887,label:"Sarkies brothers open it",source:{title:"Raffles Hotel",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/raffles-hotel",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:1899,label:"Main Building completed",source:{title:"Raffles Hotel",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/raffles-hotel",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:100,label:"suites",suffix:"+",source:{title:"Raffles Hotel",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/raffles-hotel",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}}],thenNow:{then:{src:"nearby/cards/sg-raffles-hotel-then.webp",alt:"Black-and-white view across Beach Road to the Raffles Hotel main building, with palms and its porch",credit:"Marine Photo Service, 1920–1939 · public domain",url:"https://commons.wikimedia.org/wiki/File:A_view_of_the_Raffles_Hotel,_Singapore_RMG_P95135.tiff"},now:{src:"nearby/cards/sg-raffles-hotel-now.webp",alt:"The white front of the Raffles Hotel main building with its verandahs and cast-iron porch in 2023",credit:"Daniel Case 2023 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Front_facade_of_Raffles_Hotel,_Singapore,_from_southeast.jpg"},thenLabel:"1920–1939",nowLabel:"2023",captions:{then:{lead:"1920–1939.",text:" The main building seen across Beach Road, behind palms."},mid:{lead:"Same front, decades apart.",text:" It was last restored from 1989 to 1991."},now:{lead:"2023.",text:" Wide verandahs and a copy of the old cast-iron porch."}}},reviewedAt:"2026-10-29"},"curated:sg-red-dot-design-museum":{title:["Red Dot Design Museum,","award winners","on Marina Bay"],subtitle:"Marina Boulevard · design museum",lead:"Everything shown at the Red Dot Design Museum has won the international Red Dot Design Award. Panels of design experts judge it in three areas: product design, communication design and design concept.",more:["The museum goes back to a permanent show of well-designed industrial products, set up at Villa Hügel in Essen, Germany, in 1955. The Singapore museum opened on Maxwell Road in 2005 and moved to Marina Bay in 2017.","The building is glass in strong geometric shapes, with steel structure and large overhanging roofs. There is a design shop, with work by Singapore designers, and a café and bar."],lookFor:["Large overhanging roofs on the glass building","Work by Singapore designers in the shop","The Marina Bay Waterfront Promenade outside"],sources:[{title:"Red Dot Design Museum",url:"https://www.roots.gov.sg/places/places-landing/Places/museums/red-dot-design-museum",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"},{title:"Red Dot Design Museum Singapore",url:"https://red-dot.org/design-concept/red-dot-design-museum-singapore",publisher:"Red Dot",checkedAt:"2026-10-31"}],clip:{title:"Only award winners inside",seconds:90,captions:["Every object here has won the Red Dot Design Award.","The idea began in Essen, Germany, in 1955.","Singapore’s museum opened on Maxwell Road in 2005.","Since 2017 it has stood in glass on the Marina Bay promenade."],poster:{src:"nearby/cards/red-dot-design-museum.webp",alt:"The museum’s glass front with steel struts, an overhanging roof and red screens at the door",credit:"JudiciousGoat 2024 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Red_dot_design_museum_singapore_exterior.jpg"}},tiles:[{value:1955,label:"first show in Essen, Germany",source:{title:"Red Dot Design Museum",url:"https://www.roots.gov.sg/places/places-landing/Places/museums/red-dot-design-museum",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:2005,label:"opens on Maxwell Road",source:{title:"Red Dot Design Museum",url:"https://www.roots.gov.sg/places/places-landing/Places/museums/red-dot-design-museum",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:2017,label:"moves to Marina Bay",source:{title:"Red Dot Design Museum",url:"https://www.roots.gov.sg/places/places-landing/Places/museums/red-dot-design-museum",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-reflections-bukit-chandu":{title:["Bukit Chandu,","where the Malay Regiment","held the hill"],subtitle:"Pepys Road · WWII interpretive centre",lead:"Reflections at Bukit Chandu is a World War Two interpretive centre in a hillside bungalow. It remembers the Battle of Pasir Panjang and the men of the Malay Regiment who fought in it.",more:["Bukit Chandu means “Opium Hill”. It is named after the Opium Packing Plant that once stood at the foot of the hill. The bungalow was built for the plant’s senior British staff. It looks like other black-and-white colonial bungalows, but has art-deco touches.","In February 1942, two days before Singapore fell, soldiers of the Malay Regiment were pushed back onto this hill. For 48 hours they fought, in the end hand to hand when their ammunition ran out. Lieutenant Adnan bin Saidi was among those captured and killed. The centre opened on 15 February 2002."],lookFor:["The sculpture of a Malay mortar crew","Art-deco touches on the black-and-white bungalow","The tree-top canopy walk to Kent Ridge Park"],sources:[{title:"The Building",url:"https://www.heritage.sg/reflectionsatbukitchandu/about-us/the-building",publisher:"Reflections at Bukit Chandu (National Heritage Board)",checkedAt:"2026-10-31"},{title:"Overview",url:"https://www.heritage.sg/reflectionsatbukitchandu/about-us/overview",publisher:"Reflections at Bukit Chandu (National Heritage Board)",checkedAt:"2026-10-31"},{title:"Packing Chandu",url:"https://www.heritage.sg/reflectionsatbukitchandu/whats-on/experiences/packing-chandu",publisher:"Reflections at Bukit Chandu (National Heritage Board)",checkedAt:"2026-10-31"},{title:"Reflections at Bukit Chandu",url:"https://en.wikipedia.org/wiki/Reflections_at_Bukit_Chandu",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"The battle for Opium Hill",seconds:95,captions:["Bukit Chandu means “Opium Hill” in Malay.","The bungalow housed British staff of an opium packing plant.","In February 1942 the Malay Regiment fought here for 48 hours.","Today the centre tells their story and the hill’s history."],poster:{src:"nearby/cards/reflections-bukit-chandu.webp",alt:"Bronze sculpture of Malay Regiment soldiers firing a mortar, in a garden at Bukit Chandu",credit:"Jpatokal 2005 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:BukitChandu_MalayRegiment.JPG"}},tiles:[{value:1942,label:"Battle of Pasir Panjang",source:{title:"Reflections at Bukit Chandu",url:"https://en.wikipedia.org/wiki/Reflections_at_Bukit_Chandu",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:48,label:"hours of fighting",source:{title:"Reflections at Bukit Chandu",url:"https://en.wikipedia.org/wiki/Reflections_at_Bukit_Chandu",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:2002,label:"centre opens",source:{title:"The Building",url:"https://www.heritage.sg/reflectionsatbukitchandu/about-us/the-building",publisher:"Reflections at Bukit Chandu (National Heritage Board)",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-republic-plaza":{title:["Republic Plaza,","280 metres","of granite and glass"],subtitle:"Raffles Place · office tower",lead:"Republic Plaza is a 66-storey office tower at Raffles Place, designed by Kisho Kurokawa. At 280 metres, it was one of Singapore's three tallest buildings when it was finished.",more:["The tower has an eight-sided plan. Its longer sides on the upper floors are turned 45 degrees from those at street level. The outside is polished granite and blue glass.","Building began in December 1991, and the first tower was done by December 1995. Parts were made in factories first, which saved time and money; this won the building a top FIABCI real estate prize in 1997. A 23-storey second tower stands on Malacca Street, and the complex opened officially on 25 January 1998."],lookFor:["The eight-sided tower, its top turned 45 degrees","Polished granite and blue glass panels","Republic Plaza II, 23 storeys, on Malacca Street"],sources:[{title:"Republic Plaza (Singapore)",url:"https://en.wikipedia.org/wiki/Republic_Plaza_(Singapore)",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"A tower that turns",seconds:90,captions:["Republic Plaza's main tower has 66 floors and rises 280 metres.","Japanese architect Kisho Kurokawa designed it; work began in 1991.","Its upper floors are turned 45 degrees from those at street level.","Look up at its polished granite and blue glass from Raffles Place."]},tiles:[{value:1991,label:"groundbreaking",source:{title:"Republic Plaza (Singapore)",url:"https://en.wikipedia.org/wiki/Republic_Plaza_(Singapore)",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:280,label:"metres tall",suffix:" m",source:{title:"Republic Plaza (Singapore)",url:"https://en.wikipedia.org/wiki/Republic_Plaza_(Singapore)",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:1998,label:"officially opened",source:{title:"Republic Plaza (Singapore)",url:"https://en.wikipedia.org/wiki/Republic_Plaza_(Singapore)",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-seroja":{title:["Seroja,","flavours of the","Malay Archipelago"],subtitle:"Duo Galleria · Malay Archipelago tasting menu, two MICHELIN stars",lead:"Seroja cooks the flavours of the Malay Archipelago. Its name is the Malay word for the lotus, and also honours Jalan Seroja in Klang, Malaysia, where chef Kevin Wong’s great-grandfather settled.",more:["Wong was born near Klang and worked in MICHELIN-starred kitchens in France, California and Singapore, including as head chef of Meta. He works with 16 farmers, craftsmen and artisans from across the archipelago.","In 2023 Seroja won its first MICHELIN star and became the first restaurant in Singapore with a MICHELIN Green Star, for sustainable cooking; Wong won the Young Chef Award. In 2026 it gained a second star."],lookFor:["The open kitchen","The 13-seat counter","Kampong Gelam and Bugis, a short walk away"],sources:[{title:"Press Room",url:"https://seroja.sg/story",publisher:"Seroja",checkedAt:"2026-10-31"},{title:"People",url:"https://seroja.sg/people",publisher:"Seroja",checkedAt:"2026-10-31"},{title:"New restaurant Seroja wins big at MICHELIN Guide Singapore 2023",url:"https://www.womensweekly.com.sg/food/new-restaurant-seroja-first-michelin-star-guide-singapore-2023",publisher:"Singapore Women's Weekly",checkedAt:"2026-10-31"},{title:"List of Michelin-starred restaurants in Singapore",url:"https://en.wikipedia.org/wiki/List_of_Michelin-starred_restaurants_in_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"Named after a lotus",seconds:90,captions:["Seroja is the Malay word for the lotus flower.","It also honours Jalan Seroja in Klang, Malaysia.","In 2023 it won a star and Singapore’s first Green Star.","In 2026 it gained a second MICHELIN star."],poster:{src:"nearby/cards/seroja.webp",alt:"The DUO towers at night above old shophouses at North Bridge Road and Arab Street; Seroja is in Duo Galleria (not the restaurant itself)",credit:"Xixian Wang 2017 · CC BY 3.0",url:"https://commons.wikimedia.org/wiki/File:Night_view_of_DUO_Singapore_from_junction_of_North_Bridge_Road_and_Arab_Street_20170831.jpg"}},tiles:[{value:2023,label:"first star and Green Star",source:{title:"Press Room",url:"https://seroja.sg/story",publisher:"Seroja",checkedAt:"2026-10-31"}},{value:2026,label:"two MICHELIN stars",source:{title:"Press Room",url:"https://seroja.sg/story",publisher:"Seroja",checkedAt:"2026-10-31"}},{value:13,label:"counter seats",source:{title:"Press Room",url:"https://seroja.sg/story",publisher:"Seroja",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-singapore-art-museum":{title:["Old St Joseph’s,","a school that became","an art museum"],subtitle:"Bras Basah Road · former school, Singapore Art Museum’s old home",lead:"This building on Bras Basah Road was St Joseph’s Institution, Singapore’s oldest Catholic boys’ school. From 1996 it was home to the Singapore Art Museum.",more:["The cornerstone was laid on 19 March 1855, St Joseph’s feast day, and the first block was finished in 1867. Father Charles Nain later added the two curved wings and the dome. A bronze statue of St Jean-Baptiste de La Salle with two children stands over the entrance.","The school moved to Malcolm Road in 1988, and the art museum opened here in 1996. It closed for redevelopment in 2019; it was later announced that SAM will stay at Tanjong Pagar Distripark and not return."],lookFor:["The bronze La Salle statue over the entrance","Two curved wings with arched verandahs","The central dome"],sources:[{title:"Former Saint Joseph's Institution",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/former-saint-josephs-institution",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"},{title:"Singapore Art Museum",url:"https://en.wikipedia.org/wiki/Singapore_Art_Museum",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"From classrooms to galleries",seconds:90,captions:["This was St Joseph’s Institution, a Catholic boys’ school.","Its cornerstone was laid on St Joseph’s Day, 1855.","From 1996 it was the Singapore Art Museum.","SAM now shows art at Tanjong Pagar Distripark instead."],poster:{src:"nearby/cards/singapore-art-museum.webp",alt:"The white former St Joseph’s Institution with its curved, arched wings and small central dome",credit:"ProjectManhattan 2013 · CC BY-SA 3.0",url:"https://commons.wikimedia.org/wiki/File:Singapore_Art_Museum_-_20131211.jpg"}},tiles:[{value:1855,label:"cornerstone laid",source:{title:"Former Saint Joseph's Institution",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/former-saint-josephs-institution",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:1867,label:"first block completed",source:{title:"Former Saint Joseph's Institution",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/former-saint-josephs-institution",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:1996,label:"art museum opens",source:{title:"Former Saint Joseph's Institution",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/former-saint-josephs-institution",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-singapore-chinese-cultural-centre":{title:["A home for","Singapore’s own","Chinese culture"],subtitle:"Straits Boulevard · cultural centre",lead:"The Singapore Chinese Cultural Centre was opened on 19 May 2017 by Prime Minister Lee Hsien Loong. It looks at Chinese culture as it developed in Singapore’s multi-racial society.",more:["The idea was first put forward in 2012, and ground was broken in 2014. Donors gave over $29 million, topped up by $15 million from the Cultural Matching Fund. The 11-storey building by DP Architects stands next to the Singapore Conference Hall.","Its permanent exhibition, SINGAPO人 (said “singapo-ren”), opened on 29 February 2020. The centre also holds exhibitions, shows, festivals, talks and workshops through the year."],lookFor:["The SINGAPO人 permanent exhibition","Chinese design touches on a modern façade","The Singapore Conference Hall next door"],sources:[{title:"About SCCC",url:"https://singaporeccc.org.sg/about-sccc/",publisher:"Singapore Chinese Cultural Centre",checkedAt:"2026-10-31"},{title:"Our Journey",url:"https://singaporeccc.org.sg/our-journey/",publisher:"Singapore Chinese Cultural Centre",checkedAt:"2026-10-31"},{title:"Singapore Chinese Cultural Centre",url:"https://www.dpa.com.sg/?p=3891",publisher:"DP Architects",checkedAt:"2026-10-31"}],clip:{title:"Chinese, the Singapore way",seconds:90,captions:["This centre is about Chinese culture as it grew up in Singapore.","The idea came in 2012; the building opened in May 2017.","Its 11-storey home has a 530-seat auditorium.","Inside, SINGAPO人 shows what makes the culture its own."],poster:{src:"nearby/cards/singapore-chinese-cultural-centre.webp",alt:"The centre’s glass-and-red-brick building among office towers on Straits Boulevard",credit:"Bjoertvedt 2018 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Singapore_-_Straits_Bvd_Singapore_Chinese_Cultural_Centre_IMG_9654.jpg"}},tiles:[{value:2017,label:"opened by the Prime Minister",source:{title:"Our Journey",url:"https://singaporeccc.org.sg/our-journey/",publisher:"Singapore Chinese Cultural Centre",checkedAt:"2026-10-31"}},{value:530,label:"seats in the auditorium",source:{title:"Singapore Chinese Cultural Centre",url:"https://www.dpa.com.sg/?p=3891",publisher:"DP Architects",checkedAt:"2026-10-31"}},{value:2020,label:"SINGAPO人 exhibition opens",source:{title:"Our Journey",url:"https://singaporeccc.org.sg/our-journey/",publisher:"Singapore Chinese Cultural Centre",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-singapore-city-gallery":{title:["Singapore City Gallery,","the city as a model"],subtitle:"Maxwell Road · urban planning gallery at the URA Centre",lead:"The Singapore City Gallery, in the URA Centre on Maxwell Road, shows how Singapore plans and builds its city. Entry is free.",more:["It opened on 27 January 1999 as the URA Gallery and was renamed in 2004. Its best-known exhibit is the Central Area Model of the city centre, made mostly of balsa wood and acrylic at a scale of 1:400.","Heads-up: the gallery is partly closed from 1 December 2026 to 30 April 2027 and fully closed from 1 May 2027. A refreshed gallery is expected in Q4 2027."],lookFor:["The Central Area Model of the city centre","The three-minute light show on the model","An exhibit where a brush of the hand shows old buildings"],sources:[{title:"Singapore City Gallery",url:"https://en.wikipedia.org/wiki/Singapore_City_Gallery",publisher:"Wikipedia",checkedAt:"2026-10-29"},{title:"Singapore City Gallery",url:"https://www.ura.gov.sg/get-involved/singapore-city-gallery/",publisher:"Urban Redevelopment Authority",checkedAt:"2026-10-29"},{title:"Visit Singapore City Gallery",url:"https://www.ura.gov.sg/get-involved/singapore-city-gallery/visit/",publisher:"Urban Redevelopment Authority",checkedAt:"2026-10-29"}],clip:{title:"The city in miniature",seconds:85,captions:["This free gallery shows how Singapore plans its land.","It opened in 1999 as the URA Gallery.","Its Central Area Model is 11 m by 10 m, at a scale of 1:400.","A three-minute light show plays over it every 20 minutes."],poster:{src:"nearby/cards/singapore-city-gallery.webp",alt:"Visitors looking down on the Central Area Model of Singapore’s city centre",credit:"Chainwit. 2025 · CC BY 4.0",url:"https://commons.wikimedia.org/wiki/File:Singapore_City_Gallery_%22Central_Area_Model%22_(2025)_-_img_01.jpg"}},tiles:[{value:1999,label:"opened as the URA Gallery",source:{title:"Singapore City Gallery",url:"https://en.wikipedia.org/wiki/Singapore_City_Gallery",publisher:"Wikipedia",checkedAt:"2026-10-29"}},{value:11,label:"long Central Area Model",suffix:" m",source:{title:"Singapore City Gallery",url:"https://en.wikipedia.org/wiki/Singapore_City_Gallery",publisher:"Wikipedia",checkedAt:"2026-10-29"}},{value:3,label:"minute light show",source:{title:"Singapore City Gallery",url:"https://www.ura.gov.sg/get-involved/singapore-city-gallery/",publisher:"Urban Redevelopment Authority",checkedAt:"2026-10-29"}}],reviewedAt:"2026-10-29"},"curated:sg-singapore-conference-hall":{title:["Singapore Conference Hall,","a modern hall","for a new nation"],subtitle:"Shenton Way · concert hall, home of the Singapore Chinese Orchestra",lead:"The Singapore Conference Hall and Trade Union House was opened by Prime Minister Lee Kuan Yew on 15 October 1965. It was built as the headquarters of the National Trades Union Congress (NTUC) and as a place for conferences and exhibitions.",more:["William Lim, Chan Voon Fee and Lim Chong Keat of the Malayan Architects Co-Partnership won the design competition, which had 16 entries. The modernist building has a butterfly roof, cantilevered terraces and sun-breakers of local hardwood.","In 1971 Commonwealth leaders met here, the first time the Commonwealth met outside London. NTUC moved out in 2000, and the Singapore Chinese Orchestra now uses the hall. It was the first post-colonial building to become a National Monument, in 2010."],lookFor:["The butterfly roof, sloping in to the middle","Hardwood sun-breakers along the front","Mosaic tiles with Malay mat patterns inside"],sources:[{title:"Former Singapore Conference Hall and Trade Union House (now Singapore Conference Hall)",url:"https://roots.gov.sg/places/places-landing/Places/national-monuments/former-singapore-conference-hall-and-trade-union-house-now-singapore-conference-hall",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-29"},{title:"Former Singapore Conference Hall and Trade Union House (now Singapore Conference Hall)",url:"https://www.ura.gov.sg/conservation/find-a-building/conservation-portal/062-schtuh/",publisher:"Urban Redevelopment Authority",checkedAt:"2026-10-29"}],clip:{title:"A hall for the unions",seconds:95,captions:["It was built for conferences and as the trade unions’ headquarters.","Its design won an open competition launched in 1961.","A school janitor laid the foundation stone in 1962.","Today the Singapore Chinese Orchestra plays here."],poster:{src:"nearby/cards/singapore-conference-hall.webp",alt:"Singapore Conference Hall from the road, with its sun-breaker screen above the entrance",credit:"ZKang123 2024 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Singapore_Conference_Hall_exterior_20240818_114158.jpg"}},tiles:[{value:1961,label:"design competition",source:{title:"Former Singapore Conference Hall and Trade Union House (now Singapore Conference Hall)",url:"https://roots.gov.sg/places/places-landing/Places/national-monuments/former-singapore-conference-hall-and-trade-union-house-now-singapore-conference-hall",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-29"}},{value:1965,label:"officially opened",source:{title:"Former Singapore Conference Hall and Trade Union House (now Singapore Conference Hall)",url:"https://roots.gov.sg/places/places-landing/Places/national-monuments/former-singapore-conference-hall-and-trade-union-house-now-singapore-conference-hall",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-29"}},{value:1e3,label:"seats in the auditorium",grouped:!0,source:{title:"Former Singapore Conference Hall and Trade Union House (now Singapore Conference Hall)",url:"https://roots.gov.sg/places/places-landing/Places/national-monuments/former-singapore-conference-hall-and-trade-union-house-now-singapore-conference-hall",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-29"}}],thenNow:{then:{src:"nearby/cards/singapore-conference-hall-then.webp",alt:"The new Conference Hall in 1967: white sun-breakers over the front and the Dewan Persidangan Singapura sign over the door",credit:"Sherwin John Carlquist 1967 · CC BY 4.0",url:"https://commons.wikimedia.org/wiki/File:(Singapore_Conference_Hall_in_Singapore)_-_DPLA_-_59ee0f6e4fcb2fe2056f43ff5f19e82d.jpg"},now:{src:"nearby/cards/singapore-conference-hall-now.webp",alt:"The hall in 2024 from the left, behind trees, with the same sign over the entrance and a newer glass block above",credit:"ZKang123 2024 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Singapore_Conference_Hall_exterior_20240727_171001.jpg"},thenLabel:"1967",nowLabel:"2024",captions:{then:{lead:"1967.",text:" Two years old: white sun-breakers over the front, the name above the door."},mid:{lead:"Same front, 57 years apart.",text:" A S$22 million renovation made it the orchestra’s home."},now:{lead:"2024.",text:" Trees, a newer glass block, and the same name over the entrance."}}},reviewedAt:"2026-10-29"},"curated:sg-singapore-cricket-club":{title:["Singapore Cricket Club,","on the Padang","since 1852"],subtitle:"Connaught Drive · sports and social club",lead:"The Singapore Cricket Club was set up in 1852. Its clubhouse stands at the south end of the Padang, the open green in the Civic District.",more:["The club has had three clubhouses on the Padang: the first in the 1860s, the second in 1877, and the third in 1884. The 1884 building forms the core of the clubhouse you see now.","Cricket matches are played at the Padang's south-western end. The club also hosts the yearly Singapore Cricket Club International Rugby Sevens, and the Padang is used for football and hockey too."],lookFor:["The clubhouse at the Padang's south end","Cricket matches on the Padang's south-western end","The Recreation Club at the far end of the field"],sources:[{title:"Singapore Cricket Club",url:"https://en.wikipedia.org/wiki/Singapore_Cricket_Club",publisher:"Wikipedia",checkedAt:"2026-10-31"},{title:"The Padang",url:"https://www.roots.gov.sg/en/places/places-landing/Places/national-monuments/the-padang",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}],clip:{title:"Cricket by the Padang",seconds:90,captions:["This club at the south end of the Padang began in 1852.","The core of today's clubhouse was built in 1884.","It is Singapore's second-oldest club, with over 3,000 members.","Cricket, rugby and football are still played on the Padang."],poster:{src:"nearby/cards/singapore-cricket-club.webp",alt:"The white Singapore Cricket Club clubhouse with its red roof on Connaught Drive, the National Gallery dome behind",credit:"Orderinchaos 2016 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Singapore_Cricket_Club_building_2016.jpg"}},tiles:[{value:1852,label:"club founded",source:{title:"Singapore Cricket Club",url:"https://en.wikipedia.org/wiki/Singapore_Cricket_Club",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:1884,label:"clubhouse core built",source:{title:"Singapore Cricket Club",url:"https://en.wikipedia.org/wiki/Singapore_Cricket_Club",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:3e3,label:"members",suffix:"+",grouped:!0,source:{title:"Singapore Cricket Club",url:"https://en.wikipedia.org/wiki/Singapore_Cricket_Club",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-singapore-flyer":{title:["Singapore Flyer,","a wheel 165 metres high"],subtitle:"Marina Centre · observation wheel",lead:"The Singapore Flyer is an observation wheel 165 metres high. When it opened in 2008, it was the tallest Ferris wheel in the world.",more:["The first public rides were on Valentine's Day, 14 February 2008, and the Prime Minister opened the wheel officially on 15 April. In 2014 the High Roller in Las Vegas took the record, 2.6 metres taller.","Each of the 28 air-conditioned capsules holds up to 28 people. The capsules hang outside the rim, and one full turn takes about 32 minutes."],lookFor:["Capsules mounted on the outside of the rim","The three-storey terminal building below","Marina Bay and the city skyline from the top"],sources:[{title:"Singapore Flyer",url:"https://en.wikipedia.org/wiki/Singapore_Flyer",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"Once the tallest wheel",seconds:90,captions:["The Singapore Flyer is a giant observation wheel 165 metres high.","When it opened in 2008, it was the world's tallest Ferris wheel.","In 2014 the High Roller in Las Vegas beat it by 2.6 metres.","Its 28 cooled capsules take about 32 minutes to go round."]},tiles:[{value:2008,label:"officially opened",source:{title:"Singapore Flyer",url:"https://en.wikipedia.org/wiki/Singapore_Flyer",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:165,label:"metres high",suffix:" m",source:{title:"Singapore Flyer",url:"https://en.wikipedia.org/wiki/Singapore_Flyer",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:28,label:"capsules",source:{title:"Singapore Flyer",url:"https://en.wikipedia.org/wiki/Singapore_Flyer",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-singapore-recreation-club":{title:["Singapore Recreation Club,","at the north end","of the Padang"],subtitle:"Connaught Drive · sports and social club",lead:"The Singapore Recreation Club was founded in 1883 by thirty Eurasian men. It stands at the north end of the Padang, with the Cricket Club at the other end.",more:["The club first met in a building on Waterloo Street and put up a pavilion on the Padang in 1884. A proper clubhouse opened in 1905. Its colours, chosen in 1886, are navy blue for sportsmanship and red for the brotherhood of man in sports.","Ordinary membership opened to people of all communities in 1955, and women were admitted in 1956. In 1963 full membership was opened to all. The present clubhouse, which cost $65 million, opened on 28 June 1997."],lookFor:["The clubhouse at the Padang's north end","The Cricket Club at the far end of the field","Navy blue and red, the club's colours"],sources:[{title:"Singapore Recreation Club",url:"https://en.wikipedia.org/wiki/Singapore_Recreation_Club",publisher:"Wikipedia",checkedAt:"2026-10-31"},{title:"The Padang",url:"https://www.roots.gov.sg/en/places/places-landing/Places/national-monuments/the-padang",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}],clip:{title:"A club for all",seconds:90,captions:["Thirty Eurasian men founded this club in 1883.","Its first pavilion went up on the Padang in 1884.","In 1955 it opened to all communities; women joined from 1956.","Today's clubhouse opened in 1997, facing the Padang."],poster:{src:"nearby/cards/singapore-recreation-club.webp",alt:"The Singapore Recreation Club clubhouse with green glass, tall columns and a pointed gable",credit:"Actuall7 2026 · CC BY 4.0",url:"https://commons.wikimedia.org/wiki/File:Singapore_Recreation_Club,_2026.jpg"}},tiles:[{value:1883,label:"club founded",source:{title:"Singapore Recreation Club",url:"https://en.wikipedia.org/wiki/Singapore_Recreation_Club",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:1905,label:"first clubhouse opens",source:{title:"Singapore Recreation Club",url:"https://en.wikipedia.org/wiki/Singapore_Recreation_Club",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:1997,label:"new clubhouse opens",source:{title:"Singapore Recreation Club",url:"https://en.wikipedia.org/wiki/Singapore_Recreation_Club",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-skyville-dawson":{title:["SkyVille @ Dawson,","villages stacked","in the sky"],subtitle:"Dawson Road · public housing by WOHA",lead:"SkyVille @ Dawson is a public housing project built for HDB and designed by WOHA. Its 960 homes are grouped into “Sky Villages” of 80 homes each.",more:["Each Sky Village shares a naturally ventilated community terrace and sky garden. Each of the three linked towers holds four Sky Villages, one on top of another. Despite the 960 homes, there is not one internal corridor.","Openings on all sides let in light and air. In the park below, large rain trees were kept when the old Margaret Drive was closed. In 2016 the project was named a Design of the Year in the President’s Design Award."],lookFor:["Sky gardens stacked every 11 storeys","Old rain trees in the park at the foot of the towers","Sunshades on the walls and overhangs over the windows"],sources:[{title:"SkyVille @ Dawson",url:"https://woha.net/project/skyville-dawson/",publisher:"WOHA",checkedAt:"2026-10-31"},{title:"SkyVille @ Dawson – Design of the Year 2016",url:"https://pda.designsingapore.org/award-recipients/2016/skyville-at-dawson/",publisher:"President's Design Award (DesignSingapore Council)",checkedAt:"2026-10-31"}],clip:{title:"Villages in the sky",seconds:90,captions:["SkyVille @ Dawson is HDB public housing designed by WOHA.","HDB gave WOHA the project in 2008, on a tight public budget.","Every 80 homes share a breezy sky terrace and garden.","There are 960 homes, but not one internal corridor."]},tiles:[{value:960,label:"homes",grouped:!0,source:{title:"SkyVille @ Dawson",url:"https://woha.net/project/skyville-dawson/",publisher:"WOHA",checkedAt:"2026-10-31"}},{value:80,label:"homes in each Sky Village",source:{title:"SkyVille @ Dawson",url:"https://woha.net/project/skyville-dawson/",publisher:"WOHA",checkedAt:"2026-10-31"}},{value:2016,label:"Design of the Year",source:{title:"SkyVille @ Dawson – Design of the Year 2016",url:"https://pda.designsingapore.org/award-recipients/2016/skyville-at-dawson/",publisher:"President's Design Award (DesignSingapore Council)",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-soka-youth-centre":{title:["Soka Youth Centre,","a centre run","by young people"],subtitle:"Pasir Panjang Road · Soka Gakkai youth centre",lead:"The Soka Youth Centre is a four-storey building on Pasir Panjang Road, run by Soka Gakkai Singapore’s youth division. It has a conference room, a prayer hall and an auditorium.",more:["It was first the Pasir Panjang Soka Centre, officially opened on 16 March 1987. It was turned into the Soka Youth Centre on 7 April 2001.","Its programmes aim to build leadership among young people and to encourage them to volunteer and serve the community."],sources:[{title:"Soka Youth Centre",url:"https://sokasingapore.org/find-us/activity-centres/soka-youth-centre",publisher:"Soka Gakkai Singapore",checkedAt:"2026-10-31"}],clip:{title:"A centre run by youth",seconds:80,captions:["This four-storey centre belongs to Soka Gakkai Singapore.","It opened in 1987 as the Pasir Panjang Soka Centre.","On 7 April 2001 it became the Soka Youth Centre.","Its youth division runs the prayer hall and auditorium."]},tiles:[{value:1987,label:"Pasir Panjang Soka Centre",source:{title:"Soka Youth Centre",url:"https://sokasingapore.org/find-us/activity-centres/soka-youth-centre",publisher:"Soka Gakkai Singapore",checkedAt:"2026-10-31"}},{value:2001,label:"becomes youth centre",source:{title:"Soka Youth Centre",url:"https://sokasingapore.org/find-us/activity-centres/soka-youth-centre",publisher:"Soka Gakkai Singapore",checkedAt:"2026-10-31"}},{value:4,label:"storeys",source:{title:"Soka Youth Centre",url:"https://sokasingapore.org/find-us/activity-centres/soka-youth-centre",publisher:"Soka Gakkai Singapore",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-solaris":{title:["Solaris,","a garden ramp","spiralling up"],subtitle:"Fusionopolis Walk · eco-office building by Ken Yeang",lead:"Solaris is an office building at one-north designed by the “green” architect Ken Yeang. A planted ramp about 1.5 km long winds around the outside, from the street to the roof gardens.",more:["The ramp is at least 3 metres wide. It joins one-north Park across the street with a chain of roof gardens and sky terraces, so plants and small animals can move through the building. A diagonal “solar shaft” lets daylight deep inside.","At the north-east corner an “Eco-cell” brings plants, light and fresh air down into the car park. The building uses over 36% less energy than similar local buildings and was awarded Green Mark Platinum in 2009."],lookFor:["The planted ramp spiralling up the outside","The Eco-cell at the north-east corner","Sun-shade louvres, over 10 km long in all"],sources:[{title:"Solaris, Singapore",url:"https://www.e-architect.com/singapore/solaris-singapore",publisher:"e-architect",checkedAt:"2026-10-31"},{title:"Fusionopolis",url:"https://en.wikipedia.org/wiki/Fusionopolis",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"A 1.5 km garden ramp",seconds:85,captions:["Solaris is a green office building designed by Ken Yeang.","A planted ramp 1.5 km long winds up its outside walls.","It links one-north Park with gardens on the roof.","It uses over 36% less energy than similar local buildings."],poster:{src:"nearby/cards/solaris.webp",alt:"Solaris, a rounded white office building with plants growing along a ramp that wraps its floors",credit:"UbiSing 2012 · CC BY-SA 3.0",url:"https://commons.wikimedia.org/wiki/File:Solaris_@_One-North.JPG"}},tiles:[{value:2010,label:"completed",source:{title:"Fusionopolis",url:"https://en.wikipedia.org/wiki/Fusionopolis",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:1.5,label:"planted ramp",suffix:" km",source:{title:"Solaris, Singapore",url:"https://www.e-architect.com/singapore/solaris-singapore",publisher:"e-architect",checkedAt:"2026-10-31"}},{value:36,label:"less energy (over)",suffix:"%",source:{title:"Solaris, Singapore",url:"https://www.e-architect.com/singapore/solaris-singapore",publisher:"e-architect",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-song-fa-bak-kut-teh-new-bridge-road":{title:["Song Fa,","bak kut teh from","a 1969 pushcart"],subtitle:"New Bridge Road · bak kut teh restaurant",lead:"Song Fa Bak Kut Teh began in 1969, when Yeo Eng Song served bak kut teh from a pushcart on Johor Road. In 1975 the stall moved into a coffeeshop on Victoria Street.",more:["Its soup is Teochew style, clear and peppery, with pork ribs simmered with garlic and Sarawak white pepper. The second generation, Diana Yeo, Yeo Hart Pong and Yeo Zhi Yong, grew it into a chain of 13 outlets by 2021.","The first restaurant-style outlet opened here at 11 New Bridge Road, across from The Central at Clarke Quay. In 2026 this branch’s MICHELIN Bib Gourmand marked 10 years of recognition."],lookFor:["The pushcart in the brand’s logo","Clear, peppery soup with pork ribs","The Central mall across the road"],sources:[{title:"About Us",url:"https://songfa.com.sg/pages/about-us",publisher:"Song Fa Bak Kut Teh",checkedAt:"2026-10-29"},{title:"Song Fa Bak Kut Teh",url:"https://vulcanpost.com/731950/song-fa-bak-kut-teh-singapore/",publisher:"Vulcan Post",checkedAt:"2026-10-29"}],clip:{title:"From pushcart to shophouse",seconds:90,captions:["Song Fa simmers pork ribs with garlic and white pepper.","Yeo Eng Song began with a pushcart on Johor Road in 1969.","In 1975 the stall moved into a coffeeshop on Victoria Street.","This branch won its tenth year of Bib Gourmand in 2026."],poster:{src:"nearby/cards/sg-song-fa-bak-kut-teh-new-bridge-road.webp",alt:"The white corner shophouse of Song Fa Bak Kut Teh on New Bridge Road, with its sign",credit:"Chainwit. 2023 · CC BY 4.0",url:"https://commons.wikimedia.org/wiki/File:Song_Fa_Bak_Kut_Teh,_New_Bridge_Rd,_Singapore_(2023)_01.jpg"}},tiles:[{value:1969,label:"pushcart on Johor Road",source:{title:"About Us",url:"https://songfa.com.sg/pages/about-us",publisher:"Song Fa Bak Kut Teh",checkedAt:"2026-10-29"}},{value:1975,label:"coffeeshop on Victoria St",source:{title:"Song Fa Bak Kut Teh",url:"https://vulcanpost.com/731950/song-fa-bak-kut-teh-singapore/",publisher:"Vulcan Post",checkedAt:"2026-10-29"}},{value:10,label:"Bib Gourmand years (2026)",source:{title:"About Us",url:"https://songfa.com.sg/pages/about-us",publisher:"Song Fa Bak Kut Teh",checkedAt:"2026-10-29"}}],reviewedAt:"2026-10-29"},"curated:sg-south-beach":{title:["South Beach,","old army blocks","under a wave"],subtitle:"Beach Road · offices, hotel and homes",lead:"South Beach is a mixed development of offices, a JW Marriott hotel, homes and shops, designed by Foster + Partners and completed in 2016. Its two new towers are 45 and 42 storeys tall.",more:["The site was the Beach Road army camp, where the first National Service enlistment took place in 1967. Three 1930s army blocks and the 1952 former NCO Club were given conservation status in 2002 and restored.","A large canopy, an 'environmental filter', rises and dips like huge waves over the open spaces and links the old buildings to the towers. Rainwater from the towers and canopy is collected in a tank underground."],lookFor:["The wave-like canopy between the towers","The restored 1930s army blocks","The former NCO Club of 1952"],sources:[{title:"South Beach (Singapore)",url:"https://en.wikipedia.org/wiki/South_Beach_(Singapore)",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"Army camp to towers",seconds:92,captions:["Beach Road camp saw the first National Service intake in 1967.","Three 1930s army blocks and a 1952 club were kept.","Foster + Partners added two towers, done in 2016.","A wavy canopy shades the space between them."]},tiles:[{value:1930,label:"army blocks built",suffix:"s",source:{title:"South Beach (Singapore)",url:"https://en.wikipedia.org/wiki/South_Beach_(Singapore)",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:1967,label:"first NS enlistment here",source:{title:"South Beach (Singapore)",url:"https://en.wikipedia.org/wiki/South_Beach_(Singapore)",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:2016,label:"completed",source:{title:"South Beach (Singapore)",url:"https://en.wikipedia.org/wiki/South_Beach_(Singapore)",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-sri-layan-sithi-vinayagar-temple":{title:["Sri Layan Sithi Vinayagar,","a temple for Ganesha"],subtitle:"Keong Saik Road · Hindu temple",lead:"Sri Layan Sithi Vinayagar Temple stands at the corner of Keong Saik Road and Kreta Ayer Road. It is dedicated to Vinayagar, also called Ganesha, the elephant-headed god.",more:["The first temple was a small shrine near the mortuary of Singapore General Hospital, used by hospital and prison staff. In 1920 the government took the land to expand the hospital. With the money, the Nattukottai Chettiars, a money-lending community from Tamil Nadu, built this temple in 1925.","The old Vinayagar statue was placed in front of the new black-stone statue in the sanctum, and a third statue was later given by a trustee. A five-storey gopuram, or gateway tower, was added in a renovation consecrated in December 2007."],lookFor:["The five-tier gopuram with painted figures","A Ganesha sculpture on the front gate","Three Vinayagar statues in the sanctum"],sources:[{title:"Sri Layan Sithi Vinayagar Temple",url:"https://www.roots.gov.sg/places/places-landing/Places/surveyed-sites/Sri-Layan-Sithi-Vinayagar-Temple",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"},{title:"Sri Layan Sithi Vinayagar Temple (73 Keong Saik Road)",url:"https://www.ura.gov.sg/conservation/find-a-building/conservation-portal/bkps-00180/",publisher:"Urban Redevelopment Authority (URA)",checkedAt:"2026-10-31"},{title:"Sri Layan Sithi Vinayagar Temple",url:"https://sttemple.com/about-lsv",publisher:"Chettiars' Temple Society (ST Temple)",checkedAt:"2026-10-31"}],clip:{title:"Ganesha on Keong Saik Road",seconds:90,captions:["This temple is for Vinayagar, the elephant-headed god Ganesha.","Chettiars built it here in 1925 after losing their first site.","Its name comes from the old Sepoy Lines, near its first home.","Before Thaipusam, a silver chariot procession comes here."]},tiles:[{value:1920,label:"first site taken over",source:{title:"Sri Layan Sithi Vinayagar Temple",url:"https://www.roots.gov.sg/places/places-landing/Places/surveyed-sites/Sri-Layan-Sithi-Vinayagar-Temple",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:1925,label:"new temple built",source:{title:"Sri Layan Sithi Vinayagar Temple",url:"https://www.roots.gov.sg/places/places-landing/Places/surveyed-sites/Sri-Layan-Sithi-Vinayagar-Temple",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:2007,label:"five-tier gopuram",source:{title:"Sri Layan Sithi Vinayagar Temple",url:"https://sttemple.com/about-lsv",publisher:"Chettiars' Temple Society (ST Temple)",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-sri-thendayuthapani":{title:["Chettiars’ Temple,","Murugan’s home","on Tank Road"],subtitle:"Tank Road · Hindu temple",lead:"Sri Thendayuthapani Temple, known as the Chettiars’ Temple, is dedicated to Lord Murugan. The Chettiar community built it on Tank Road, and a stone at the entrance gives the date 4 April 1859.",more:["Before 1859, Chettiars prayed to a Vel, a spear that stands for Murugan, under a pipal tree beside a water tank. The temple was rebuilt and consecrated on 24 November 1983, with a 75-foot entrance tower. It became Singapore’s 67th national monument on 20 October 2014.","On Thaipusam, devotees walk from Sri Srinivasa Perumal Temple on Serangoon Road to this temple, some carrying kavadi or milk pots, to thank Murugan."],lookFor:["The 75-foot Raja Gopuram over the entrance","The 1859 date stone at the entrance","The temple library, with books over 120 years"],sources:[{title:"About STT",url:"https://sttemple.com/about-stt",publisher:"Sri Thendayuthapani Temple (Chettiars’ Temple Society)",checkedAt:"2026-10-31"},{title:"Sri Thendayuthapani Temple",url:"https://en.wikipedia.org/wiki/Sri_Thendayuthapani_Temple",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"A spear under a tree",seconds:90,captions:["Chettiar traders first prayed to a spear under a tree here.","The temple was built on 4 April 1859, says its entrance stone.","A 75-foot gopuram went up when it was rebuilt in 1983.","At Thaipusam, devotees walk here carrying kavadi."],poster:{src:"nearby/cards/sri-thendayuthapani.webp",alt:"The temple’s tall entrance tower covered in brightly painted figures of gods",credit:"Shiny Things 2009 · CC BY 2.0",url:"https://commons.wikimedia.org/wiki/File:SriThendayuthapaniTemple-Singapore-gopuram-20091220.jpg"}},tiles:[{value:1859,label:"temple built",source:{title:"About STT",url:"https://sttemple.com/about-stt",publisher:"Sri Thendayuthapani Temple (Chettiars’ Temple Society)",checkedAt:"2026-10-31"}},{value:75,label:"foot entrance tower",grouped:!0,source:{title:"About STT",url:"https://sttemple.com/about-stt",publisher:"Sri Thendayuthapani Temple (Chettiars’ Temple Society)",checkedAt:"2026-10-31"}},{value:2014,label:"national monument",source:{title:"About STT",url:"https://sttemple.com/about-stt",publisher:"Sri Thendayuthapani Temple (Chettiars’ Temple Society)",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-sri-veeramakaliamman-temple":{title:["Sri Veeramakaliamman,","Kali’s temple","on Serangoon Road"],subtitle:"Serangoon Road · Hindu temple",lead:"Sri Veeramakaliamman Temple is Singapore’s first temple to the goddess Kali, the ‘Destroyer of Evil’. Early Indian settlers turned to her for safety in a new land.",more:["It was first called Soonambu Kambam Kovil, the ‘temple at the village of lime’, after the lime kilns nearby. Tamil workers from the lime pits may have set up a shrine here as early as 1855, and Bengali labourers built a temple in 1881.","In 1908 municipal labourers took over and restored it, bringing a statue of Kali from South India. During the Japanese Occupation the temple sheltered over 20 homeless people each night and gave them food."],lookFor:["Images of Kali inside the temple","Parvati with her sons Ganesha and Murugan","Its South Indian Tamil temple style"],sources:[{title:"Sri Veeramakaliamman Temple",url:"https://www.roots.gov.sg/places/places-landing/Places/landmarks/little-india-heritage-trail-walk-of-faiths/sri-veeramakaliamman-temple",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"},{title:"Sri Veeramakaliamman Temple",url:"https://en.wikipedia.org/wiki/Sri_Veeramakaliamman_Temple",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"Temple of the lime village",seconds:90,captions:["This is Singapore’s first temple to the goddess Kali.","Lime-pit workers set up a shrine here as early as 1855.","Bengali labourers built a temple in 1881.","In the war it sheltered over 20 homeless people each night."],poster:{src:"nearby/cards/sri-veeramakaliamman-temple.webp",alt:"The temple’s colourful tower and red-and-white walls on Serangoon Road, with people outside",credit:"Bahnfrend 2023 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Sri_Veeramakaliamman_Temple,_2023_(02).jpg"}},tiles:[{value:1855,label:"shrine (as early as)",source:{title:"Sri Veeramakaliamman Temple",url:"https://www.roots.gov.sg/places/places-landing/Places/landmarks/little-india-heritage-trail-walk-of-faiths/sri-veeramakaliamman-temple",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:1881,label:"temple built",source:{title:"Sri Veeramakaliamman Temple",url:"https://www.roots.gov.sg/places/places-landing/Places/landmarks/little-india-heritage-trail-walk-of-faiths/sri-veeramakaliamman-temple",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:1908,label:"restored, new main hall",source:{title:"Sri Veeramakaliamman Temple",url:"https://www.roots.gov.sg/places/places-landing/Places/landmarks/little-india-heritage-trail-walk-of-faiths/sri-veeramakaliamman-temple",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-st-andrew-s-cathedral":{title:["St Andrew's Cathedral,","walls of shell lime","and egg white"],subtitle:"St Andrew's Road · Anglican cathedral",lead:"St Andrew's Cathedral is Singapore's oldest surviving Anglican place of worship and the seat of the Anglican bishop. The Neo-Gothic church you see was finished in 1861.",more:["The first church, designed by George D. Coleman, was completed in 1837. A spire was added later without a lightning conductor, and lightning struck it in 1845 and 1849. By 1852 the church was unsafe.","Lieutenant-Colonel Ronald MacPherson designed a new church in the Neo-Gothic style, simple enough for Indian convict labourers to build. It was completed in 1861 and became a cathedral in 1870. Its walls are covered in Madras chunam, a plaster of shell lime, egg whites, coarse sugar and coconut-husk water, polished until it shines.","In 1942 the nave was used as a hospital for the wounded. Today services are held in many languages, including English, Mandarin, Tagalog and Burmese."],lookFor:["A cross made of nails from Coventry Cathedral","Stained-glass windows for Raffles and Crawfurd","The carriage porch under the steeple"],sources:[{title:"Saint Andrew's Cathedral",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/saint-andrews-cathedral",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}],clip:{title:"Built twice",seconds:100,captions:["This is Singapore's oldest surviving Anglican place of worship.","The first church here was hit by lightning in 1845 and 1849.","Indian convicts built the new church, finished in 1861.","Its walls shine with Madras chunam: shell lime, egg white and sugar."]},tiles:[{value:1837,label:"first church completed",source:{title:"Saint Andrew's Cathedral",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/saint-andrews-cathedral",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:1861,label:"new church completed",source:{title:"Saint Andrew's Cathedral",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/saint-andrews-cathedral",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:1870,label:"becomes a cathedral",source:{title:"Saint Andrew's Cathedral",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/saint-andrews-cathedral",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}}],thenNow:{then:{src:"nearby/cards/st-andrew-s-cathedral-then.webp",alt:"Colour print of the cathedral and its dark spire across the Padang, with a statue of Raffles on the left",credit:"Photoglob Co. 1890 · public domain",url:"https://commons.wikimedia.org/wiki/File:Singapore._St._Andrew%27s_Cathedral_%26_Raffles_Monument_LCCN2017657643.jpg"},now:{src:"nearby/cards/st-andrew-s-cathedral-now.webp",alt:"The white cathedral and spire across the Padang lawn, with trees and new buildings behind",credit:"Dietmar Rabich 2019 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Singapore_(SG),_St_Andrew%27s_Cathedral_--_2019_--_4499.jpg"},thenLabel:"1890",nowLabel:"2019",captions:{then:{lead:"1890.",text:" The cathedral across the Padang, with Raffles’ statue in front."},mid:{lead:"Same spire, same lawn.",text:" The statue has gone; the church still stands."},now:{lead:"2019.",text:" White walls and spire, with new towers behind."}}},reviewedAt:"2026-10-29"},"curated:sg-st-joseph-s-church":{title:["St Joseph’s Church,","the Portuguese Mission’s","Gothic church"],subtitle:"Victoria Street · Catholic church",lead:"St Joseph’s Church on Victoria Street was the headquarters of the Portuguese Mission in Singapore. A first church was built here in 1853; the present Neo-Gothic church was blessed on 30 June 1912.",more:["Architect David McLeod Craik chose a Neo-Gothic design with pointed lancet arches and an eight-sided belfry. In 1950 blue-and-white Portuguese tiles, called azulejo, were added to the front to mark a visit of the Pilgrim Statue of Our Lady of Fatima.","The church has one of Singapore’s largest collections of religious stained glass, made by the Belgian Jules Dobbelaere. The Portuguese Mission was dissolved in 1999, and Catholics of all races worship here today."],lookFor:["Blue-and-white azulejo tiles on the front","The St Catherine window with a sailing boat","An eight-sided belfry with a dome"],sources:[{title:"Saint Joseph's Church",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/st-josephs-church",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"},{title:"About",url:"https://sjcvs.org.sg/about/",publisher:"St Joseph's Church (Victoria Street)",checkedAt:"2026-10-31"}],clip:{title:"Blue-and-white tiles",seconds:90,captions:["This was the home church of the Portuguese Mission.","A first church of St Joseph stood here from 1853.","Today’s Neo-Gothic church was blessed on 30 June 1912.","Blue-and-white Portuguese tiles were added in 1950."],poster:{src:"nearby/cards/st-joseph-s-church.webp",alt:"St Joseph’s Church on Victoria Street, white with a domed belfry, behind its name sign",credit:"Gnoeee 2023 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:St_Joseph%27s_Church_Victoria_street_Singapore.jpg"}},tiles:[{value:1853,label:"first church completed",source:{title:"Saint Joseph's Church",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/st-josephs-church",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:1912,label:"today’s church blessed",source:{title:"Saint Joseph's Church",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/st-josephs-church",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:1950,label:"azulejo tiles added",source:{title:"Saint Joseph's Church",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/st-josephs-church",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-sultan-mosque":{title:["Sultan Mosque,","golden domes","of Kampong Glam"],subtitle:"Muscat Street · mosque",lead:"Sultan Mosque was the royal mosque of the Sultan of Johor. In 1824 an agreement with the British East India Company set land aside for it near Istana Kampong Glam.",more:["The first mosque was a one-storey brick building. By 1924 it needed repair, and Denis Santry of Swan & Maclaren designed a larger one. Muslims from many communities gave money, and the new mosque was finished by 26 February 1932.","Two golden onion-shaped domes stand at each end of the prayer hall. Round the base of each is a belt of glass bottles, given by poor people as their gift to the building. The start of Ramadan is announced here every year."],lookFor:["Glass-bottle bands at the base of the domes","Arabesque mouldings on the front façade","Ramadan bazaar stalls during the fasting month"],sources:[{title:"Sultan Mosque",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/sultan-mosque",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"},{title:"Sultan Mosque",url:"https://en.wikipedia.org/wiki/Sultan_Mosque",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"Bottles under the domes",seconds:95,captions:["This was once the royal mosque of the Sultan of Johor.","Land for it was set aside in an agreement made in 1824.","A belt of glass bottles, given by the poor, rings each dome.","Its prayer hall holds up to 5,000 people."]},tiles:[{value:1824,label:"land set aside for a mosque",source:{title:"Sultan Mosque",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/sultan-mosque",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:1932,label:"today’s mosque completed",source:{title:"Sultan Mosque",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/sultan-mosque",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:5e3,label:"worshippers in the hall",grouped:!0,source:{title:"Sultan Mosque",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/sultan-mosque",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-summer-pavilion":{title:["Summer Pavilion,","Cantonese at","the Ritz-Carlton"],subtitle:"Raffles Avenue · Cantonese, one MICHELIN star",lead:"Summer Pavilion is the Cantonese restaurant of The Ritz-Carlton, Millenia Singapore. It won a star in the first MICHELIN Guide Singapore in 2016 and has kept it ever since.",more:["Chef Cheung Siu Kong has worked here since 2003 and became Chinese Executive Chef in 2014. A renovation in late 2015 gave the restaurant a modern look and six private dining rooms.","The hotel opened in 1996. It holds about 4,200 modern artworks, including pieces by Frank Stella, Andy Warhol and Dale Chihuly."],lookFor:["Art from the hotel’s collection of about 4,200 works","Pieces by Warhol, Stella and Chihuly"],sources:[{title:"Summer Pavilion at The Ritz-Carlton, Millenia Singapore awarded its first Michelin star",url:"https://www.journaldespalaces.com/en/news-48214-Summer-Pavilion-at-The-Ritz-Carlton-Millenia-Singapore-Awarded-Its-First-Michelin-Star.html",publisher:"Le Journal des Palaces (hotel press release)",checkedAt:"2026-10-31"},{title:"The Ritz-Carlton Millenia Singapore",url:"https://en.wikipedia.org/wiki/The_Ritz-Carlton_Millenia_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"},{title:"List of Michelin-starred restaurants in Singapore",url:"https://en.wikipedia.org/wiki/List_of_Michelin-starred_restaurants_in_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"A star from the first guide",seconds:90,captions:["Summer Pavilion is the Ritz-Carlton, Millenia’s Cantonese room.","Chef Cheung Siu Kong has cooked here since 2003.","In 2016 it won a star in Singapore’s first MICHELIN Guide.","It has kept one star in every Singapore guide since."]},tiles:[{value:1996,label:"hotel opens",source:{title:"The Ritz-Carlton Millenia Singapore",url:"https://en.wikipedia.org/wiki/The_Ritz-Carlton_Millenia_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:2003,label:"Chef Cheung joins",source:{title:"Summer Pavilion at The Ritz-Carlton, Millenia Singapore awarded its first Michelin star",url:"https://www.journaldespalaces.com/en/news-48214-Summer-Pavilion-at-The-Ritz-Carlton-Millenia-Singapore-Awarded-Its-First-Michelin-Star.html",publisher:"Le Journal des Palaces (hotel press release)",checkedAt:"2026-10-31"}},{value:2016,label:"first MICHELIN star",source:{title:"Summer Pavilion at The Ritz-Carlton, Millenia Singapore awarded its first Michelin star",url:"https://www.journaldespalaces.com/en/news-48214-Summer-Pavilion-at-The-Ritz-Carlton-Millenia-Singapore-Awarded-Its-First-Michelin-Star.html",publisher:"Le Journal des Palaces (hotel press release)",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-suntec-city":{title:["Suntec City,","a city","in the shape of a hand"],subtitle:"Temasek Boulevard · offices, mall and convention centre",lead:"Suntec City was built from 1989 and finished in stages between 1995 and 1997. It has five office towers, a mall and a convention and exhibition centre. Its name comes from Chinese words meaning 'new achievement'.",more:["It was designed by I. M. Pei and Partners with DP Architects and Tsao and McKown. From above it looks like a hand: four 45-storey towers are the fingers, the 18-storey tower the thumb and the convention centre the wrist.","The Fountain of Wealth is the ring in the palm. Four 13.8-metre bronze legs hold up a bronze ring 21 metres across, and its water flows inwards to keep wealth in. The 1998 Guinness Book of Records called it the world's largest fountain."],lookFor:["Water flowing inwards at the Fountain of Wealth","The four 45-storey towers around the fountain"],sources:[{title:"Suntec City",url:"https://www.nlb.gov.sg/main/article-detail?cmsuuid=0031a7ef-ebe2-4c42-af76-eaefeef60b10",publisher:"National Library Board (Singapore Infopedia)",checkedAt:"2026-10-31"}],clip:{title:"The Fountain of Wealth",seconds:96,captions:["Suntec City is laid out like a human hand.","Four 45-storey towers are the fingers, an 18-storey one the thumb.","The Fountain of Wealth is the ring in the palm.","Its water flows inwards, a sign of keeping wealth."]},tiles:[{value:1989,label:"construction begins",source:{title:"Suntec City",url:"https://www.nlb.gov.sg/main/article-detail?cmsuuid=0031a7ef-ebe2-4c42-af76-eaefeef60b10",publisher:"National Library Board (Singapore Infopedia)",checkedAt:"2026-10-31"}},{value:45,label:"storeys, each finger tower",source:{title:"Suntec City",url:"https://www.nlb.gov.sg/main/article-detail?cmsuuid=0031a7ef-ebe2-4c42-af76-eaefeef60b10",publisher:"National Library Board (Singapore Infopedia)",checkedAt:"2026-10-31"}},{value:21,label:"metre bronze ring",source:{title:"Suntec City",url:"https://www.nlb.gov.sg/main/article-detail?cmsuuid=0031a7ef-ebe2-4c42-af76-eaefeef60b10",publisher:"National Library Board (Singapore Infopedia)",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-supreme-court-of-singapore":{title:["Supreme Court,","a disc above","the courts"],subtitle:"Supreme Court Lane · law courts",lead:"The Supreme Court building holds Singapore's High Court and Court of Appeal. Designed by Foster + Partners with CPG Corporation, it was declared open in January 2006.",more:["The Court of Appeal sits highest of all, in a metal disc raised above the other courts. The disc stands for the dome of the old Supreme Court building, in a modern form. A shiny roof below it bounces daylight up onto the disc and down into the central atrium.","The building is faced with rosa aurora marble. Its open atria, skylights and lift shafts are meant to show that the law is open to all. Inside are a Judicial Heritage Gallery in basement 1 and a viewing gallery on level 8."],lookFor:["The metal disc on top, home of the Court of Appeal","Rosa aurora marble on the outside walls","The Judicial Heritage Gallery in basement 1"],sources:[{title:"The Supreme Court",url:"https://www.roots.gov.sg/places/places-landing/places/landmarks/the-graftbusters-trail/the-supreme-court",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"},{title:"Supreme Court Courtbuilding",url:"https://cpgcorp.com.sg/?p=3947",publisher:"CPG Corporation",checkedAt:"2026-10-31"},{title:"Visit the Supreme Court",url:"https://www.judiciary.gov.sg/visit-us/supreme-court",publisher:"Singapore Courts",checkedAt:"2026-10-31"}],clip:{title:"The disc on the roof",seconds:90,captions:["Singapore's highest courts sit in this building by Foster + Partners.","President S. R. Nathan declared it open in January 2006.","The disc on top holds the Court of Appeal, like the old court's dome.","Inside, there is a viewing gallery on level 8."]},tiles:[{value:2006,label:"officially opened",source:{title:"The Supreme Court",url:"https://www.roots.gov.sg/places/places-landing/places/landmarks/the-graftbusters-trail/the-supreme-court",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:9,label:"storeys",source:{title:"Supreme Court Courtbuilding",url:"https://cpgcorp.com.sg/?p=3947",publisher:"CPG Corporation",checkedAt:"2026-10-31"}},{value:3,label:"appeal courts",source:{title:"Supreme Court Courtbuilding",url:"https://cpgcorp.com.sg/?p=3947",publisher:"CPG Corporation",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-sushi-zen-1247221":{title:["Sushi Zen,","eight seats","at a Beijing chef’s counter"],subtitle:"Teck Lim Road · sushi counter",lead:"Sushi Zen is a small sushi counter on Teck Lim Road run by E Ran, a well-known sushi chef from Beijing.",more:["Only eight guests sit at the counter. E Ran began learning Edo-mae sushi at 17. Ingredients come from Toyosu Market in Japan and are flown in four times a week; the rice is Nanatsuboshi from Hokkaido.","Teck Lim Road links Keong Saik Road and Neil Road. It is named after businessman Ong Teck Lim and lined with conserved shophouses."],lookFor:["Conserved shophouses on short Teck Lim Road","Keong Saik Road at the end of the street"],sources:[{title:"Food Review: Sushi Zen at Teck Lim Road",url:"https://therantingpanda.com/2024/07/31/food-review-sushi-zen-at-teck-lim-road-beijings-renowned-sushi-chef-owner-e-ran-opens-in-singapore-with-haute-japanese-sushiya/",publisher:"The Ranting Panda (food blog)",checkedAt:"2026-10-29"},{title:"Teck Lim Road",url:"https://en.wikipedia.org/wiki/Teck_Lim_Road",publisher:"Wikipedia",checkedAt:"2026-10-29"}],clip:{title:"Eight seats, one counter",seconds:90,captions:["Sushi Zen is an eight-seat sushi counter on Teck Lim Road.","Its chef-owner, E Ran, is a well-known sushi chef from Beijing.","He began learning Edo-mae sushi at 17.","Fish from Toyosu Market is flown in four times a week."],poster:{src:"nearby/cards/sushi-zen.webp",alt:"Teck Lim Road and its conserved shophouses, the street where Sushi Zen is (not the restaurant itself)",credit:"Terence Ong 2006 · CC BY 2.5",url:"https://commons.wikimedia.org/wiki/File:Teck_Lim_Road.JPG"}},tiles:[{value:8,label:"counter seats",source:{title:"Food Review: Sushi Zen at Teck Lim Road",url:"https://therantingpanda.com/2024/07/31/food-review-sushi-zen-at-teck-lim-road-beijings-renowned-sushi-chef-owner-e-ran-opens-in-singapore-with-haute-japanese-sushiya/",publisher:"The Ranting Panda (food blog)",checkedAt:"2026-10-29"},suffix:" "},{value:17,label:"age E Ran began sushi",source:{title:"Food Review: Sushi Zen at Teck Lim Road",url:"https://therantingpanda.com/2024/07/31/food-review-sushi-zen-at-teck-lim-road-beijings-renowned-sushi-chef-owner-e-ran-opens-in-singapore-with-haute-japanese-sushiya/",publisher:"The Ranting Panda (food blog)",checkedAt:"2026-10-29"},suffix:" "},{value:4,label:"fish flights a week",source:{title:"Food Review: Sushi Zen at Teck Lim Road",url:"https://therantingpanda.com/2024/07/31/food-review-sushi-zen-at-teck-lim-road-beijings-renowned-sushi-chef-owner-e-ran-opens-in-singapore-with-haute-japanese-sushiya/",publisher:"The Ranting Panda (food blog)",checkedAt:"2026-10-29"},suffix:" "}],reviewedAt:"2026-10-29"},"curated:sg-tai-wah-pork-noodle":{title:["Tai Wah,","bak chor mee","from a 1930s cart"],subtitle:"Hong Lim Market and Food Centre · bak chor mee",lead:"Tai Wah Pork Noodle serves bak chor mee, or minced meat noodles, at Hong Lim Market and Food Centre. The recipe goes back to Tang Joon Teo, who sold his noodles from a cart in the 1930s.",more:["His sons helped at the stall from childhood and inherited the recipe. The family later split into separate stalls; Tai Wah and Hill Street Tai Hwa are now separate businesses, and Eatbook says the biggest difference is the sauce the noodles are tossed in.","A bowl comes with meatballs, liver, wonton, crisp pork lard and fried sole fish. The usual noodle is mee pok, flat egg noodles, and the dry version is the one most customers order."],lookFor:["The queue at stall #02-16","Fried sole fish and crisp lard on top","Dry noodles tossed in chilli and vinegar"],sources:[{title:"Tai Wah Pork Noodle",url:"https://eatbook.sg/tai-wah-pork-noodle/",publisher:"Eatbook (food blog)",checkedAt:"2026-10-29"},{title:"Tai Wah Pork Noodle – A slurp-worthy encounter",url:"https://misstamchiak.com/high-street-tai-wah-pork-noodle",publisher:"Miss Tam Chiak (food blog)",checkedAt:"2026-10-29"},{title:"Mee pok (Bak chor mee)",url:"https://en.wikipedia.org/wiki/Bak_chor_mee",publisher:"Wikipedia",checkedAt:"2026-10-29"}],clip:{title:"A family noodle recipe",seconds:90,captions:["Bak chor mee means minced meat noodles.","Tang Joon Teo first sold his noodles from a cart in the 1930s.","His sons took on the recipe; the family stalls later split.","Most people here order it dry, with chilli and vinegar."],poster:{src:"nearby/cards/sg-tai-wah-pork-noodle.webp",alt:"Rows of tables inside Hong Lim Market and Food Centre, where the stall is (not the stall itself)",credit:"Kbseah 2025 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Hong_Lim_Market_and_Food_Centre,_interior.jpg"}},tiles:[{value:1930,label:"cart days begin",source:{title:"Tai Wah Pork Noodle",url:"https://eatbook.sg/tai-wah-pork-noodle/",publisher:"Eatbook (food blog)",checkedAt:"2026-10-29"},suffix:"s"},{value:13,label:"Tai Wah stalls island-wide",source:{title:"Tai Wah Pork Noodle",url:"https://eatbook.sg/tai-wah-pork-noodle/",publisher:"Eatbook (food blog)",checkedAt:"2026-10-29"}},{value:3,label:"bowl sizes at Hong Lim",source:{title:"Tai Wah Pork Noodle",url:"https://eatbook.sg/tai-wah-pork-noodle/",publisher:"Eatbook (food blog)",checkedAt:"2026-10-29"}}],orderProposal:{kind:"bak-chor-mee",title:"Order bak chor mee",intro:"Bak chor mee means minced meat noodles. Pick the noodle, then dry (tossed in sauce) or soup.",base:"one bak chor mee",baseMeaning:"One bowl of minced meat noodles",steps:[{id:"greet",question:"Who is at the counter?",options:[{id:"uncle",label:"Uncle",term:"Uncle,",meaning:""},{id:"auntie",label:"Auntie",term:"Auntie,",meaning:""}]},{id:"noodle",question:"Which noodle?",options:[{id:"meepok",label:"Mee pok · flat",term:"mee pok",meaning:"with flat egg noodles"},{id:"meekia",label:"Mee kia · thin",term:"mee kia",meaning:"with thin noodles"}]},{id:"style",question:"Dry or soup?",options:[{id:"dry",label:"Dry",term:"dry",meaning:"tossed in sauce"},{id:"soup",label:"Soup",term:"soup",meaning:"in soup"}],note:"The dry sauce is chilli, oil and vinegar; add more vinegar at the table."},{id:"where",question:"Eat here or take away?",options:[{id:"here",label:"Having here",term:"having here",meaning:"to eat here"},{id:"dabao",label:"Da bao",term:"da bao",meaning:"to take away"}]}],sources:[{title:"Mee pok (Bak chor mee)",url:"https://en.wikipedia.org/wiki/Bak_chor_mee",publisher:"Wikipedia",checkedAt:"2026-10-29"},{title:"Tai Wah Pork Noodle",url:"https://eatbook.sg/tai-wah-pork-noodle/",publisher:"Eatbook (food blog)",checkedAt:"2026-10-29"},{title:"Tai Wah Pork Noodle – A slurp-worthy encounter",url:"https://misstamchiak.com/high-street-tai-wah-pork-noodle",publisher:"Miss Tam Chiak (food blog)",checkedAt:"2026-10-29"},{title:"Singlish vocabulary",url:"https://en.wikipedia.org/wiki/Singlish_vocabulary",publisher:"Wikipedia",checkedAt:"2026-10-29"}]},reviewedAt:"2026-10-29"},"curated:sg-tan-kim-seng-fountain":{title:["Tan Kim Seng Fountain,","a thank-you","in cast iron"],subtitle:"Esplanade Park · Victorian fountain",lead:"This cast-iron fountain was put up to thank Tan Kim Seng, a Chinese community leader who gave money for the town's first water supply. It was unveiled at Fullerton Square on 19 May 1882.",more:["Tan Kim Seng supported the Chinese Pauper Hospital, now Tan Tock Seng Hospital, and founded two schools. He is best remembered for his gift in 1857 towards waterworks to bring fresh water to the town. The Municipal Council ordered the fountain from Andrew Handyside & Company in Derby, England.","In the lower bowl sit four Muses, Greek goddesses of the arts: Calliope with a writing tablet, Clio with a scroll, Erato with a lyre and Melpomene with a wreath. Under them, four faces of Poseidon spout water. The fountain was moved to Esplanade Park when the Fullerton Building was going up."],lookFor:["Four Muses, each holding her own object","Four faces of Poseidon spouting water","The Cenotaph and Lim Bo Seng Memorial nearby"],sources:[{title:"Esplanade Park Memorials",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/esplanade-park-memorials",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"},{title:"Tan Kim Seng Fountain",url:"https://en.wikipedia.org/wiki/Tan_Kim_Seng_Fountain",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"Water for the town",seconds:90,captions:["This iron fountain honours Tan Kim Seng, a Chinese community leader.","In 1857 he gave money to build the town's freshwater supply.","Four Muses sit in its bowl, above four faces of Poseidon.","First set up at Fullerton Square, it now stands in Esplanade Park."]},tiles:[{value:1857,label:"gift for the waterworks",source:{title:"Esplanade Park Memorials",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/esplanade-park-memorials",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:1882,label:"fountain unveiled",source:{title:"Esplanade Park Memorials",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/esplanade-park-memorials",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:2010,label:"national monument",source:{title:"Tan Kim Seng Fountain",url:"https://en.wikipedia.org/wiki/Tan_Kim_Seng_Fountain",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-tan-si-chong-su":{title:["Tan Si Chong Su,","the hall of","the Tan clan"],subtitle:"Magazine Road · clan temple",lead:"Tan Si Chong Su on Magazine Road is the ancestral hall of the Tan clan. It was built between 1876 and 1878, paid for mainly by the merchants Tan Kim Ching and Tan Beng Swee.",more:['It is also called Po Chiak Keng, meaning "protection of the innocent". The temple helped settle disputes and protected newly arrived Chinese immigrants. A school opened here in 1889 and had about 200 students at its peak, but it closed in 1962.','The building follows traditional Hokkien design, with three halls. Its curved roof ridges end in forked "swallow tails" and carry dragons made from cut pieces of coloured ceramic.'],lookFor:["Swallow-tail roof ridges with ceramic dragons","Granite columns carved with dragons","Door gods painted on the timber doors"],sources:[{title:"Tan Si Chong Su",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/tan-si-chong-su",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"},{title:"Tan Si Chong Su",url:"https://en.wikipedia.org/wiki/Tan_Si_Chong_Su",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"A hall for the Tans",seconds:90,captions:["This is the ancestral hall of the Tan clan.","Merchants Tan Kim Ching and Tan Beng Swee paid for most of it.","Once on the riverbank, it now stands inland after reclamation.","Look for granite dragon columns and painted door gods."],poster:{src:"nearby/cards/sg-tan-si-chong-su.webp",alt:"Front of Tan Si Chong Su, with curved roof ridges and ceramic decoration",credit:"Terence Ong 2006 · CC BY 2.5",url:"https://commons.wikimedia.org/wiki/File:Tan_Si_Chong_Su.JPG"}},tiles:[{value:1876,label:"building starts",source:{title:"Tan Si Chong Su",url:"https://en.wikipedia.org/wiki/Tan_Si_Chong_Su",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:1889,label:"clan school opens",source:{title:"Tan Si Chong Su",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/tan-si-chong-su",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:1974,label:"national monument",source:{title:"Tan Si Chong Su",url:"https://en.wikipedia.org/wiki/Tan_Si_Chong_Su",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-tanjong-pagar-railway-station":{title:["Tanjong Pagar station,","where trains","from Malaya ended"],subtitle:"Keppel Road · former railway terminus, seen from outside",lead:"Tanjong Pagar Railway Station was the southern end of the railway from Malaya. It was officially opened on 2 May 1932, and the last train left on 30 June 2011.",more:["Swan & Maclaren designed it, mostly in the Art Deco style, with ideas from English railway stations. Above the four marble figures on the front are the letters F, M, S and R, for the Federated Malay States Railways.","Inside, the hall is about 22 metres high with no columns, and murals of about 9,000 ceramic tiles show rubber tapping, tin mining, rice growing and transport. The station became a National Monument in 2011 and is now linked with Cantonment MRT station."],lookFor:["Four marble figures on the front","The letters F, M, S and R above them","Chinese-style eave tiles along the roof"],sources:[{title:"Former Tanjong Pagar Railway Station",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/former-tanjong-pagar-railway-station",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-29"},{title:"Tanjong Pagar railway station",url:"https://en.wikipedia.org/wiki/Tanjong_Pagar_railway_station",publisher:"Wikipedia",checkedAt:"2026-10-29"}],clip:{title:"End of the line",seconds:95,captions:["Trains from Malaya ended their journey here from 1932 to 2011.","It was officially opened on 2 May 1932.","Four marble figures stand for farming, trade, transport and industry.","Since 2011 it has been a National Monument."],poster:{src:"nearby/cards/tanjong-pagar-railway-station.webp",alt:"The front of Tanjong Pagar Railway Station with its arches and four marble figures, cars parked in front",credit:"EquatorialSky2, derivative MagentaGreen 2011 · CC BY-SA 3.0",url:"https://commons.wikimedia.org/wiki/File:Tanjong_Pagar_Railway_Station_exterior_view(1_retouched).jpg"}},tiles:[{value:1932,label:"station opened",source:{title:"Former Tanjong Pagar Railway Station",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/former-tanjong-pagar-railway-station",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-29"}},{value:9e3,label:"mural tiles in hall (about)",grouped:!0,source:{title:"Former Tanjong Pagar Railway Station",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/former-tanjong-pagar-railway-station",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-29"}},{value:2011,label:"last train leaves",source:{title:"Former Tanjong Pagar Railway Station",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/former-tanjong-pagar-railway-station",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-29"}}],reviewedAt:"2026-10-29"},"curated:sg-tekka-centre":{title:["Tekka Centre,","Little India’s","people’s market"],subtitle:"Buffalo Road · wet market and hawker centre",lead:"Tekka Centre is a wet market and hawker centre in Little India. Its story began in 1915 with Kandang Kerbau Market, named after the district’s cattle and meat trade.",more:["By the 1930s it was known as the ‘people’s market’, popular with all communities. The stallholders moved into the new complex across the road on 3 May 1981. It was renamed Zhujiao Centre in 1981, but many people could not link the Mandarin name to the area, and it became Tekka Centre in 2000.","Tekka comes from the Hokkien Tek Kia Kha, ‘foot of the small bamboos’. Today the hawker centre sells Indian vegetarian meals on banana leaves, North Indian, Malay and Chinese vegetarian food."],lookFor:["Indian meals served on banana leaves","Seafood and vegetable stalls in the wet market","Tailors who alter clothes in minutes"],sources:[{title:"Tekka Market",url:"https://www.roots.gov.sg/stories-landing/stories/Hawker-Centres/Tekka-Market",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"},{title:"Tekka Centre",url:"https://en.wikipedia.org/wiki/Tekka_Centre",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"Three names for one market",seconds:90,captions:["The first market here opened in 1915 as Kandang Kerbau Market.","Kandang kerbau is Malay for ‘buffalo pens’.","In 1981 it moved across the road into today’s building.","Renamed Tekka Centre in 2000, it sells food from many cultures."],poster:{src:"nearby/cards/tekka-centre.webp",alt:"Rows of wet-market stalls in Tekka Centre seen from the floor above",credit:"Mat Honan 2003 · CC BY 2.0",url:"https://commons.wikimedia.org/wiki/File:Wet_market_in_Tekka_Centre,_Singapore_-_20030228.jpg"}},tiles:[{value:1915,label:"first market opens",source:{title:"Tekka Market",url:"https://www.roots.gov.sg/stories-landing/stories/Hawker-Centres/Tekka-Market",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:1981,label:"stallholders move in",source:{title:"Tekka Market",url:"https://www.roots.gov.sg/stories-landing/stories/Hawker-Centres/Tekka-Market",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:2e3,label:"renamed Tekka Centre",source:{title:"Tekka Market",url:"https://www.roots.gov.sg/stories-landing/stories/Hawker-Centres/Tekka-Market",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-telok-ayer-chinese-methodist-church":{title:["Telok Ayer","Chinese Methodist Church,","a Chinese roof on top"],subtitle:"Telok Ayer Street · Methodist church",lead:"This church grew from the work of Dr Benjamin West, an American doctor and Methodist missionary, who opened a clinic on Upper Nankin Street in 1889. Its present building on Telok Ayer Street was dedicated on 11 January 1925.",more:["The architect was Denis Santry of Swan & Maclaren, who also designed the Cenotaph. The church mixes European arches with a Chinese-style roof.","During the Japanese Occupation, Sunday services went on and about 300 refugees sheltered in the church. Services are held in English, Mandarin and Hokkien."],lookFor:["The Chinese-style roof over the front","Small crosses on the column tops","Louvred doors and windows"],sources:[{title:"Telok Ayer Chinese Methodist Church",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/telok-ayer-chinese-methodist-church",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"},{title:"Telok Ayer Chinese Methodist Church",url:"https://en.wikipedia.org/wiki/Telok_Ayer_Chinese_Methodist_Church",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"A refuge in wartime",seconds:94,captions:["Dr Benjamin West started this church's work in 1889.","The present building was dedicated on 11 January 1925.","About 300 refugees sheltered here in the Second World War.","Look up: a Chinese-style roof tops European arches."],poster:{src:"nearby/cards/sg-telok-ayer-chinese-methodist-church.webp",alt:"The white church on Telok Ayer Street with arches, round windows and a red Chinese-style roof, office towers behind",credit:"Marcin Konsek 2016 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:2016_Singapur,_Chinatown,_Ulica_Telok_Ayer,_Chiński_Kościół_Metodystyczny_(01).jpg"}},tiles:[{value:1889,label:"church work begins",source:{title:"Telok Ayer Chinese Methodist Church",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/telok-ayer-chinese-methodist-church",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:1925,label:"sanctuary dedicated",source:{title:"Telok Ayer Chinese Methodist Church",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/telok-ayer-chinese-methodist-church",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:300,label:"wartime refugees (about)",source:{title:"Telok Ayer Chinese Methodist Church",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/telok-ayer-chinese-methodist-church",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-tentera-di-raja":{title:["Masjid Tentera Di Raja,","built by soldiers","in 1961"],subtitle:"Clementi Road · hillside mosque",lead:"Masjid Tentera Di Raja is a mosque on a hill at the edge of Clementi Woods Park, close to NUS. It was built in 1961 by Muslim soldiers serving in the British forces.",more:["Its name honours their work: “Tentera Diraja” means “Army of the King” in Malay. The mosque was officially opened on 30 March 1962, and it can hold 1,000 people.","The mosque stands on land held under a temporary licence, which was renewed in 2014. A two-storey madrasah building was added in a major renovation in 2006."],lookFor:["The minaret topped by a gold-painted dome","The two-storey madrasah wing added in 2006","The woods of Clementi Woods Park around the hill"],sources:[{title:"Tentera Di Raja",url:"https://www.muis.gov.sg/community/mosque/mosque-directory/tentera-di-raja/",publisher:"Majlis Ugama Islam Singapura (MUIS)",checkedAt:"2026-10-31"},{title:"Masjid Tentera Diraja",url:"https://en.wikipedia.org/wiki/Masjid_Tentera_Diraja",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"The soldiers’ mosque",seconds:90,captions:["A mosque on a hill at the edge of Clementi Woods Park.","Muslim soldiers in the British forces built it in 1961.","Its name means “Army of the King” in Malay.","Look up at the minaret with its gold-painted dome."]},tiles:[{value:1961,label:"built by soldiers",source:{title:"Tentera Di Raja",url:"https://www.muis.gov.sg/community/mosque/mosque-directory/tentera-di-raja/",publisher:"Majlis Ugama Islam Singapura (MUIS)",checkedAt:"2026-10-31"}},{value:1962,label:"officially opened",source:{title:"Masjid Tentera Diraja",url:"https://en.wikipedia.org/wiki/Masjid_Tentera_Diraja",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:1e3,label:"worshippers it can hold",grouped:!0,source:{title:"Tentera Di Raja",url:"https://www.muis.gov.sg/community/mosque/mosque-directory/tentera-di-raja/",publisher:"Majlis Ugama Islam Singapura (MUIS)",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-the-arts-house-old-parliament-house":{title:["The Arts House,","Singapore's oldest","government building"],subtitle:"Old Parliament Lane · arts centre in the old Parliament",lead:"Built in 1827, this is Singapore's oldest government building and perhaps its oldest surviving building. It was a courthouse, then home to Parliament from 1965 to 1999, and is now The Arts House.",more:["Architect George Drumgoole Coleman designed it as a mansion for John Argyle Maxwell, a Scottish merchant. A dispute over the land meant Maxwell never moved in. The house was leased to the government and first used as a court house; the government bought it in 1842.","Extensions in 1873-1875 and 1901 changed the house, and Coleman's original design was lost. After the Second World War it became the Assembly House, and in 1965 the Parliament House of the new nation. Parliament moved next door in 1999, and The Arts House opened here on 26 March 2004."],lookFor:["Arches at the porch, from the 1827 design","Palladian windows on the front","The Chamber, the old debating hall"],sources:[{title:"The Arts House",url:"https://en.wikipedia.org/wiki/The_Arts_House",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"House, court, Parliament",seconds:100,captions:["G. D. Coleman designed this house in 1827 for merchant John Maxwell.","Maxwell never lived in it; it became a courthouse instead.","From 1965 to 1999 it was home to Singapore's Parliament.","The old chamber is now a 150-seat room for music and film."]},tiles:[{value:1827,label:"house completed",source:{title:"The Arts House",url:"https://en.wikipedia.org/wiki/The_Arts_House",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:1965,label:"Parliament moves in",source:{title:"The Arts House",url:"https://en.wikipedia.org/wiki/The_Arts_House",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:2004,label:"arts centre opens",source:{title:"The Arts House",url:"https://en.wikipedia.org/wiki/The_Arts_House",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-the-blue-ginger-tanjong-pagar":{title:["The Blue Ginger,","Peranakan food","in a three-storey shophouse"],subtitle:"Tanjong Pagar Road · Peranakan (Nonya) restaurant",lead:"The Blue Ginger is a Peranakan restaurant on Tanjong Pagar Road, open since 1995. It is one of the first Peranakan restaurants in Singapore.",more:["A group of friends started it when Peranakan food was mostly cooked at home. It is housed in an original, restored three-storey shophouse.","Inside, look for a Peranakan portrait painting and Peranakan tiles at the bar. It is a MICHELIN Bib Gourmand restaurant in the 2026 guide."],lookFor:["A Peranakan portrait painting above a dining table","Peranakan tiles at the bar","The three-storey shophouse front"],sources:[{title:"The Blue Ginger – Tanjong Pagar",url:"https://theblueginger.com/tanjong-pagar/",publisher:"The Blue Ginger",checkedAt:"2026-10-29"},{title:"About The Blue Ginger",url:"https://theblueginger.com/about-us/",publisher:"The Blue Ginger",checkedAt:"2026-10-29"}],clip:{title:"Home cooking, since 1995",seconds:90,captions:["The Blue Ginger serves Peranakan, or Nonya, food.","A group of friends opened it on Tanjong Pagar Road in 1995.","Back then, Peranakan food was mostly cooked at home.","It fills a restored three-storey shophouse."],poster:{src:"nearby/cards/the-blue-ginger.webp",alt:"Shophouses along Tanjong Pagar Road, the street where The Blue Ginger is (not the restaurant itself)",credit:"Deoma12 2024 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Shophouses_along_Tanjong_Pagar_Road.jpg"}},tiles:[{value:1995,label:"opened by a group of friends",source:{title:"The Blue Ginger – Tanjong Pagar",url:"https://theblueginger.com/tanjong-pagar/",publisher:"The Blue Ginger",checkedAt:"2026-10-29"}},{value:3,label:"storeys of shophouse",source:{title:"The Blue Ginger – Tanjong Pagar",url:"https://theblueginger.com/tanjong-pagar/",publisher:"The Blue Ginger",checkedAt:"2026-10-29"},suffix:" "},{value:2026,label:"MICHELIN Bib Gourmand",source:{title:"The Blue Ginger – Tanjong Pagar",url:"https://theblueginger.com/tanjong-pagar/",publisher:"The Blue Ginger",checkedAt:"2026-10-29"}}],reviewedAt:"2026-10-29"},"curated:sg-the-cenotaph":{title:["The Cenotaph,","for 124 men","who never came home"],subtitle:"Esplanade Park · war memorial",lead:"The Cenotaph remembers the soldiers who died in both World Wars. It was first built for the 124 men from Singapore who went to the war in Europe in 1914-1918 and never returned.",more:["Governor Sir Laurence Guillemard laid the foundation stone on 15 November 1920. Denis Santry of Swan & Maclaren designed it after the Cenotaph in Whitehall, London. It is made of local white granite and is nearly 18 metres tall.","After the Japanese Occupation, the back was dedicated to those who died defending Singapore in the Second World War. The words 'They died that we might live' are set in bronze in English, Chinese, Malay and Tamil."],lookFor:["The words 'Our Glorious Dead'","Five steps, each carved with a war year","A bronze crown in a laurel wreath on top"],sources:[{title:"Esplanade Park Memorials",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/esplanade-park-memorials",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}],clip:{title:"Our Glorious Dead",seconds:90,captions:["This granite memorial honours the dead of both World Wars.","It was built for 124 men from Singapore lost in the First World War.","The visiting Prince of Wales unveiled it on 31 March 1922.","Its back carries words in Singapore's four official languages."]},tiles:[{value:1920,label:"foundation stone laid",source:{title:"Esplanade Park Memorials",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/esplanade-park-memorials",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:1922,label:"memorial unveiled",source:{title:"Esplanade Park Memorials",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/esplanade-park-memorials",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:124,label:"names on bronze plates",source:{title:"Esplanade Park Memorials",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/esplanade-park-memorials",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}}],thenNow:{then:{src:"nearby/cards/the-cenotaph-then.webp",alt:"Old postcard of the Cenotaph tower on its wide steps by the sea, with ships in the distance",credit:"Unknown photographer, undated (KITLV 104806) · CC BY 4.0",url:"https://commons.wikimedia.org/wiki/File:De_Cenotaph,_oorlogsmonument_te_Singapore,_KITLV_104806.tiff"},now:{src:"nearby/cards/the-cenotaph-now.webp",alt:"The granite Cenotaph with the words Our Glorious Dead, its steps and trees behind",credit:"CEphoto, Uwe Aranas 2015 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Singapore_The-Cenotaph-01.jpg"},thenLabel:"Undated",nowLabel:"2015",captions:{then:{lead:"Old postcard.",text:" The Cenotaph by the sea, ships beyond the wall."},mid:{lead:"Same steps, same tower.",text:" Trees now fill the view behind it."},now:{lead:"2015.",text:" “Our Glorious Dead” above the steps."}}},reviewedAt:"2026-10-29"},"curated:sg-the-coconut-club-1195654":{title:["The Coconut Club,","all things lemak"],subtitle:"Beach Road · nasi lemak restaurant",lead:"The Coconut Club opened on Ann Siang Hill in 2016 as a restaurant built around one dish, nasi lemak. In 2022 it moved to a larger, restored shophouse on Beach Road in Kampong Gelam.",more:["'Lemak' means the rich creaminess of coconut. The rice is made with the restaurant's own 'White Sutera' coconut milk, a blend from a family-run farm. The chicken comes from a fourth-generation farm in Loyang.","The three-storey shophouse seats up to 100 diners. Desserts include chendol and pandan sago with gula melaka. It has a MICHELIN Bib Gourmand."],lookFor:["A restored shophouse on Beach Road","Nasi lemak with fried chicken (ayam goreng berempah)","Chendol or pandan sago gula melaka"],sources:[{title:"The Coconut Club turns 10",url:"https://middleclass.sg/treats/the-coconut-club-10-anniversary/",publisher:"Middle Class",checkedAt:"2026-10-31"},{title:"The Coconut Club",url:"https://secretsingapore.co/the-coconut-club/",publisher:"Secret Singapore",checkedAt:"2026-10-31"},{title:"Beach Road",url:"https://www.thecoconutclub.sg/beach-road",publisher:"The Coconut Club",checkedAt:"2026-10-31"},{title:"About",url:"https://www.thecoconutclub.sg/about",publisher:"The Coconut Club",checkedAt:"2026-10-31"}],clip:{title:"All things lemak",seconds:85,captions:["The Coconut Club opened on Ann Siang Hill in 2016.","It was built around one dish: nasi lemak.","In 2022 it moved to a three-storey shophouse on Beach Road.","Its rice is cooked in its own 'White Sutera' coconut milk."],poster:{src:"nearby/cards/sg-the-coconut-club-1195654.webp",alt:"Beach Road at dusk, with low older buildings and towers behind (the road, not the restaurant)",credit:"Angelo Fernandes05 2023 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Beach_Road_in_Singapore.jpg"}},tiles:[{value:2016,label:"opens on Ann Siang Hill",source:{title:"The Coconut Club turns 10",url:"https://middleclass.sg/treats/the-coconut-club-10-anniversary/",publisher:"Middle Class",checkedAt:"2026-10-31"}},{value:2022,label:"moves to Beach Road",source:{title:"The Coconut Club",url:"https://secretsingapore.co/the-coconut-club/",publisher:"Secret Singapore",checkedAt:"2026-10-31"}},{value:100,label:"diners (up to)",source:{title:"The Coconut Club",url:"https://secretsingapore.co/the-coconut-club/",publisher:"Secret Singapore",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-the-concourse":{title:["The Concourse,","an eight-sided","tropical skyscraper"],subtitle:"Beach Road · office tower and apartments",lead:"The Concourse on Beach Road was started in 1981 as Hong Fok Centre, but work stopped in the mid-1980s recession. In 1987 the American architect Paul Rudolph and Architects 61 redesigned it, and it was completed on 5 February 1994.",more:["Rudolph called it a 'Tropical Skyscraper', with sun shading, wide overhangs and balconies. The 41-storey tower is eight-sided, as 8 is linked with prosperity in Chinese culture.","Tall columns lift the tower off the ground. Its aluminium walls have sloping windows in clusters, stacked like dinner plates and turning around the building. Inside are 14 sky-atria."],lookFor:["Tall columns lifting the tower at its base","Window clusters turning like stacked plates"],sources:[{title:"The Concourse",url:"https://en.wikipedia.org/wiki/The_Concourse",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"Stacked like plates",seconds:90,captions:["Paul Rudolph redesigned this half-built tower in 1987.","It was completed on 5 February 1994.","Its plan has eight sides; 8 means prosperity in Chinese culture.","Window clusters rotate up the tower like stacked plates."]},tiles:[{value:1994,label:"completed",source:{title:"The Concourse",url:"https://en.wikipedia.org/wiki/The_Concourse",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:175,label:"metres, office tower",source:{title:"The Concourse",url:"https://en.wikipedia.org/wiki/The_Concourse",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:41,label:"storeys",source:{title:"The Concourse",url:"https://en.wikipedia.org/wiki/The_Concourse",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-the-float-marina-bay":{title:["The Float,","a stage on the bay,","becoming NS Square"],subtitle:"Marina Bay · former floating stage",lead:"The Float was a 120-by-83-metre steel stage floating on Marina Bay, with a 27,000-seat grandstand on the shore. It opened in 2007 and is being rebuilt as NS Square.",more:["It was meant as a stop-gap venue while the National Stadium was rebuilt, and hosted National Day Parades, the 2010 Youth Olympics ceremonies and New Year's Eve shows. The platform was made of 15 large pontoons that lock together like a jigsaw, held in place by six pylons.","In 2017 the government said The Float would become NS Square, a permanent tribute to National Service. The new venue will have about 30,000 seats, a gallery on National Service and a waterfront promenade, and is due by 2027."],lookFor:["Building works for NS Square on the bay","The city skyline that was the stage's backdrop"],sources:[{title:"The Float @ Marina Bay",url:"https://en.wikipedia.org/wiki/The_Float_%40_Marina_Bay",publisher:"Wikipedia",checkedAt:"2026-10-31"},{title:"NS Square",url:"https://www.mindef.gov.sg/about-us/community-engagement/ns-square/",publisher:"Ministry of Defence Singapore",checkedAt:"2026-10-31"}],clip:{title:"A stage that floated",seconds:90,captions:["From 2007 a huge steel stage floated here on Marina Bay.","It was built while the old National Stadium was being rebuilt.","It could carry 1,070 tonnes, the weight of about 9,000 people.","Now it is being rebuilt as NS Square, due to be ready by 2027."]},tiles:[{value:2007,label:"stage opens",source:{title:"The Float @ Marina Bay",url:"https://en.wikipedia.org/wiki/The_Float_%40_Marina_Bay",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:27e3,label:"grandstand seats",grouped:!0,source:{title:"The Float @ Marina Bay",url:"https://en.wikipedia.org/wiki/The_Float_%40_Marina_Bay",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:3e4,label:"seats at NS Square",grouped:!0,source:{title:"NS Square",url:"https://www.mindef.gov.sg/about-us/community-engagement/ns-square/",publisher:"Ministry of Defence Singapore",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-the-gateway":{title:["The Gateway,","two sharp towers","by I. M. Pei"],subtitle:"Beach Road · office towers",lead:"The Gateway is a pair of 37-storey, 150-metre office towers on Beach Road, completed in April 1990. They are called The Gateway East and The Gateway West.",more:["The towers were designed by the American architect I. M. Pei, with the local firm Chua Ka Seng and Partners. Their trapezoid shape is like the one Pei used for the East Building of the National Gallery of Art in Washington, D.C."],lookFor:["The sharp corners of the two trapezoid towers"],sources:[{title:"The Gateway (Singapore)",url:"https://en.wikipedia.org/wiki/The_Gateway_(Singapore)",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"Two trapezoids",seconds:90,captions:["The Gateway is a pair of office towers on Beach Road.","I. M. Pei designed them; they were completed in April 1990.","Each tower is a trapezoid in plan.","They are named The Gateway East and The Gateway West."]},tiles:[{value:1990,label:"completed",source:{title:"The Gateway (Singapore)",url:"https://en.wikipedia.org/wiki/The_Gateway_(Singapore)",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:37,label:"storeys",source:{title:"The Gateway (Singapore)",url:"https://en.wikipedia.org/wiki/The_Gateway_(Singapore)",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:150,label:"metres tall",source:{title:"The Gateway (Singapore)",url:"https://en.wikipedia.org/wiki/The_Gateway_(Singapore)",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-the-majestic":{title:["The Majestic,","a Cantonese","opera house"],subtitle:"Eu Tong Sen Street · former opera house and cinema",lead:"The Majestic on Eu Tong Sen Street was completed in 1928. Eu Tong Sen, a tin-mining and rubber tycoon, built it as a Cantonese opera house for his wife, who loved the opera.",more:["It became a cinema in 1938. During the Japanese Occupation it was the Tai Hwa Opera House, and after the war the Majestic Film Company gave it its present name. It showed Chinese films until it closed in 1998.","The building, by the architects Swan and Maclaren, mixes Western and Chinese styles and was built to seat 1,194 people. After an S$8 million renovation it reopened as a shopping mall in 2003."],lookFor:["Tiles with Cantonese opera scenes on the front","A colourful mosaic of flying dragons","The name “The Majestic” high on the front"],sources:[{title:"The Majestic, Singapore",url:"https://en.wikipedia.org/wiki/The_Majestic,_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-29"}],clip:{title:"An opera house for his wife",seconds:90,captions:["The Majestic was completed in 1928 as a Cantonese opera house.","Tycoon Eu Tong Sen built it for his wife, an opera fan.","Tiles on the front show scenes from Cantonese opera.","It was a cinema until 1998, then became a shopping mall."],poster:{src:"nearby/cards/the-majestic.webp",alt:"The Majestic on Eu Tong Sen Street, its decorated front with the name across the top",credit:"Bahnfrend 2025 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:The_Majestic,_Singapore,_2025_(01).jpg"}},tiles:[{value:1928,label:"opera house completed",source:{title:"The Majestic, Singapore",url:"https://en.wikipedia.org/wiki/The_Majestic,_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-29"}},{value:1194,label:"seats when built",grouped:!0,source:{title:"The Majestic, Singapore",url:"https://en.wikipedia.org/wiki/The_Majestic,_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-29"}},{value:1998,label:"cinema closes",source:{title:"The Majestic, Singapore",url:"https://en.wikipedia.org/wiki/The_Majestic,_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-29"}}],reviewedAt:"2026-10-29"},"curated:sg-the-metropolis":{title:["The Metropolis,","twin office towers","at Buona Vista"],subtitle:"North Buona Vista Drive · office towers",lead:"The Metropolis is a pair of office towers on North Buona Vista Drive, with the Buona Vista MRT interchange at its doorstep. Its developer, Ho Bee, calls it the largest commercial development outside the Central Business District.",more:["It was planned as the gateway to one-north, the nearby hub for research and business parks. It was completed in 2013 and has a total floor area of about 1.2 million square feet.","Its floors are large and free of columns, about 29,000 and 27,000 square feet. The building holds the BCA Green Mark Platinum award for green design."],sources:[{title:"The Metropolis",url:"https://www.hobee.com/projects/work/the-metropolis",publisher:"Ho Bee Land",checkedAt:"2026-10-31"}],clip:{title:"Offices outside the CBD",seconds:80,captions:["The Metropolis is two office towers beside Buona Vista MRT.","Ho Bee planned it as a gateway to one-north.","Finished in 2013, it has about 1.2 million sq ft of floor space.","Its builder calls it the largest office project outside the CBD."],poster:{src:"nearby/cards/the-metropolis.webp",alt:"The two glass towers of The Metropolis at Buona Vista on a rainy evening, seen from a height",credit:"Erwin Soo 2013 · CC BY 2.0",url:"https://commons.wikimedia.org/wiki/File:The_Metropolis_and_the_MOE_Building,_Singapore,_on_a_rainy_evening_-_20130303.jpg"}},tiles:[{value:2013,label:"completed",source:{title:"The Metropolis",url:"https://www.hobee.com/projects/work/the-metropolis",publisher:"Ho Bee Land",checkedAt:"2026-10-31"}},{value:1.2,label:"gross floor area",suffix:"M sq ft",source:{title:"The Metropolis",url:"https://www.hobee.com/projects/work/the-metropolis",publisher:"Ho Bee Land",checkedAt:"2026-10-31"}},{value:29e3,label:"sq ft on a large floor",grouped:!0,source:{title:"The Metropolis",url:"https://www.hobee.com/projects/work/the-metropolis",publisher:"Ho Bee Land",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-the-rochester":{title:["The Rochester,","homes, hotel and shops","in one place"],subtitle:"Rochester Drive · mixed-use development",lead:"The Rochester is a mixed-use development at one-north. It combines a condominium, terrace houses, a hotel, serviced apartments and a shopping podium.",more:["Its 26-storey tower holds a 250-room hotel and 120 serviced apartments. Beside it are a condominium tower, 32 three-storey terrace houses, an eight-storey retail and car park podium, and two older two-storey bungalows.","The whole development has about 73,600 square metres of floor space and cost about S$290 million to build."],sources:[{title:"Mixed Development – The Rochester at One North",url:"https://www.jrp-group.com/en/projects/detail/541/",publisher:"J. Roger Preston",checkedAt:"2026-10-31"}],clip:{title:"A small town in one block",seconds:75,captions:["The Rochester mixes homes, a hotel and shops at one-north.","A 26-storey tower holds 250 hotel rooms and 120 serviced flats.","An eight-storey podium holds shops and parking.","There are also 32 three-storey terrace houses."],poster:{src:"nearby/cards/the-rochester.webp",alt:"The Rochester towers on the left, beside The Star building, seen across a lawn",credit:"B.B.25 2018 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:The_Star_Vista_and_The_Rochester_Condo.jpg"}},tiles:[{value:250,label:"hotel rooms",source:{title:"Mixed Development – The Rochester at One North",url:"https://www.jrp-group.com/en/projects/detail/541/",publisher:"J. Roger Preston",checkedAt:"2026-10-31"}},{value:120,label:"serviced apartments",source:{title:"Mixed Development – The Rochester at One North",url:"https://www.jrp-group.com/en/projects/detail/541/",publisher:"J. Roger Preston",checkedAt:"2026-10-31"}},{value:73600,label:"m² floor area",grouped:!0,source:{title:"Mixed Development – The Rochester at One North",url:"https://www.jrp-group.com/en/projects/detail/541/",publisher:"J. Roger Preston",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-the-sail-marina-bay":{title:["The Sail,","two glass towers","of homes by the bay"],subtitle:"Marina Bay · condominium towers",lead:"The Sail @ Marina Bay is a pair of glass condominium towers finished in 2008. The taller one has 70 storeys and rises 245 metres, one of the tallest homes in Singapore.",more:["The towers were designed by Peter Pran and Timothy Johnson of NBBJ. The Marina Bay Tower was shaped to look like a sail, and the space between the towers like a canyon, ideas taken from sun, wind and water.","There are 1,111 homes, from one-bedroom flats to five penthouses, with shops on the lower floors. The towers stand on reclaimed land, built over an MRT line on soft ground. They are private homes, so you see them from the street."],lookFor:["The sail-shaped Marina Bay Tower, 70 storeys","The shorter Central Park Tower, 63 storeys","Downtown MRT station just to the west"],sources:[{title:"The Sail @ Marina Bay",url:"https://en.wikipedia.org/wiki/The_Sail_%40_Marina_Bay",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"Shaped like a sail",seconds:90,captions:["These two glass towers are homes, not offices.","The taller tower has 70 storeys and rises 245 metres.","The Marina Bay Tower was shaped to look like a sail.","The first residents moved in in July 2008."]},tiles:[{value:2008,label:"first residents move in",source:{title:"The Sail @ Marina Bay",url:"https://en.wikipedia.org/wiki/The_Sail_%40_Marina_Bay",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:70,label:"storeys",source:{title:"The Sail @ Marina Bay",url:"https://en.wikipedia.org/wiki/The_Sail_%40_Marina_Bay",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:1111,label:"homes",grouped:!0,source:{title:"The Sail @ Marina Bay",url:"https://en.wikipedia.org/wiki/The_Sail_%40_Marina_Bay",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-the-star-vista":{title:["The Star Vista,","shops under","a 5,000-seat theatre"],subtitle:"Vista Exchange Green · mall in The Star",lead:"The Star Vista is a three-storey shopping mall in The Star, a 15-storey building next to Buona Vista MRT station. Above it is The Star Performing Arts Centre.",more:["The building was designed by Andrew Bromberg of the firm Aedas. The arts centre fills levels 3 to 11 and includes The Star Theatre, with 5,000 seats, and an outdoor amphitheatre for 300. It opened officially on 1 November 2012 with a concert by David Foster.","CapitaLand developed the mall. In November 2019 Rock Productions, the business arm of New Creation Church, bought it for S$296 million. The church holds its services in the theatre above."],lookFor:["The arts centre in the upper half, shops below","The outdoor amphitheatre for 300 people"],sources:[{title:"The Star, Singapore",url:"https://en.wikipedia.org/wiki/The_Star,_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"A mall under a theatre",seconds:85,captions:["The Star Vista is a three-storey mall inside The Star.","Andrew Bromberg of Aedas designed the curving building.","Above the shops sits a theatre with 5,000 seats.","The arts centre opened on 1 November 2012."],poster:{src:"nearby/cards/the-star-vista.webp",alt:"The Star, a large curving building with The Star Vista mall in its lower floors, seen from above",credit:"Whywhy99 2014 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:The_Star_Vista,_Singapore.jpg"}},tiles:[{value:2012,label:"arts centre opens",source:{title:"The Star, Singapore",url:"https://en.wikipedia.org/wiki/The_Star,_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:5e3,label:"seats in The Star Theatre",grouped:!0,source:{title:"The Star, Singapore",url:"https://en.wikipedia.org/wiki/The_Star,_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:15,label:"storeys",source:{title:"The Star, Singapore",url:"https://en.wikipedia.org/wiki/The_Star,_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-tian-tian-hainanese-chicken-rice":{title:["Tian Tian,","Maxwell’s famous","chicken rice"],subtitle:"Maxwell Food Centre · Hainanese chicken rice",lead:"Tian Tian Hainanese Chicken Rice is run by Foo Kui Lian, who took over the business from her brother. It became famous after Anthony Bourdain featured it on his TV show “No Reservations” in 2008.",more:["Foo retired in 2010, but in 2013 she competed against Gordon Ramsay over who made the better chicken rice. In 2016 the stall became the first in Maxwell Food Centre to get a MICHELIN Bib Gourmand.","The business has grown, but it still runs from the same stall. When Foo started out, she prepared 15 to 20 chickens every morning."],lookFor:["The queue at stall #01-10/11","Rice cooked with chicken fat, ginger and pandan","Chilli sauce, dark soy sauce and ginger"],order:"chicken-rice",sources:[{title:"Gordon Ramsay brought her out of retirement (Insider)",url:"https://sg.news.yahoo.com/gordon-ramsay-brought-her-retirement-132101669.html",publisher:"Business Insider via Yahoo News Singapore",checkedAt:"2026-10-29"},{title:"Maxwell Food Centre",url:"https://en.wikipedia.org/wiki/Maxwell_Food_Centre",publisher:"Wikipedia",checkedAt:"2026-10-29"},{title:"Hainanese chicken rice",url:"https://en.wikipedia.org/wiki/Hainanese_chicken_rice",publisher:"Wikipedia",checkedAt:"2026-10-29"}],clip:{title:"A queue made famous",seconds:90,captions:["Tian Tian sells Hainanese chicken rice at Maxwell Food Centre.","Anthony Bourdain featured it on his TV show in 2008.","In 2013 it took on Gordon Ramsay in a chicken rice contest.","In 2016 it was the first stall here with a Bib Gourmand."],poster:{src:"nearby/cards/sg-tian-tian-hainanese-chicken-rice.webp",alt:"A plate of Tian Tian chicken rice with poached chicken, greens and chilli sauce at Maxwell Food Centre",credit:"Orderinchaos 2016 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Singapore_food_-_Tian_Tian_chicken_rice_Nov_2016.jpg"}},tiles:[{value:2008,label:"on Bourdain’s TV show",source:{title:"Gordon Ramsay brought her out of retirement (Insider)",url:"https://sg.news.yahoo.com/gordon-ramsay-brought-her-retirement-132101669.html",publisher:"Business Insider via Yahoo News Singapore",checkedAt:"2026-10-29"}},{value:2013,label:"chicken rice vs Ramsay",source:{title:"Gordon Ramsay brought her out of retirement (Insider)",url:"https://sg.news.yahoo.com/gordon-ramsay-brought-her-retirement-132101669.html",publisher:"Business Insider via Yahoo News Singapore",checkedAt:"2026-10-29"}},{value:2016,label:"Michelin Bib Gourmand",source:{title:"Gordon Ramsay brought her out of retirement (Insider)",url:"https://sg.news.yahoo.com/gordon-ramsay-brought-her-retirement-132101669.html",publisher:"Business Insider via Yahoo News Singapore",checkedAt:"2026-10-29"}}],reviewedAt:"2026-10-29"},"curated:sg-true-blue-cuisine":{title:["True Blue Cuisine,","a Peranakan home","on Armenian Street"],subtitle:"Armenian Street · Peranakan restaurant",lead:"True Blue Cuisine is a Peranakan restaurant on Armenian Street, run by Benjamin Seck, known as Baba Ben. He started it in November 2003 with his mother, the Peranakan cook Nyonya Daisy Seah.",more:["The restaurant began at East Coast Road and moved to 47/49 Armenian Street in January 2008. Signature dishes from Daisy include ayam buah keluak, ngoh hiang and chap chye. The kitchen does not use pork or lard, so chicken takes its place.","Ben collects Peranakan things. The rooms show old furniture, beadwork slippers, antique jewellery and family photos from the last 100 years. The main hall has a 'chim chae', the airwell found in Peranakan homes."],lookFor:["The airwell (chim chae) in the main hall","Antique beaded slippers in the Manek Room","Ayam buah keluak on the menu"],sources:[{title:"About",url:"https://truebluecuisine.com/about/",publisher:"True Blue Cuisine",checkedAt:"2026-10-31"},{title:"Chefs",url:"https://truebluecuisine.com/chefs/",publisher:"True Blue Cuisine",checkedAt:"2026-10-31"},{title:"Premises",url:"https://truebluecuisine.com/premises/",publisher:"True Blue Cuisine",checkedAt:"2026-10-31"}],clip:{title:"A Peranakan dining room",seconds:90,captions:["Benjamin Seck opened a Peranakan restaurant in November 2003.","His mother, Nyonya Daisy Seah, shaped its menu.","It moved to 47/49 Armenian Street in January 2008.","Dine among his old Peranakan furniture and photos."],poster:{src:"nearby/cards/sg-true-blue-cuisine.webp",alt:"Two-storey shophouses along Armenian Street (the street, not the restaurant itself)",credit:"Jacklee 2012 · CC BY-SA 3.0",url:"https://commons.wikimedia.org/wiki/File:Shophouses_along_Armenian_Street,_Singapore_-_20120103-01.jpg"}},tiles:[{value:2003,label:"restaurant starts",source:{title:"Chefs",url:"https://truebluecuisine.com/chefs/",publisher:"True Blue Cuisine",checkedAt:"2026-10-31"}},{value:2008,label:"moves to Armenian Street",source:{title:"About",url:"https://truebluecuisine.com/about/",publisher:"True Blue Cuisine",checkedAt:"2026-10-31"}},{value:80,label:"seats in the main hall",source:{title:"Premises",url:"https://truebluecuisine.com/premises/",publisher:"True Blue Cuisine",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-true-way-presbyterian-church":{title:["True Way Presbyterian,","a church for","Hokkien migrants"],subtitle:"Stirling Road · Presbyterian church",lead:"True Way Presbyterian Church is on Stirling Road in Queenstown. Rev Tan Leng Tian founded it in 1939 for mostly Hokkien-speaking migrant workers.",more:["The members first met at Rev Tan’s home and later used other churches’ buildings. The foundation stone of its first church on Stirling Road was laid on 23 October 1960.","Members’ children joined an English youth fellowship started in 1970. It grew into an English service, which became a full congregation in 1992. A Thai fellowship began in 1998 and is now a Thai service. The church marked its 85th anniversary in 2024."],sources:[{title:"About Us",url:"https://www.trueway.org.sg/about-us/",publisher:"True Way Presbyterian Church (English Congregation)",checkedAt:"2026-10-31"},{title:"我们的历史 (Our History)",url:"https://twpc.org.sg/our-history/",publisher:"True Way Presbyterian Church",checkedAt:"2026-10-31"}],clip:{title:"Started in a pastor’s home",seconds:85,captions:["Rev Tan Leng Tian founded the church in 1939.","It first met in his home, then in other churches.","An English youth group began in 1970 and grew into a service.","Today there are Chinese, English and Thai services."],poster:{src:"nearby/cards/true-way-presbyterian-church.webp",alt:"True Way Presbyterian Church on Stirling Road, a cream and red church building below tall flats",credit:"Kbseah 2026 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:True_Way_Presbyterian_Church,_exterior.jpg"}},tiles:[{value:1939,label:"church founded",source:{title:"About Us",url:"https://www.trueway.org.sg/about-us/",publisher:"True Way Presbyterian Church (English Congregation)",checkedAt:"2026-10-31"}},{value:1970,label:"English youth group starts",source:{title:"About Us",url:"https://www.trueway.org.sg/about-us/",publisher:"True Way Presbyterian Church (English Congregation)",checkedAt:"2026-10-31"}},{value:1992,label:"English congregation",source:{title:"About Us",url:"https://www.trueway.org.sg/about-us/",publisher:"True Way Presbyterian Church (English Congregation)",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-um-yong-baek":{title:["Um Yong Baek,","Busan pork soup","by Lau Pa Sat"],subtitle:"Boon Tat Street · Busan pork soup and barbecue",lead:"Um Yong Baek is the Singapore branch of a Busan restaurant famous for dwaeji gukbap, a pork and rice soup.",more:["It opened officially on 1 July 2022. You can choose a clear Busan-style broth or the thicker Milyang style made from pork bones. In the evening it becomes a barbecue restaurant.","In 2025 Korea’s agriculture ministry named it one of three outstanding Korean restaurants in Singapore. Boon Tat Street was called Japan Street until it was renamed in 1946."],lookFor:["Satay stalls on Boon Tat Street in the evening","Lau Pa Sat’s cast-iron market hall at the street’s end"],sources:[{title:"Um Yong Baek review",url:"https://hungrygowhere.com/critics-reviews/um-yong-baek-singapore/",publisher:"HungryGoWhere",checkedAt:"2026-10-29"},{title:"Korea designates 7 new outstanding Korean restaurants worldwide",url:"https://www.koreatimes.co.kr/lifestyle/travel-food/20251118/korea-designates-7-new-outstanding-korean-restaurants-worldwide",publisher:"The Korea Times",checkedAt:"2026-10-29"},{title:"Boon Tat Street",url:"https://en.wikipedia.org/wiki/Boon_Tat_Street",publisher:"Wikipedia",checkedAt:"2026-10-29"}],clip:{title:"Busan soup for lunch",seconds:90,captions:["Um Yong Baek began in Busan as a pork and rice soup house.","Its Singapore branch officially opened on 1 July 2022.","The broth takes more than 24 hours to prepare.","By day it serves soup; in the evening it turns into a barbecue."],poster:{src:"nearby/cards/um-yong-baek.webp",alt:"Evening satay stalls on Boon Tat Street beside Lau Pa Sat, the street where Um Yong Baek is (not the restaurant itself)",credit:"alex.ch 2007 · CC BY 2.0",url:"https://commons.wikimedia.org/wiki/File:Satay_stalls_along_Boon_Tat_Street_next_to_Telok_Ayer_Market,_Singapore_-_20070127-01.jpg"}},tiles:[{value:1946,label:"Japan Street renamed",source:{title:"Boon Tat Street",url:"https://en.wikipedia.org/wiki/Boon_Tat_Street",publisher:"Wikipedia",checkedAt:"2026-10-29"}},{value:2022,label:"Singapore branch opens",source:{title:"Um Yong Baek review",url:"https://hungrygowhere.com/critics-reviews/um-yong-baek-singapore/",publisher:"HungryGoWhere",checkedAt:"2026-10-29"}},{value:2025,label:"named outstanding by Korea",source:{title:"Korea designates 7 new outstanding Korean restaurants worldwide",url:"https://www.koreatimes.co.kr/lifestyle/travel-food/20251118/korea-designates-7-new-outstanding-korean-restaurants-worldwide",publisher:"The Korea Times",checkedAt:"2026-10-29"}}],reviewedAt:"2026-10-29"},"curated:sg-uob-plaza":{title:["UOB Plaza,","a bank's tower","by the river"],subtitle:"Raffles Place · bank head office",lead:"UOB Plaza is the head office of United Overseas Bank, beside the Singapore River at Raffles Place. Its 280-metre tower, designed by Kenzo Tange, was finished in 1992.",more:["Plans began in 1981 but stopped in 1983 when the property market was weak. Work restarted in 1988, and the 66-storey UOB Plaza One was completed in November 1992. Its look is close to Tange's Tokyo Metropolitan Government Building of 1990.","The shorter UOB Plaza Two was first built in the 1970s as the UOB Building, then given new floors and a matching face by 1995. A 45-metre-high podium on four columns links the two towers and holds the bank's main banking hall. Lee Kuan Yew opened the complex on 6 August 1995."],lookFor:["The podium raised on four columns","UOB Plaza Two, the shorter, older tower","The Singapore River at its foot"],sources:[{title:"UOB Plaza",url:"https://en.wikipedia.org/wiki/UOB_Plaza",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"Two towers, one bank",seconds:90,captions:["UOB Plaza is the head office of United Overseas Bank.","Kenzo Tange designed its 66-storey tower, finished in 1992.","A banking hall sits in a podium held up on four columns.","It opened on 6 August 1995, the bank's 60th birthday."]},tiles:[{value:1992,label:"tower completed",source:{title:"UOB Plaza",url:"https://en.wikipedia.org/wiki/UOB_Plaza",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:280,label:"metres tall",suffix:" m",source:{title:"UOB Plaza",url:"https://en.wikipedia.org/wiki/UOB_Plaza",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:1995,label:"officially opened",source:{title:"UOB Plaza",url:"https://en.wikipedia.org/wiki/UOB_Plaza",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-victoria-theatre-and-concert-hall":{title:["Victoria Theatre","and Concert Hall,","two halls, one clock"],subtitle:"Empress Place · theatre and concert hall",lead:"Two buildings stand side by side on Empress Place. The Town Hall, built between 1855 and 1862, is now Victoria Theatre. The Victoria Memorial Hall, built in memory of Queen Victoria and opened in 1905, is now Victoria Concert Hall.",more:["A 54-metre clock tower joins the two halls. Its clock was set in motion on 1 February 1907. Both buildings are in the Neoclassical style, with tall Corinthian columns and triangular pediments.","After the Second World War, war crime trials were held in the Memorial Hall from 1946 to 1947. In 1980 it reopened as Victoria Concert Hall, home of the new Singapore Symphony Orchestra. A big facelift followed from 2010 to 2014."],lookFor:["A crown on top of the clock tower","The State Crest in the triangular pediments","Oval shields with the letters V, R and I"],sources:[{title:"Victoria Theatre and Victoria Concert Hall",url:"https://www.roots.gov.sg/places/places-landing/places/national-monuments/victoria-theatre-and-concert-hall",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}],clip:{title:"Town Hall to concert hall",seconds:96,captions:["Two halls joined by a 54-metre clock tower.","The Town Hall, now the theatre, was built from 1855 to 1862.","The Memorial Hall for Queen Victoria opened in 1905.","Today both halls host concerts and shows."]},tiles:[{value:1862,label:"Town Hall completed",source:{title:"Victoria Theatre and Victoria Concert Hall",url:"https://www.roots.gov.sg/places/places-landing/places/national-monuments/victoria-theatre-and-concert-hall",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:1905,label:"Memorial Hall opens",source:{title:"Victoria Theatre and Victoria Concert Hall",url:"https://www.roots.gov.sg/places/places-landing/places/national-monuments/victoria-theatre-and-concert-hall",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:54,label:"metre clock tower",source:{title:"Victoria Theatre and Victoria Concert Hall",url:"https://www.roots.gov.sg/places/places-landing/places/national-monuments/victoria-theatre-and-concert-hall",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}}],thenNow:{then:{src:"nearby/cards/sg-victoria-theatre-and-concert-hall-then.webp",alt:"Postcard from the 1930s: the theatre and Memorial Hall with the clock tower between them, cars parked in front",credit:"Unknown author, 1930s · public domain",url:"https://commons.wikimedia.org/wiki/File:Victoria_Theatre_and_Victoria_Memorial_Hall_-_c_1930.jpg"},now:{src:"nearby/cards/sg-victoria-theatre-and-concert-hall-now.webp",alt:"The white front of the two halls and the clock tower seen across the lawn in 2025",credit:"TTangMonuments 2025 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Victoria_Theatre_and_Victoria_Concert_Hall,_with_54m_high_Clock_Tower.jpg"},thenLabel:"1930s",nowLabel:"2025",captions:{then:{lead:"1930s.",text:" A postcard of the two halls and the clock tower."},mid:{lead:"Same front, about 90 years on.",text:" The tower still joins the halls."},now:{lead:"2025.",text:" The halls after the facelift of 2010 to 2014."}}},reviewedAt:"2026-10-29"},"curated:sg-waku-ghin":{title:["Waku Ghin,","a Sydney chef’s","table at Marina Bay"],subtitle:"The Shoppes at Marina Bay Sands · Japanese tasting menu",lead:"Waku Ghin is the Marina Bay Sands restaurant of Tetsuya Wakuda, a Japanese-born chef based in Sydney. It serves a 10-course tasting menu.",more:["Wakuda was born in Hamamatsu, Japan, in 1959 and opened his restaurant Tetsuya in Sydney in 1989. Waku Ghin opened in 2010. Its signature dishes include marinated botan shrimp with sea urchin and caviar.","It won one MICHELIN star in Singapore’s first guide in 2016 and two in 2017. Since 2024 it has held one star."],lookFor:["The 10-seat Chef’s Table","Marina Bay Sands’ three 55-storey towers"],sources:[{title:"Tetsuya Wakuda",url:"https://en.wikipedia.org/wiki/Tetsuya_Wakuda",publisher:"Wikipedia",checkedAt:"2026-10-31"},{title:"List of Michelin-starred restaurants in Singapore",url:"https://en.wikipedia.org/wiki/List_of_Michelin-starred_restaurants_in_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"},{title:"Marina Bay Sands",url:"https://en.wikipedia.org/wiki/Marina_Bay_Sands",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"From Hamamatsu to the bay",seconds:90,captions:["Waku Ghin is chef Tetsuya Wakuda’s restaurant at Marina Bay.","Wakuda, born in Hamamatsu, Japan, made his name in Sydney.","It opened in 2010 and won two MICHELIN stars in 2017.","A signature: botan shrimp with sea urchin and caviar."]},tiles:[{value:2010,label:"opens at Marina Bay Sands",source:{title:"Tetsuya Wakuda",url:"https://en.wikipedia.org/wiki/Tetsuya_Wakuda",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:2017,label:"two MICHELIN stars",source:{title:"Tetsuya Wakuda",url:"https://en.wikipedia.org/wiki/Tetsuya_Wakuda",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:10,label:"seats at the Chef’s Table",source:{title:"Tetsuya Wakuda",url:"https://en.wikipedia.org/wiki/Tetsuya_Wakuda",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-wesley-methodist-church":{title:["Wesley Methodist Church,","red brick","below Fort Canning"],subtitle:"Fort Canning Road · Methodist church",lead:"Wesley Methodist Church is the first Methodist church in Singapore. Its congregation began on 8 February 1885, when about 150 people came to a service at the Town Hall.",more:["In 1907 the government gave the Methodists a hillside site at Fort Canning. The church, designed by David McLeod Craik in a red-brick Gothic style, was dedicated on 4 February 1909. In 1937 it got a Hammond electric organ, the first of its kind in Malaya.","During the Japanese Occupation the building was stripped and used as an ammunition depot. The stained-glass windows had been removed for safekeeping and survived. After repairs the church was rededicated in 1948, and it was extended in the 1970s and 1980s."],lookFor:["Red-brick Gothic front on Fort Canning Road","Stained-glass windows that survived the war","The marble baptismal font, another survivor"],sources:[{title:"Wesley Methodist Church",url:"https://www.roots.gov.sg/places/places-landing/places/surveyed-sites/wesley-methodist-church",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"},{title:"Our History",url:"https://www.wesleymc.org/about-us/our-history",publisher:"Wesley Methodist Church",checkedAt:"2026-10-31"},{title:"Wesley Methodist Church, Singapore",url:"https://en.wikipedia.org/wiki/Wesley_Methodist_Church,_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"The first Methodist church",seconds:95,captions:["The first Methodist service here was in the Town Hall in 1885.","In 1907 the government gave land at Fort Canning.","The church was dedicated on 4 February 1909.","In the war it was an ammunition depot; the glass survived."],poster:{src:"nearby/cards/sg-wesley-methodist-church.webp",alt:"The red-brick Gothic tower of the church, outlined in lights at night",credit:"Sgconlaw 2024 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Wesley_Methodist_Church_at_the_Singapore_Night_Festival_2024.jpg"}},tiles:[{value:1885,label:"first Methodist service",source:{title:"Our History",url:"https://www.wesleymc.org/about-us/our-history",publisher:"Wesley Methodist Church",checkedAt:"2026-10-31"}},{value:1909,label:"church dedicated",source:{title:"Wesley Methodist Church",url:"https://www.roots.gov.sg/places/places-landing/places/surveyed-sites/wesley-methodist-church",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:1937,label:"Malaya's first Hammond organ",source:{title:"Our History",url:"https://www.wesleymc.org/about-us/our-history",publisher:"Wesley Methodist Church",checkedAt:"2026-10-31"}}],thenNow:{then:{src:"nearby/cards/sg-wesley-methodist-church-then.webp",alt:"The church in an old sepia postcard: the Gothic tower, nave and palm trees",credit:"Unknown, old postcard · public domain",url:"https://commons.wikimedia.org/wiki/File:WesleyMethodistChurch-sepiapostcard.jpg"},now:{src:"nearby/cards/sg-wesley-methodist-church-now.webp",alt:"The same tower in 2024, lit at night, with later buildings beside it",credit:"Sgconlaw 2024 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Wesley_Methodist_Church_at_the_Singapore_Night_Festival_2024.jpg"},thenLabel:"Postcard",nowLabel:"2024",captions:{then:{lead:"Old postcard.",text:" The red-brick Gothic tower and nave, among palm trees."},mid:{lead:"Same tower.",text:" The church was extended in the 1970s and 1980s."},now:{lead:"2024.",text:" The tower lit up for the Singapore Night Festival."}},tall:!0},reviewedAt:"2026-10-29"},"curated:sg-west-coast-park":{title:["West Coast Park,","the play centre","of the west"],subtitle:"West Coast Highway · seaside park",lead:"West Coast Park is a large park by the sea in the far west of Queenstown, covering about 50 hectares. NParks calls it the “Play Centre of the West”.",more:["Work on the park began in 1977 on reclaimed land at Pasir Panjang. It was closed in 1998 and rebuilt, and reopened two years later with a sand play area, barbecue pits, a marsh garden and what was then Singapore’s largest playground.","The 3.5-hectare Grand Lawn is a common spot for kite flying. In the quiet Marsh Garden, NParks suggests looking for the White-breasted Waterhen and the Striated Heron."],lookFor:["Kites over the 3.5-hectare Grand Lawn","Waterhens and herons in the Marsh Garden","Sunset and yachts from the lookout point"],sources:[{title:"West Coast Park",url:"https://www.nparks.gov.sg/visit/parks/park-detail/west-coast-park",publisher:"National Parks Board (NParks)",checkedAt:"2026-10-31"},{title:"West Coast Park",url:"https://en.wikipedia.org/wiki/West_Coast_Park",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"A park on reclaimed land",seconds:90,captions:["NParks calls this park the “Play Centre of the West”.","Work on it began in 1977, on reclaimed land at Pasir Panjang.","A quiet Marsh Garden draws herons and waterhens.","Walk to the lookout point to watch the sun set over the sea."],poster:{src:"nearby/cards/west-coast-park.webp",alt:"Sunset over the sea from the shore of West Coast Park, with oil rigs at the port in the distance",credit:"Leongyy02 2022 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Coastal_view_of_West_Coast_Park,_Singapore,_2_May_2022.jpg"}},tiles:[{value:1977,label:"park works begin",source:{title:"West Coast Park",url:"https://en.wikipedia.org/wiki/West_Coast_Park",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:50,label:"park area",suffix:" ha",source:{title:"West Coast Park",url:"https://en.wikipedia.org/wiki/West_Coast_Park",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:9,label:"barbecue pits to book",source:{title:"West Coast Park",url:"https://www.nparks.gov.sg/visit/parks/park-detail/west-coast-park",publisher:"National Parks Board (NParks)",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-yong-fu":{title:["Yong Fu,","Ningbo flavours","with the seasons"],subtitle:"Suntec City · Ningbo cuisine, one MICHELIN star",lead:"Yong Fu is a Ningbo restaurant at Suntec City. It builds its dishes on seasonal seafood and fine ingredients, aiming for the delicate, balanced taste of Ningbo cooking.",more:["The menu and its prices change with the seasons and with what ingredients are available, and the restaurant follows a farm-to-table idea. It says it uses ingredients fully.","It has six private rooms, the largest seating 18 at one table, each with its own tea table. The main dining room can be booked whole for up to 50 guests. In 2026 Yong Fu won one MICHELIN star."],lookFor:["The tea table in each private room","Suntec City’s bronze Fountain of Wealth nearby"],sources:[{title:"Menu",url:"https://www.yongfusg.com/menu",publisher:"Yong Fu",checkedAt:"2026-10-31"},{title:"About",url:"https://www.yongfusg.com/about",publisher:"Yong Fu",checkedAt:"2026-10-31"},{title:"List of Michelin-starred restaurants in Singapore",url:"https://en.wikipedia.org/wiki/List_of_Michelin-starred_restaurants_in_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"},{title:"Suntec City",url:"https://en.wikipedia.org/wiki/Suntec_City",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"Ningbo cooking at Suntec",seconds:90,captions:["Yong Fu cooks the delicate, balanced flavours of Ningbo.","Its dishes start from seasonal seafood and fine ingredients.","The menu and prices change with the seasons.","In 2026 it won its first MICHELIN star in Singapore."],poster:{src:"nearby/cards/yong-fu.webp",alt:"The bronze Fountain of Wealth between Suntec City towers 3 and 4; Yong Fu is in Tower 5 (not the restaurant itself)",credit:"Moheen Reeyad 2023 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Fountain_of_Wealth,_Suntec_City_(111152).jpg"}},tiles:[{value:6,label:"private dining rooms",source:{title:"About",url:"https://www.yongfusg.com/about",publisher:"Yong Fu",checkedAt:"2026-10-31"}},{value:18,label:"guests at the VVIP table",source:{title:"About",url:"https://www.yongfusg.com/about",publisher:"Yong Fu",checkedAt:"2026-10-31"}},{value:2026,label:"first MICHELIN star here",source:{title:"List of Michelin-starred restaurants in Singapore",url:"https://en.wikipedia.org/wiki/List_of_Michelin-starred_restaurants_in_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-yueh-hai-ching":{title:["Yueh Hai Ching,","a Teochew temple","among the towers"],subtitle:"Phillip Street · Teochew temple, national monument",lead:"Yueh Hai Ching is one of Singapore’s oldest Chinese temples, now dwarfed by office towers. Teochew immigrants first prayed to Mazu, goddess of the seas, at a small wood-and-attap shrine on this street.",more:["Ngee Ann Kongsi, set up in 1845 to serve the Teochew community, took over the temple that year. It was rebuilt between 1852 and 1855 with money from the community, using some materials brought from China.","It has two halls side by side, each with its own entrance: one for Mazu and one for Xuan Tian Shang Di, the Teochew patron god. Cantonese devotees called it Mah Miu, the “twin temples”. Emperor Guangxu gave it a plaque reading shu hai xiang yun, in return for 6,000 taels of silver for flood relief in Shandong. After restoration from 2011 to 2014, it won a UNESCO Asia-Pacific Award of Merit."],lookFor:["Dragons and legends in cut porcelain on the roof","Two entrances, one for each hall","Carvings of the Eight Immortals Crossing the Seas"],sources:[{title:"Yueh Hai Ching Temple",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/yueh-hai-ching-temple",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"},{title:"Temple of the Teochews: Yueh Hai Ching Temple",url:"https://culturepaedia.singaporeccc.org.sg/en/communities/temple-of-the-teochews-yueh-hai-ching-temple/",publisher:"Singapore Chinese Cultural Centre (Culturepaedia)",checkedAt:"2026-10-31"},{title:"Yueh Hai Ching Temple",url:"https://en.wikipedia.org/wiki/Yueh_Hai_Ching_Temple",publisher:"Wikipedia",checkedAt:"2026-10-31"}],clip:{title:"Twin temples of the Teochews",seconds:90,captions:["Two halls side by side: one for Mazu, one for Xuan Tian Shang Di.","Teochew migrants first prayed here at a wood-and-attap shrine.","A Qing emperor sent a plaque, for help with floods in Shandong.","Look up: the roof is crowded with cut-porcelain figures."],poster:{src:"nearby/cards/yueh-hai-ching.webp",alt:"The temple front on Phillip Street, its roof lined with porcelain figures, between office towers",credit:"Zairon 2015 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Singapore_Tempel_Yueh_Hai_Ching_1.jpg"}},tiles:[{value:1845,label:"Ngee Ann Kongsi takes charge",source:{title:"Yueh Hai Ching Temple",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/yueh-hai-ching-temple",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:1855,label:"rebuilt temple completed",source:{title:"Yueh Hai Ching Temple",url:"https://www.roots.gov.sg/places/places-landing/Places/national-monuments/yueh-hai-ching-temple",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}},{value:1996,label:"national monument",source:{title:"Temple of the Teochews: Yueh Hai Ching Temple",url:"https://culturepaedia.singaporeccc.org.sg/en/communities/temple-of-the-teochews-yueh-hai-ching-temple/",publisher:"Singapore Chinese Cultural Centre (Culturepaedia)",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"},"curated:sg-zen":{title:["Zén,","a Nordic meal","over three floors"],subtitle:"Bukit Pasoh Road · Nordic tasting menu",lead:"Zén is the Singapore restaurant of Swedish chef Björn Frantzén. It fills three floors of a classic shophouse on Bukit Pasoh Road.",more:["Frantzén was born in Stockholm in 1977. Zén opened late in 2018 and, like his Stockholm restaurant Frantzén, leads guests through three floors. It serves only a tasting menu, and in September 2021 it was awarded three MICHELIN stars.",'Bukit Pasoh Road was nicknamed "the street of the clans", after the close to 30 Chinese clan and cultural associations based here. Its pre-war shophouses date back to the 1920s.'],lookFor:["Clan association signboards on Bukit Pasoh Road","Two- and three-storey art deco shophouses"],sources:[{title:"Restaurant Zén officially opens in Singapore",url:"https://www.frantzengroup.com/restaurant-zen-officially-opens-in-singapore/",publisher:"Frantzén Group",checkedAt:"2026-10-31"},{title:"Björn Frantzén",url:"https://en.wikipedia.org/wiki/Bj%C3%B6rn_Frantz%C3%A9n",publisher:"Wikipedia",checkedAt:"2026-10-31"},{title:"List of Michelin-starred restaurants in Singapore",url:"https://en.wikipedia.org/wiki/List_of_Michelin-starred_restaurants_in_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"},{title:"31 Bukit Pasoh Road (Former New Majestic Hotel)",url:"https://www.roots.gov.sg/places/places-landing/Places/surveyed-sites/31-Bukit-Pasoh-Road-Former-New-Majestic-Hotel",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}],clip:{title:"A meal over three floors",seconds:90,captions:["Zén is the Singapore restaurant of Swedish chef Björn Frantzén.","It opened late in 2018, following his Stockholm restaurant.","The meal moves through three floors of a restored shophouse.","In 2021 it was awarded three MICHELIN stars."],poster:{src:"nearby/cards/sg-zen.webp",alt:"Shophouses along Bukit Pasoh Road, the street where Zén is (not the restaurant itself)",credit:"Jacklee 2013 · CC BY-SA 3.0",url:"https://commons.wikimedia.org/wiki/File:Shophouses_along_Bukit_Pasoh_Road,_Singapore_-_20131130-01.JPG"}},tiles:[{value:2018,label:"Zén opens",source:{title:"Björn Frantzén",url:"https://en.wikipedia.org/wiki/Bj%C3%B6rn_Frantz%C3%A9n",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:2021,label:"three MICHELIN stars",source:{title:"List of Michelin-starred restaurants in Singapore",url:"https://en.wikipedia.org/wiki/List_of_Michelin-starred_restaurants_in_Singapore",publisher:"Wikipedia",checkedAt:"2026-10-31"}},{value:1920,label:"street's shophouses built",suffix:"s",source:{title:"31 Bukit Pasoh Road (Former New Majestic Hotel)",url:"https://www.roots.gov.sg/places/places-landing/Places/surveyed-sites/31-Bukit-Pasoh-Road-Former-New-Majestic-Hotel",publisher:"National Heritage Board (Roots)",checkedAt:"2026-10-31"}}],reviewedAt:"2026-10-29"}},s=e=>`/ui1/nearby/cards/${e}`,t="2026-10-29",o=(e,r,d)=>({title:e,url:r,publisher:d,checkedAt:t}),n=o("Thian Hock Keng","https://roots.gov.sg/places/places-landing/Places/national-monuments/thian-hock-keng","National Heritage Board (Roots)"),l=o("Sri Mariamman Temple","https://www.roots.gov.sg/places/places-landing/Places/national-monuments/sri-mariamman-temple","National Heritage Board (Roots)"),u=o("Jamae Mosque","https://roots.gov.sg/places/places-landing/Places/national-monuments/jamae-mosque","National Heritage Board (Roots)"),m=o("History","https://masjidjamaechulia.sg/index.php/welcome/history","Masjid Jamae (Chulia)"),h=o("About us","https://nus.edu.sg/museum/about-us","NUS Museum"),y=o("Visit","https://nus.edu.sg/museum/visit","NUS Museum"),c=o("Our Story","https://lkcnhm.nus.edu.sg/our-story/","Lee Kong Chian Natural History Museum"),v=o("Museum History","https://lkcnhm.nus.edu.sg/our-story/museum-history/","Lee Kong Chian Natural History Museum"),w=o("Interview with an evolutionary paleobiologist, Dr Emanuel Tschopp","https://lkcnhm.nus.edu.sg/interview-with-an-evolutionary-paleobiologist-dr-emanuel-tschopp/","Lee Kong Chian Natural History Museum"),S=o("Pagoda Street","https://en.wikipedia.org/wiki/Pagoda_Street","Wikipedia"),A=o("Chinatown, Outram","https://en.wikipedia.org/wiki/Chinatown,_Outram","Wikipedia"),b={"curated:sg-thian-hock-keng-temple":{title:i.title,subtitle:i.subtitle.replace(/^天福宫 · /,""),clip:{title:i.video.title,seconds:i.video.duration,captions:[...i.video.captions],poster:a.thianHockKeng},tiles:[{value:1839,label:"building starts",source:n},{value:1842,label:"temple completed",source:n},{value:1973,label:"national monument",source:n}],thenNow:{then:i.thenNow.then,now:i.thenNow.now,thenLabel:"c.1890",nowLabel:"2006",captions:i.thenNow.captions},lead:i.lead,more:i.more,lookFor:i.lookFor.map(e=>e.text),sources:[n],story:{path:"/place/chinatown/monument",label:"Chinatown story card"},reviewedAt:t},"curated:sg-sri-mariamman-temple":{title:["Sri Mariamman Temple,","for the goddess","of rain and healing"],subtitle:"South Bridge Road · Hindu temple",clip:{title:"A gateway of gods",seconds:100,captions:["Naraina Pillai, a clerk from Penang, founded the temple.","A wood-and-attap temple stood here by 1827.","In 1925 a five-tiered gopuram replaced the first tower.","Its goddess is linked to rain and to curing disease."]},tiles:[{value:1827,label:"wood-and-attap temple",source:l},{value:1843,label:"oldest brick parts (about)",source:l},{value:1925,label:"five-tiered gopuram",source:l}],thenNow:{tall:!0,then:{src:s("sri-mariamman-1895-1906.webp"),alt:"Postcard of the temple’s gateway tower between 1895 and 1906, before it was replaced",credit:"KITLV 1404868, 1895–1906 · public domain",url:"https://commons.wikimedia.org/wiki/File:KITLV_-_1404868_-_Singapore._Hindu_Temple._-_1895-1906.tif"},now:{src:s("sri-mariamman-2023.webp"),alt:"The gateway tower in 2023, covered in brightly painted sculptures of Hindu deities",credit:"Chainwit. 2023 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Gopuram_-_Sri_Mariamman_Temple_Singapore_(2023)_-_img_01.jpg"},thenLabel:"1895–1906",nowLabel:"2023",captions:{then:{lead:"1895–1906.",text:" The first gopuram, three tiers high and plainer in design."},mid:{lead:"Same gateway, two towers.",text:" The old one was replaced in 1925."},now:{lead:"2023.",text:" Five tiers of brightly painted Hindu deities."}}},lead:"Sri Mariamman Temple was founded by Naraina Pillai, a government clerk from Penang. A wood-and-attap temple stood on South Bridge Road by 1827.",more:["The oldest parts of today’s brick temple date from around 1843. In 1925 the first three-tiered gopuram was replaced by the five-tiered tower you see now, with brightly painted sculptures of Hindu deities.","Its goddess, Sri Mariamman, is linked to the life-giving rain and is prayed to for curing epidemic diseases such as cholera. Each October or November, at the Theemithi festival, male devotees walk barefoot across burning charcoal."],lookFor:["Cows, sacred to Hindus, on the boundary walls","Colourful domes (vimanam) over the shrines","The painted ceiling along the main hall"],sources:[l],reviewedAt:t},"curated:sg-masjid-jamae-chulia":{title:["Masjid Jamae,","twin minarets on","South Bridge Road"],clip:{title:"Built by Chulia traders",seconds:96,captions:["Chulia traders from South India built a mosque here around 1826.","The mosque you see went up between 1830 and 1835.","Two eight-sided minarets frame the main gate.","Look for green Chinese tiles under the windows."]},tiles:[{value:1826,label:"first mosque (about)",source:u},{value:1835,label:"today’s mosque done",source:u},{value:1974,label:"national monument",source:m}],thenNow:{then:{src:s("jamae-c1900.webp"),alt:"South Bridge Road around 1900: rickshaws in the street, the mosque’s minarets on the right and the temple tower beyond",credit:"G.R. Lambert & Co., c.1900 · public domain",url:"https://commons.wikimedia.org/wiki/File:Photographic_Views_of_Singapore_Plate_02_South_Bridge_Road.jpg"},now:{src:s("jamae-2018.webp"),alt:"The same stretch of South Bridge Road in 2018, with the green minarets, shophouses and festive lanterns",credit:"Bahnfrend 2018 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:South_Bridge_Road,_Singapore,_2018_(05).jpg"},thenLabel:"c.1900",nowLabel:"2018",captions:{then:{lead:"c.1900.",text:" Rickshaws on South Bridge Road, the minarets on the right and the temple tower beyond."},mid:{lead:"Same street, over a century apart.",text:" The minarets still mark the mosque."},now:{lead:"2018.",text:" Shophouses and festive lanterns along the same road."}}},lead:"Masjid Jamae was built by the Chulias, Tamil Muslim traders and moneychangers from South India’s Coromandel Coast. Their first mosque here went up around 1826, and the present one between 1830 and 1835.",more:["Its design mixes Indo-Islamic and Neoclassical styles. Above the gate, a small palace-like front with tiny doors and windows joins the two minarets, and the call to prayer was once made from the balcony there.","It is one of the few mosques in Singapore that offers religious classes in Tamil, and it has room for about 1,500 worshippers."],lookFor:["Seven levels of arched niches on each minaret","Green-glazed Chinese tiles below the windows","Tuscan columns and pilasters, a European touch"],sources:[u,m],reviewedAt:t},"curated:sg-pagoda-street-trengganu-street":{clip:{title:"A street named after a temple",seconds:90,captions:["Pagoda Street is named after the temple’s gopuram nearby.","In the early 1900s its shophouses were lodgings for coolies.","Those lodging houses closed after the 1930s.","Today it is a car-free street lined with shops."]},sources:[S,A],story:{path:"/place/chinatown/festival",label:"Chinatown story card"},reviewedAt:t},"curated:sg-nus-museum":{title:["NUS Museum,","art collections","on the Kent Ridge campus"],clip:{title:"Four collections",seconds:90,poster:{src:s("nus-museum.webp"),alt:"The NUS Museum’s outside wall with its name, beside Kent Ridge heritage trail signs",credit:"Ralff Nestor Nacor 2023 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:NUS_Museum,_Singaporean.jpg"},captions:["Its story starts in 1955, at the University of Malaya.","Four collections hold more than 8,000 items.","They include works by the sculptor Ng Eng Teng.","Open Tuesday to Saturday, 10 am to 6 pm."]},tiles:[{value:1955,label:"University of Malaya Art Museum",source:h},{value:8e3,suffix:"+",grouped:!0,label:"items",source:h},{value:4,label:"collections",source:h}],lead:"The NUS Museum goes back to the University of Malaya Art Museum, set up in 1955. Today its four collections hold more than 8,000 items, including works by Ng Eng Teng and the Peranakan collection of the Baba House.",sources:[h,y],reviewedAt:t},"curated:sg-lee-kong-chian-natural-history":{title:["Singapore’s only","natural history museum"],clip:{title:"Prince, Apollonia and Twinky",seconds:104,poster:{src:s("lkcnhm-sauropods.webp"),alt:"The three sauropod dinosaur skeletons in the museum’s gallery under blue light",credit:"Jacklee 2015 · CC BY-SA 4.0",url:"https://commons.wikimedia.org/wiki/File:Diplodocid_sauropod_skeletons,_Lee_Kong_Chian_Natural_History_Museum,_Singapore_-_20150808-01.jpg"},captions:["This is Singapore’s only natural history museum.","It keeps over a million specimens from Southeast Asia.","Its three sauropods are Prince, Apollonia and Twinky.","The museum’s story goes back to the 1870s."]},tiles:[{value:3,label:"sauropod dinosaurs",source:w},{value:1,suffix:"M+",label:"specimens and records",source:c},{value:1870,suffix:"s",label:"history begins",source:c}],lead:"The Lee Kong Chian Natural History Museum is Singapore’s only natural history museum. Its rock-shaped building at NUS holds over a million specimens, field notes, drawings and photographs from Southeast Asia.",more:["Its history goes back to the 1870s. In the gallery, the three sauropod dinosaurs Prince, Apollonia and Twinky are still used in research, not just for display.","Heads-up: the Mammal Zone closes for renovation from late November, to reopen with a new look in 2027."],sources:[c,v,w],reviewedAt:t},"curated:sg-tian-tian-hainanese-chicken-rice":{sources:[],order:"chicken-rice",reviewedAt:t},"curated:sg-maxwell-food-centre":{sources:[],order:"kopi",reviewedAt:t},"curated:sg-chinatown-complex-food-centre":{sources:[],order:"kopi",reviewedAt:t},"curated:sg-lim-chee-guan-new-bridge-road":{sources:[],story:{path:"/place/chinatown/food",label:"Chinatown story card: bak kwa"},reviewedAt:t},"curated:sg-the-spread-nus":{sources:[],story:{path:"/place/berlin-wall-fragments/food",label:"Berlin Wall story card: lunch"},reviewedAt:t},"curated:sg-berlin-wall-fragments-utown":{sources:[],story:{path:"/place/berlin-wall-fragments/monument",label:"Berlin Wall story card"},reviewedAt:t}},p=e=>({...e,src:s(e.src.replace(/^nearby\/cards\//,""))}),C=e=>({...e,clip:e.clip&&{...e.clip,poster:e.clip.poster&&p(e.clip.poster)},thenNow:e.thenNow&&{...e.thenNow,then:p(e.thenNow.then),now:p(e.thenNow.now)}});function T(e,r){if(!e||!r)return r??e;const d=Object.fromEntries(Object.entries(r).filter(([k,f])=>f!==void 0&&k!=="sources"));return{...e,...d,sources:[...e.sources,...r.sources]}}const _=Object.fromEntries([...new Set([...Object.keys(g),...Object.keys(b)])].map(e=>{const r=g[e];return[e,T(r&&C(r),b[e])]}));function B(e){return _[e]}export{_ as P,i as T,B as p};
